begin;
insert into private.quiz_question_bank(
 question_id,revision,learning_language_code,translation_language_code,
 source_lesson_id,topic_id,difficulty,prompt_learning,prompt_translation,options,
 correct_option_id,explanation_learning,explanation_translation,status,question_type,
 answer_language_code,learning_objective_id,approved_at
) values
('quiz-ms-en-b001',1,'ms','en','ms-b-greetings','ms-greetings','beginner','Anda tiba di kelas pada pukul 8.00 pagi. Apakah sapaan yang paling sesuai?','You arrive in class at 8:00 a.m. Which greeting is most appropriate?','[{"id":"a","learning_text":"Selamat pagi","translation_text":"Good morning"},{"id":"b","learning_text":"Selamat malam","translation_text":"Good night"},{"id":"c","learning_text":"Selamat tinggal","translation_text":"Goodbye"},{"id":"d","learning_text":"Sama-sama","translation_text":"You''re welcome"}]'::jsonb,'a','“Selamat pagi” digunakan pada waktu pagi.','“Selamat pagi” is used in the morning.','approved','knowledge','ms','greetings-in-context',pg_catalog.now()),
('quiz-ms-en-b002',1,'ms','en','ms-b-greetings','ms-greetings','beginner','Seseorang mengucapkan “Terima kasih” selepas anda membantunya. Apakah jawapan yang sesuai?','Someone says “Terima kasih” after you help them. What is an appropriate reply?','[{"id":"a","learning_text":"Sama-sama","translation_text":"You''re welcome"},{"id":"b","learning_text":"Apa khabar?","translation_text":"How are you?"},{"id":"c","learning_text":"Selamat pagi","translation_text":"Good morning"},{"id":"d","learning_text":"Maafkan saya","translation_text":"Forgive me"}]'::jsonb,'a','“Sama-sama” ialah balasan lazim untuk ucapan terima kasih.','“Sama-sama” is a common response to thanks.','approved','knowledge','ms','polite-responses',pg_catalog.now()),
('quiz-ms-en-b003',1,'ms','en','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang menyatakan tempat tinggal seseorang sekarang.','Choose the sentence that states where someone currently lives.','[{"id":"a","learning_text":"Saya tinggal di Ipoh.","translation_text":"I live in Ipoh."},{"id":"b","learning_text":"Saya berasal dari Ipoh.","translation_text":"I come from Ipoh."},{"id":"c","learning_text":"Saya pergi ke Ipoh.","translation_text":"I am going to Ipoh."},{"id":"d","learning_text":"Saya suka Ipoh.","translation_text":"I like Ipoh."}]'::jsonb,'a','“Saya tinggal di …” menyatakan tempat seseorang menetap sekarang.','“Saya tinggal di …” states where someone lives now.','approved','knowledge','ms','introducing-personal-details',pg_catalog.now()),
('quiz-ms-en-b004',1,'ms','en','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Dalam ayat “Murid itu membaca buku”, frasa manakah menjadi subjek?','In “Murid itu membaca buku”, which phrase is the subject?','[{"id":"a","learning_text":"Murid itu","translation_text":"That pupil"},{"id":"b","learning_text":"membaca","translation_text":"reads"},{"id":"c","learning_text":"buku","translation_text":"book"},{"id":"d","learning_text":"membaca buku","translation_text":"reads a book"}]'::jsonb,'a','“Murid itu” ialah perkara yang diperkatakan, maka frasa itu subjek.','“Murid itu” is what the sentence is about, so it is the subject.','approved','knowledge','ms','subject-predicate-structure',pg_catalog.now()),
('quiz-ms-en-b006',1,'ms','en','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Pilih kata kerja berawalan meN- yang terbentuk dengan betul daripada kata dasar “tulis”.','Choose the correctly formed meN- verb derived from “tulis”.','[{"id":"a","learning_text":"menulis","translation_text":"to write"},{"id":"b","learning_text":"metulis","translation_text":"non-standard form"},{"id":"c","learning_text":"memtulis","translation_text":"incorrect prefix form"},{"id":"d","learning_text":"mengtulis","translation_text":"incorrect consonant pattern"}]'::jsonb,'a','Bentuk standard ialah “menulis”.','The standard form is “menulis”.','approved','knowledge','ms','meN-prefix-forms',pg_catalog.now()),
('quiz-ms-en-b007',1,'ms','en','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Pilih penjodoh bilangan yang sesuai: “seekor ___”.','Choose the suitable classifier phrase: “seekor ___”.','[{"id":"a","learning_text":"kucing","translation_text":"cat"},{"id":"b","learning_text":"pensel","translation_text":"pencil"},{"id":"c","learning_text":"buku","translation_text":"book"},{"id":"d","learning_text":"meja","translation_text":"table"}]'::jsonb,'a','“Ekor” digunakan sebagai penjodoh bilangan bagi haiwan seperti kucing.','“Ekor” is used as a classifier for animals such as cats.','approved','knowledge','ms','classifiers-for-animals',pg_catalog.now()),
('quiz-ms-en-b008',1,'ms','en','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah fungsi kata ganda “buku-buku” dalam ayat biasa?','What does the reduplicated form “buku-buku” usually indicate?','[{"id":"a","learning_text":"Lebih daripada sebuah buku","translation_text":"More than one book"},{"id":"b","learning_text":"Sebuah buku yang kecil","translation_text":"A small book"},{"id":"c","learning_text":"Buku yang baharu","translation_text":"A new book"},{"id":"d","learning_text":"Buku kepunyaan guru","translation_text":"The teacher''s book"}]'::jsonb,'a','Penggandaan penuh “buku-buku” lazimnya menandakan bilangan jamak.','Full reduplication “buku-buku” commonly marks plurality.','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-en-b009',1,'ms','en','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Lengkapkan ayat dengan bentuk kata kerja yang tepat: “Kakak ___ surat itu.” (tulis)','Complete the sentence with the correct verb form: “Kakak ___ surat itu.” (write)','[{"id":"a","learning_text":"menulis","translation_text":"writes"},{"id":"b","learning_text":"menuliskan","translation_text":"writes it down"},{"id":"c","learning_text":"ditulis","translation_text":"is written"},{"id":"d","learning_text":"tertulis","translation_text":"written accidentally"}]'::jsonb,'a','Dalam ayat aktif ini, “menulis” ialah kata kerja yang sesuai.','In this active sentence, “menulis” is the suitable verb.','approved','knowledge','ms','meN-prefix-context',pg_catalog.now()),
('quiz-ms-en-b010',1,'ms','en','ms-a-ragam-bahasa','ms-register','advanced','Anda menulis e-mel rasmi kepada pihak pentadbiran. Pilih pembuka permintaan yang paling sesuai.','You are writing a formal email to an administrative office. Choose the most suitable request opening.','[{"id":"a","learning_text":"Saya ingin memohon maklumat lanjut berkenaan perkara tersebut.","translation_text":"I would like to request further information about the matter."},{"id":"b","learning_text":"Oi, bagi tahu saya pasal benda itu.","translation_text":"Hey, tell me about that thing."},{"id":"c","learning_text":"Kau kena jawab sekarang.","translation_text":"You have to answer now."},{"id":"d","learning_text":"Aku nak tahu benda tu.","translation_text":"I want to know that thing."}]'::jsonb,'a','Ungkapan “Saya ingin memohon…” mengekalkan nada formal dan sopan.','“Saya ingin memohon…” maintains a formal and courteous tone.','approved','knowledge','ms','formal-register-choice',pg_catalog.now()),
('quiz-ms-en-b011',1,'ms','en','ms-a-wacana-penanda','ms-discourse-markers','advanced','Pilih penanda wacana yang paling tepat untuk menunjukkan pertentangan: “Cadangan itu menjimatkan kos. ___, pelaksanaannya memerlukan masa.”','Choose the best discourse marker to show contrast: “The proposal saves costs. ___, its implementation takes time.”','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"However"},{"id":"b","learning_text":"Selain itu","translation_text":"Furthermore"},{"id":"c","learning_text":"Seterusnya","translation_text":"Next"},{"id":"d","learning_text":"Sebagai contoh","translation_text":"For example"}]'::jsonb,'a','“Walau bagaimanapun” memperkenalkan maklumat yang berbeza atau bertentangan.','“Walau bagaimanapun” introduces contrasting information.','approved','knowledge','ms','discourse-connector-contrast',pg_catalog.now()),
('quiz-ms-en-b012',1,'ms','en','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling jelas dan gramatis untuk laporan rasmi.','Choose the clearest and most grammatical sentence for a formal report.','[{"id":"a","learning_text":"Pihak sekolah akan mengadakan mesyuarat pada hari Isnin.","translation_text":"The school will hold a meeting on Monday."},{"id":"b","learning_text":"Sekolah pihak Isnin mesyuarat akan mengadakan.","translation_text":"School side Monday meeting will hold."},{"id":"c","learning_text":"Mesyuarat akan pihak sekolah hari Isnin mengadakan.","translation_text":"Meeting will school Monday hold."},{"id":"d","learning_text":"Pada Isnin mesyuarat sekolah pihak mengadakan akan.","translation_text":"On Monday meeting school side hold will."}]'::jsonb,'a','Ayat pertama mempunyai susunan subjek, predikat dan keterangan yang jelas.','The first sentence has a clear subject, predicate and time expression.','approved','knowledge','ms','editing-agreement-and-clarity',pg_catalog.now()),
('quiz-ms-en-b005',1,'ms','en','ms-a-source-credibility','ms-topic-source-credibility','advanced','Apakah tindakan paling wajar apabila dua sumber memberikan angka yang berbeza tentang perkara yang sama?','What is the most appropriate action when two sources give different figures about the same issue?','[{"id":"a","learning_text":"Semak kaedah, tarikh dan sumber data asal.","translation_text":"Check the method, date and original data source."},{"id":"b","learning_text":"Pilih angka yang paling besar.","translation_text":"Choose the largest figure."},{"id":"c","learning_text":"Abaikan kedua-dua sumber.","translation_text":"Ignore both sources."},{"id":"d","learning_text":"Gabungkan angka tanpa menyemak.","translation_text":"Combine the figures without checking."}]'::jsonb,'a','Angka perlu dibandingkan berdasarkan kaedah dan sumber asal yang boleh disemak.','Figures should be compared using verifiable methods and original sources.','approved','knowledge','ms','verify-claim-with-source',pg_catalog.now()),
('quiz-ms-en-b013',1,'ms','en','ms-b-greetings','ms-greetings','beginner','Pilih balasan sopan yang sesuai untuk “Terima kasih”.','Choose a suitable polite reply to “Terima kasih”.','[{"id":"a","learning_text":"Sama-sama","translation_text":"You''re welcome"},{"id":"b","learning_text":"Maafkan saya","translation_text":"I''m sorry"},{"id":"c","learning_text":"Selamat tinggal","translation_text":"Goodbye"},{"id":"d","learning_text":"Apa khabar?","translation_text":"How are you?"}]'::jsonb,'a','“Sama-sama” ialah balasan lazim untuk ucapan terima kasih.','“Sama-sama” is the conventional reply to thanks.','approved','knowledge','ms','greeting-choice',pg_catalog.now()),
('quiz-ms-en-b014',1,'ms','en','ms-b-personal-information','ms-personal-information','beginner','Ayat manakah yang betul untuk menyatakan tempat tinggal anda?','Which sentence correctly tells someone where you live?','[{"id":"a","learning_text":"Saya tinggal di Ipoh.","translation_text":"I live in Ipoh."},{"id":"b","learning_text":"Saya berasal pada Ipoh.","translation_text":"I originate at Ipoh."},{"id":"c","learning_text":"Nama saya di Ipoh.","translation_text":"My name is in Ipoh."},{"id":"d","learning_text":"Saya umur Ipoh.","translation_text":"I age Ipoh."}]'::jsonb,'a','“Saya tinggal di…” digunakan untuk menyatakan tempat tinggal.','“Saya tinggal di…” states where a person lives.','approved','knowledge','ms','residence-statement',pg_catalog.now()),
('quiz-ms-en-b015',1,'ms','en','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Pilih ayat yang mempunyai susunan subjek–kata kerja–objek yang jelas.','Choose the sentence with a clear subject–verb–object order.','[{"id":"a","learning_text":"Aina membaca buku.","translation_text":"Aina reads a book."},{"id":"b","learning_text":"Membaca Aina buku.","translation_text":"Reads Aina book."},{"id":"c","learning_text":"Buku membaca Aina.","translation_text":"Book reads Aina."},{"id":"d","learning_text":"Aina buku membaca.","translation_text":"Aina book reads."}]'::jsonb,'a','Subjek “Aina” hadir sebelum kata kerja “membaca” dan objek “buku”.','The subject “Aina” comes before the verb “membaca” and object “buku”.','approved','knowledge','ms','simple-word-order',pg_catalog.now()),
('quiz-ms-en-b016',1,'ms','en','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Ungkapan manakah yang sopan untuk meminta bantuan?','Which expression is a polite way to ask for help?','[{"id":"a","learning_text":"Boleh saya minta bantuan?","translation_text":"May I ask for help?"},{"id":"b","learning_text":"Kamu mesti buat sekarang.","translation_text":"You must do it now."},{"id":"c","learning_text":"Pergi dari sini.","translation_text":"Go away."},{"id":"d","learning_text":"Saya tidak peduli.","translation_text":"I do not care."}]'::jsonb,'a','“Boleh saya…” melembutkan permintaan dan menjadikannya lebih sopan.','“Boleh saya…” softens a request and makes it polite.','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-en-b017',1,'ms','en','ms-b-community-places','ms-topic-community-places','beginner','Di manakah anda biasanya meminjam buku?','Where would you usually borrow a book?','[{"id":"a","learning_text":"Perpustakaan","translation_text":"Library"},{"id":"b","learning_text":"Balai bomba","translation_text":"Fire station"},{"id":"c","learning_text":"Klinik","translation_text":"Clinic"},{"id":"d","learning_text":"Pasar","translation_text":"Market"}]'::jsonb,'a','Perpustakaan ialah tempat orang meminjam buku.','A library is a place where people can borrow books.','approved','knowledge','ms','community-place-vocabulary',pg_catalog.now()),
('quiz-ms-en-b018',1,'ms','en','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih kata kerja yang melengkapkan: “Saya ___ sebelum pergi ke sekolah.”','Choose the verb that completes: “Saya ___ sebelum pergi ke sekolah.”','[{"id":"a","learning_text":"bersarapan","translation_text":"have breakfast"},{"id":"b","learning_text":"semalam","translation_text":"yesterday"},{"id":"c","learning_text":"cantik","translation_text":"beautiful"},{"id":"d","learning_text":"kerana","translation_text":"because"}]'::jsonb,'a','“Bersarapan” bermaksud makan sarapan sebelum ke sekolah.','“Bersarapan” means to have breakfast, an activity before school.','approved','knowledge','ms','daily-activity-verb',pg_catalog.now()),
('quiz-ms-en-b019',1,'ms','en','ms-b-family-and-people','ms-family-and-people','beginner','Apakah maksud “abang” dalam hubungan kekeluargaan?','What does “abang” usually mean?','[{"id":"a","learning_text":"Saudara lelaki yang lebih tua","translation_text":"Older brother"},{"id":"b","learning_text":"Saudara perempuan yang lebih muda","translation_text":"Younger sister"},{"id":"c","learning_text":"Nenek","translation_text":"Grandmother"},{"id":"d","learning_text":"Bapa saudara","translation_text":"Uncle"}]'::jsonb,'a','“Abang” merujuk kepada saudara lelaki yang lebih tua.','“Abang” refers to an older brother.','approved','knowledge','ms','family-relationship',pg_catalog.now()),
('quiz-ms-en-b020',1,'ms','en','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Frasa manakah yang betul untuk bermaksud “segelas air”?','Which phrase correctly means “a glass of water”?','[{"id":"a","learning_text":"Segelas air","translation_text":"A glass of water"},{"id":"b","learning_text":"Seekor air","translation_text":"An animal of water"},{"id":"c","learning_text":"Sebatang air","translation_text":"A stick of water"},{"id":"d","learning_text":"Sebiji air","translation_text":"A seed of water"}]'::jsonb,'a','“Segelas” ialah penjodoh bilangan untuk air dalam gelas.','“Segelas” is the classifier phrase used for a glassful.','approved','knowledge','ms','food-order-classifier',pg_catalog.now()),
('quiz-ms-en-b021',1,'ms','en','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Ayat manakah yang menyatakan bermain badminton sebagai hobi?','Which sentence describes playing badminton as a hobby?','[{"id":"a","learning_text":"Hobi saya bermain badminton.","translation_text":"My hobby is playing badminton."},{"id":"b","learning_text":"Saya badminton sangat.","translation_text":"I badminton very."},{"id":"c","learning_text":"Badminton saya kerana.","translation_text":"Badminton me because."},{"id":"d","learning_text":"Hobi bermain saya badminton.","translation_text":"Hobby playing my badminton."}]'::jsonb,'a','“Hobi saya…” digunakan untuk memperkenalkan aktiviti kegemaran.','“Hobi saya…” introduces an activity someone enjoys.','approved','knowledge','ms','hobby-expression',pg_catalog.now()),
('quiz-ms-en-b022',1,'ms','en','ms-b-home-and-household','ms-topic-home-and-household','beginner','Ruang manakah yang biasanya digunakan untuk memasak?','Which room is normally used for cooking?','[{"id":"a","learning_text":"Dapur","translation_text":"Kitchen"},{"id":"b","learning_text":"Bilik tidur","translation_text":"Bedroom"},{"id":"c","learning_text":"Bilik mandi","translation_text":"Bathroom"},{"id":"d","learning_text":"Ruang tamu","translation_text":"Living room"}]'::jsonb,'a','“Dapur” ialah ruang untuk menyediakan dan memasak makanan.','“Dapur” is the kitchen.','approved','knowledge','ms','room-vocabulary',pg_catalog.now()),
('quiz-ms-en-b023',1,'ms','en','ms-b-places-and-directions','ms-places-and-directions','beginner','Apakah arahan “belok kiri”?','What does “belok kiri” tell someone to do?','[{"id":"a","learning_text":"Belok ke kiri","translation_text":"Turn left"},{"id":"b","learning_text":"Belok ke kanan","translation_text":"Turn right"},{"id":"c","learning_text":"Jalan terus","translation_text":"Go straight"},{"id":"d","learning_text":"Berhenti di sini","translation_text":"Stop here"}]'::jsonb,'a','“Kiri” bermaksud sebelah kiri; “belok kiri” ialah arahan membelok ke kiri.','“Kiri” means left, so “belok kiri” means turn left.','approved','knowledge','ms','direction-instruction',pg_catalog.now()),
('quiz-ms-en-b024',1,'ms','en','ms-b-shopping-and-prices','ms-shopping-and-prices','beginner','Soalan manakah yang bertanya tentang harga sesuatu barang?','Which question asks how much an item costs?','[{"id":"a","learning_text":"Berapakah harga barang ini?","translation_text":"How much does this item cost?"},{"id":"b","learning_text":"Di manakah barang ini?","translation_text":"Where is this item?"},{"id":"c","learning_text":"Siapakah membeli barang ini?","translation_text":"Who bought this item?"},{"id":"d","learning_text":"Bilakah barang ini tiba?","translation_text":"When did this item arrive?"}]'::jsonb,'a','“Berapakah harga…” ialah cara biasa untuk bertanya tentang harga.','“Berapakah harga…” is a standard way to ask for a price.','approved','knowledge','ms','asking-price',pg_catalog.now()),
('quiz-ms-en-b025',1,'ms','en','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Perkataan manakah yang menggunakan awalan meN- dengan betul bagi kata dasar “baca”?','Which word correctly uses the meN- prefix with “baca”?','[{"id":"a","learning_text":"membaca","translation_text":"to read / reads"},{"id":"b","learning_text":"membacaan","translation_text":"reading (noun)"},{"id":"c","learning_text":"dibaca","translation_text":"is read"},{"id":"d","learning_text":"bacaan","translation_text":"reading material"}]'::jsonb,'a','Kata dasar “baca” berubah menjadi “membaca” apabila menerima awalan meN-.','The root “baca” becomes “membaca” with the meN- prefix.','approved','knowledge','ms','men-prefix-verb',pg_catalog.now()),
('quiz-ms-en-b026',1,'ms','en','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah yang sesuai untuk tiga ekor kucing?','Which classifier is appropriate for three cats?','[{"id":"a","learning_text":"Tiga ekor kucing","translation_text":"Three cats"},{"id":"b","learning_text":"Tiga batang kucing","translation_text":"Three sticks of cats"},{"id":"c","learning_text":"Tiga helai kucing","translation_text":"Three sheets of cats"},{"id":"d","learning_text":"Tiga biji kucing","translation_text":"Three seeds of cats"}]'::jsonb,'a','Gunakan “ekor” untuk haiwan.','Use “ekor” for animals.','approved','knowledge','ms','animal-classifier',pg_catalog.now()),
('quiz-ms-en-b027',1,'ms','en','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah yang dirujuk oleh perkataan “kanak-kanak”?','What does “kanak-kanak” refer to?','[{"id":"a","learning_text":"Kanak-kanak","translation_text":"Children"},{"id":"b","learning_text":"Orang dewasa","translation_text":"An adult"},{"id":"c","learning_text":"Bilik darjah","translation_text":"A classroom"},{"id":"d","learning_text":"Rumah keluarga","translation_text":"A family house"}]'::jsonb,'a','“Kanak-kanak” ialah kata ganda yang merujuk kepada golongan kanak-kanak.','“Kanak-kanak” is a reduplicated form referring to children.','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-en-b028',1,'ms','en','ms-i-aspek-perbuatan','ms-aspect','intermediate','Perkataan manakah yang menunjukkan perbuatan sedang berlaku?','Which word indicates an action is happening now?','[{"id":"a","learning_text":"sedang","translation_text":"currently / in the process of"},{"id":"b","learning_text":"telah","translation_text":"already"},{"id":"c","learning_text":"akan","translation_text":"will"},{"id":"d","learning_text":"pernah","translation_text":"ever"}]'::jsonb,'a','“Sedang” menandakan perbuatan yang sedang berlangsung.','“Sedang” marks an action in progress.','approved','knowledge','ms','ongoing-aspect',pg_catalog.now()),
('quiz-ms-en-b029',1,'ms','en','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang betul: “Buku itu ___ atas meja.”','Choose the correct preposition: “Buku itu ___ atas meja.”','[{"id":"a","learning_text":"di","translation_text":"on / at"},{"id":"b","learning_text":"ke","translation_text":"to"},{"id":"c","learning_text":"daripada","translation_text":"from"},{"id":"d","learning_text":"kepada","translation_text":"to (recipient)"}]'::jsonb,'a','“Di” menandakan tempat; “di atas meja” bermaksud berada di atas meja.','“Di” marks a location; “di atas meja” means on the table.','approved','knowledge','ms','location-preposition',pg_catalog.now()),
('quiz-ms-en-b030',1,'ms','en','ms-i-kata-hubung','ms-conjunctions','intermediate','Kata hubung manakah paling sesuai: “___ hujan, mereka meneruskan perjalanan.”','Which conjunction best completes: “___ hujan, mereka meneruskan perjalanan.”','[{"id":"a","learning_text":"Walaupun","translation_text":"Although"},{"id":"b","learning_text":"Kerana","translation_text":"Because"},{"id":"c","learning_text":"Supaya","translation_text":"So that"},{"id":"d","learning_text":"Sebelum","translation_text":"Before"}]'::jsonb,'a','“Walaupun” memperkenalkan maksud pertentangan atau konsesi.','“Walaupun” introduces a concession or contrast.','approved','knowledge','ms','contrast-conjunction',pg_catalog.now()),
('quiz-ms-en-b031',1,'ms','en','ms-i-perbandingan','ms-comparison','intermediate','Pilih bentuk perbandingan yang betul: “Menara A lebih tinggi ___ Menara B.”','Choose the correct comparison: “Menara A lebih tinggi ___ Menara B.”','[{"id":"a","learning_text":"daripada","translation_text":"than"},{"id":"b","learning_text":"kepada","translation_text":"to (recipient)"},{"id":"c","learning_text":"dengan","translation_text":"with"},{"id":"d","learning_text":"untuk","translation_text":"for"}]'::jsonb,'a','Gunakan “lebih … daripada” untuk membandingkan dua perkara.','Use “lebih … daripada” to compare two things.','approved','knowledge','ms','comparative-structure',pg_catalog.now()),
('quiz-ms-en-b032',1,'ms','en','ms-i-kata-penguat','ms-intensifiers','intermediate','Perkataan manakah menguatkan kata adjektif dalam “Cuaca hari ini ___ panas”?','Which word intensifies the adjective in “Cuaca hari ini ___ panas”?','[{"id":"a","learning_text":"sangat","translation_text":"very"},{"id":"b","learning_text":"tetapi","translation_text":"but"},{"id":"c","learning_text":"kerana","translation_text":"because"},{"id":"d","learning_text":"sejak","translation_text":"since"}]'::jsonb,'a','“Sangat” menguatkan kata adjektif “panas”.','“Sangat” strengthens the adjective “panas”.','approved','knowledge','ms','intensifier-choice',pg_catalog.now()),
('quiz-ms-en-b033',1,'ms','en','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Kata hubung manakah yang betul untuk menggabungkan idea “Saya belajar” dan “adik bermain”?','Which conjunction correctly joins the ideas “Saya belajar” and “adik bermain”?','[{"id":"a","learning_text":"manakala","translation_text":"while / whereas"},{"id":"b","learning_text":"kerana","translation_text":"because"},{"id":"c","learning_text":"supaya","translation_text":"so that"},{"id":"d","learning_text":"sehingga","translation_text":"until"}]'::jsonb,'a','“Manakala” boleh menghubungkan dua klausa yang berbeza atau selari.','“Manakala” can connect two contrasting or parallel clauses.','approved','knowledge','ms','compound-clause',pg_catalog.now()),
('quiz-ms-en-b034',1,'ms','en','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Penanda manakah yang jelas memperkenalkan kesan?','Which connector clearly introduces a result?','[{"id":"a","learning_text":"Oleh itu","translation_text":"Therefore"},{"id":"b","learning_text":"Walaupun","translation_text":"Although"},{"id":"c","learning_text":"Sebaliknya","translation_text":"Conversely"},{"id":"d","learning_text":"Namun","translation_text":"However"}]'::jsonb,'a','“Oleh itu” memperkenalkan akibat atau hasil.','“Oleh itu” introduces a consequence or result.','approved','knowledge','ms','cause-effect-linker',pg_catalog.now()),
('quiz-ms-en-b035',1,'ms','en','ms-i-conditionals','ms-topic-conditionals','intermediate','Perkataan manakah yang memperkenalkan syarat?','Which word introduces a condition?','[{"id":"a","learning_text":"sekiranya","translation_text":"if / in the event that"},{"id":"b","learning_text":"walaupun","translation_text":"although"},{"id":"c","learning_text":"sementara","translation_text":"while"},{"id":"d","learning_text":"malah","translation_text":"moreover"}]'::jsonb,'a','“Sekiranya” digunakan untuk memperkenalkan keadaan bersyarat.','“Sekiranya” introduces a conditional situation.','approved','knowledge','ms','conditional-clause',pg_catalog.now()),
('quiz-ms-en-b036',1,'ms','en','ms-i-relative-clauses','ms-topic-relative-clauses','intermediate','Perkataan manakah menghubungkan kata nama dengan klausa yang menerangkannya?','Which word links a noun to a clause describing it?','[{"id":"a","learning_text":"yang","translation_text":"that / which / who"},{"id":"b","learning_text":"dan","translation_text":"and"},{"id":"c","learning_text":"atau","translation_text":"or"},{"id":"d","learning_text":"tetapi","translation_text":"but"}]'::jsonb,'a','“Yang” memperkenalkan klausa relatif yang menerangkan kata nama.','“Yang” introduces a relative clause that describes a noun.','approved','knowledge','ms','relative-clause-marker',pg_catalog.now()),
('quiz-ms-en-b037',1,'ms','en','ms-a-ragam-bahasa','ms-register','advanced','Pembuka kata manakah paling sesuai untuk surat rasmi kepada organisasi?','Which opening is most suitable for a formal letter to an organisation?','[{"id":"a","learning_text":"Tuan/Puan,","translation_text":"Dear Sir/Madam,"},{"id":"b","learning_text":"Hai semua!","translation_text":"Hey everyone!"},{"id":"c","learning_text":"Oi,","translation_text":"Hey!"},{"id":"d","learning_text":"Apa cerita?","translation_text":"What''s up?"}]'::jsonb,'a','“Tuan/Puan” ialah panggilan hormat yang lazim dalam surat rasmi.','“Tuan/Puan” is a conventional formal salutation.','approved','knowledge','ms','formal-register',pg_catalog.now()),
('quiz-ms-en-b038',1,'ms','en','ms-a-wacana-penanda','ms-discourse-markers','advanced','Penanda wacana manakah paling sesuai untuk menunjukkan pertentangan dengan isi sebelumnya?','Which discourse marker best signals a contrast with the previous point?','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"Nevertheless / however"},{"id":"b","learning_text":"Selain itu","translation_text":"Furthermore"},{"id":"c","learning_text":"Seterusnya","translation_text":"Next"},{"id":"d","learning_text":"Kesimpulannya","translation_text":"In conclusion"}]'::jsonb,'a','“Walau bagaimanapun” menandakan pertentangan atau pengecualian terhadap isi sebelumnya.','“Walau bagaimanapun” signals a contrast or qualification.','approved','knowledge','ms','discourse-contrast',pg_catalog.now()),
('quiz-ms-en-b039',1,'ms','en','ms-a-penyuntingan','ms-editing','advanced','Pindaan manakah menghapuskan pengulangan yang tidak perlu tanpa mengubah maksud?','Which revision removes unnecessary repetition while preserving the meaning?','[{"id":"a","learning_text":"Para peserta diminta hadir pada pukul lapan.","translation_text":"Participants are asked to arrive at eight."},{"id":"b","learning_text":"Semua para peserta diminta hadir pada pukul lapan.","translation_text":"All the participants are asked to arrive at eight."},{"id":"c","learning_text":"Para semua peserta diminta hadir pada pukul lapan.","translation_text":"All participants all are asked to arrive at eight."},{"id":"d","learning_text":"Peserta-peserta semua para diminta hadir.","translation_text":"Participants-participants all the are asked to arrive."}]'::jsonb,'a','“Para peserta” sudah menunjukkan kumpulan yang ramai; penambahan “semua” tidak diperlukan.','“Para peserta” already expresses a plural group; adding “semua” is redundant.','approved','knowledge','ms','editing-clarity',pg_catalog.now()),
('quiz-ms-en-b040',1,'ms','en','ms-a-ayat-pasif','ms-passive-voice','advanced','Pilih bentuk pasif yang betul bagi ayat “Siti membaca buku itu.”','Choose the correct passive form of “Siti membaca buku itu.”','[{"id":"a","learning_text":"Buku itu dibaca oleh Siti.","translation_text":"The book is read by Siti."},{"id":"b","learning_text":"Buku itu membaca Siti.","translation_text":"The book reads Siti."},{"id":"c","learning_text":"Siti dibaca oleh buku itu.","translation_text":"Siti is read by the book."},{"id":"d","learning_text":"Dibaca buku itu Siti oleh.","translation_text":"Read the book Siti by."}]'::jsonb,'a','Objek menjadi fokus ayat dan menerima bentuk pasif berawalan di- iaitu “dibaca”.','The object becomes the focus and takes the di- passive form “dibaca”.','approved','knowledge','ms','passive-voice-focus',pg_catalog.now()),
('quiz-ms-en-b041',1,'ms','en','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Pilihan manakah paling baik untuk mengelakkan pengulangan kata nama yang sama dalam ayat berturutan?','Which choice best avoids repeating the same noun in adjacent sentences?','[{"id":"a","learning_text":"Gunakan kata ganti nama yang rujukannya jelas.","translation_text":"Use a pronoun with a clear reference."},{"id":"b","learning_text":"Ulang kata nama yang sama dalam setiap ayat.","translation_text":"Repeat the same noun in every sentence."},{"id":"c","learning_text":"Gugurkan semua subjek tanpa sebab.","translation_text":"Remove every subject without reason."},{"id":"d","learning_text":"Tukar topik pada setiap ayat.","translation_text":"Change the topic in every sentence."}]'::jsonb,'a','Rujukan kata ganti nama yang jelas menghubungkan ayat tanpa mengelirukan pembaca.','Clear pronoun reference links sentences without confusing the reader.','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-en-b042',1,'ms','en','ms-a-hujah-berasas','ms-reasoned-argument','advanced','Unsur manakah yang memberikan sokongan kepada sesuatu hujah?','Which element provides support for an argument?','[{"id":"a","learning_text":"Bukti yang relevan","translation_text":"Relevant evidence"},{"id":"b","learning_text":"Pendapat tanpa alasan","translation_text":"An opinion without reasons"},{"id":"c","learning_text":"Pengulangan dakwaan","translation_text":"Repeating the claim"},{"id":"d","learning_text":"Serangan terhadap penulis","translation_text":"Attacking the writer"}]'::jsonb,'a','Bukti yang relevan menyokong dakwaan dan mengukuhkan hujah.','Relevant evidence supports a claim and makes an argument more convincing.','approved','knowledge','ms','argument-evidence',pg_catalog.now()),
('quiz-ms-en-b043',1,'ms','en','ms-a-variasi-struktur','ms-sentence-variation','advanced','Ayat manakah menggunakan frasa tempat di hadapan untuk mempelbagaikan struktur secara semula jadi?','Which sentence uses an opening location phrase to vary its structure naturally?','[{"id":"a","learning_text":"Di tepi sungai itu, beberapa keluarga berkelah.","translation_text":"By the river, several families are having a picnic."},{"id":"b","learning_text":"Beberapa keluarga di tepi sungai itu berkelah keluarga.","translation_text":"Several families by the river picnic families."},{"id":"c","learning_text":"Berkelah beberapa keluarga sungai itu di tepi.","translation_text":"Picnic several families river by the edge."},{"id":"d","learning_text":"Sungai itu beberapa keluarga di tepi berkelah.","translation_text":"River that several families at edge picnic."}]'::jsonb,'a','Frasa tempat di hadapan menetapkan latar sebelum klausa utama.','The fronted location phrase establishes the setting before the main clause.','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-en-b044',1,'ms','en','ms-a-parafrasa','ms-paraphrasing','advanced','Parafrasa manakah mengekalkan maksud “Penggunaan air perlu dikurangkan”?','Which paraphrase preserves the meaning of “Penggunaan air perlu dikurangkan”?','[{"id":"a","learning_text":"Kita perlu menggunakan air dengan lebih sedikit.","translation_text":"We need to use less water."},{"id":"b","learning_text":"Kita mesti menggunakan air sebanyak mungkin.","translation_text":"We must use as much water as possible."},{"id":"c","learning_text":"Air tidak boleh digunakan langsung.","translation_text":"Water must not be used at all."},{"id":"d","learning_text":"Penggunaan air akan meningkat.","translation_text":"Water use will increase."}]'::jsonb,'a','Parafrasa yang baik mengubah susunan atau pilihan kata tetapi mengekalkan maksud asal.','A sound paraphrase changes wording but retains the original meaning.','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-en-b045',1,'ms','en','ms-a-bacaan-kritis','ms-critical-reading','advanced','Butiran manakah paling berguna untuk menilai kredibiliti laporan dalam talian?','Which detail is most useful when checking whether an online report is credible?','[{"id":"a","learning_text":"Nama penulis, tarikh dan sumber bukti","translation_text":"Author, date and evidence sources"},{"id":"b","learning_text":"Warna laman web sahaja","translation_text":"Website colour alone"},{"id":"c","learning_text":"Jumlah emoji dalam tajuk","translation_text":"Number of emojis in the headline"},{"id":"d","learning_text":"Panjang tajuk semata-mata","translation_text":"Headline length alone"}]'::jsonb,'a','Nama penulis, tarikh penerbitan dan bukti yang boleh disemak membantu menilai kebolehpercayaan.','Authorship, publication date and traceable evidence help assess reliability.','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-en-b046',1,'ms','en','ms-a-argument-structure','ms-topic-argument-structure','advanced','Apakah susunan paling logik bagi hujah ringkas yang berasaskan bukti?','What is the most logical order for a short evidence-based argument?','[{"id":"a","learning_text":"Dakwaan, bukti, huraian","translation_text":"Claim, evidence, explanation"},{"id":"b","learning_text":"Bukti, kesimpulan, tajuk","translation_text":"Evidence, conclusion, title"},{"id":"c","learning_text":"Huraian, tajuk, dakwaan","translation_text":"Explanation, title, claim"},{"id":"d","learning_text":"Kesimpulan, dakwaan, bukti tanpa kaitan","translation_text":"Conclusion, unrelated claim, evidence"}]'::jsonb,'a','Hujah yang jelas menyatakan dakwaan, menyokongnya dengan bukti dan menghuraikan kaitannya.','A clear argument states a claim, supports it with evidence and explains the link.','approved','knowledge','ms','argument-structure',pg_catalog.now()),
('quiz-ms-en-b047',1,'ms','en','ms-a-counterargument-and-rebuttal','ms-topic-counterargument-and-rebuttal','advanced','Apakah yang perlu dilakukan oleh sanggahan selepas hujah balas dikemukakan?','What should a rebuttal do after presenting a counterargument?','[{"id":"a","learning_text":"Menjawab hujah balas dengan alasan atau bukti yang relevan","translation_text":"Answer the counterargument with relevant reasoning or evidence"},{"id":"b","learning_text":"Mengabaikan semua pandangan lain","translation_text":"Ignore all other views"},{"id":"c","learning_text":"Mengulangi dakwaan tanpa penjelasan","translation_text":"Repeat the claim without explanation"},{"id":"d","learning_text":"Menyerang peribadi pihak lawan","translation_text":"Attack the opponent personally"}]'::jsonb,'a','Sanggahan menjawab hujah pihak lain dengan alasan atau bukti yang berkaitan.','A rebuttal responds to the opposing point with relevant reasoning or evidence.','approved','knowledge','ms','counterargument-response',pg_catalog.now()),
('quiz-ms-en-b048',1,'ms','en','ms-a-source-credibility','ms-topic-source-credibility','advanced','Sumber manakah biasanya paling kukuh untuk menyemak dasar kerajaan semasa?','Which source is generally strongest for checking a current government policy?','[{"id":"a","learning_text":"Laman rasmi agensi kerajaan yang berkaitan","translation_text":"The relevant government''s official website"},{"id":"b","learning_text":"Komen tanpa nama di media sosial","translation_text":"An anonymous social-media comment"},{"id":"c","learning_text":"Mesej berantai yang tiada pautan","translation_text":"A chain message without links"},{"id":"d","learning_text":"Iklan produk yang tidak berkaitan","translation_text":"An unrelated product advertisement"}]'::jsonb,'a','Laman rasmi agensi berkaitan biasanya menjadi rujukan utama bagi dasar agensi itu.','An official agency source is usually the primary reference for its own policy.','approved','knowledge','ms','source-credibility',pg_catalog.now()),
('quiz-ms-en-b049',1,'ms','en','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Anda tidak memahami arahan tugasan. Apakah cara yang paling sopan untuk meminta penjelasan?','You do not understand the assignment instructions. What is the politest way to ask for an explanation?','[{"id":"a","learning_text":"Boleh cikgu terangkan sekali lagi?","translation_text":"Could you explain it again, teacher?"},{"id":"b","learning_text":"Cikgu, terangkan sekarang!","translation_text":"Teacher, explain it now!"},{"id":"c","learning_text":"Saya tidak mahu mendengar arahan.","translation_text":"I do not want to hear the instructions."},{"id":"d","learning_text":"Awak mesti ulang semuanya.","translation_text":"You must repeat everything."}]'::jsonb,'a','Ungkapan “Boleh …?” membentuk permintaan yang lebih sopan.','“Boleh …?” forms a more polite request.','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-en-b050',1,'ms','en','ms-b-community-places','ms-topic-community-places','beginner','Di manakah seseorang biasanya meminjam buku untuk dibaca di luar premis?','Where would someone usually borrow books to read away from the premises?','[{"id":"a","learning_text":"Perpustakaan","translation_text":"Library"},{"id":"b","learning_text":"Klinik","translation_text":"Clinic"},{"id":"c","learning_text":"Balai polis","translation_text":"Police station"},{"id":"d","learning_text":"Stesen minyak","translation_text":"Petrol station"}]'::jsonb,'a','Perpustakaan menyediakan perkhidmatan pinjaman bahan bacaan.','A library provides a book-lending service.','approved','knowledge','ms','community-place-vocabulary',pg_catalog.now()),
('quiz-ms-en-b051',1,'ms','en','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih kata kerja yang melengkapkan ayat: “Selepas pulang, saya ___ dan berehat.”','Choose the verb that completes: “After returning home, I ___ and rest.”','[{"id":"a","learning_text":"mandi","translation_text":"bathe"},{"id":"b","learning_text":"semalam","translation_text":"last night"},{"id":"c","learning_text":"kerana","translation_text":"because"},{"id":"d","learning_text":"tinggi","translation_text":"tall"}]'::jsonb,'a','“Mandi” ialah kata kerja yang sesuai untuk kegiatan harian.','“Mandi” is a suitable verb for a daily activity.','approved','knowledge','ms','daily-activity-verb',pg_catalog.now()),
('quiz-ms-en-b052',1,'ms','en','ms-b-family-and-people','ms-family-and-people','beginner','Apakah maksud frasa “kakak saya”?','What does the phrase “kakak saya” mean?','[{"id":"a","learning_text":"kakak saya","translation_text":"my older sister"},{"id":"b","learning_text":"adik lelaki saya","translation_text":"my younger brother"},{"id":"c","learning_text":"nenek saya","translation_text":"my grandmother"},{"id":"d","learning_text":"bapa saudara saya","translation_text":"my uncle"}]'::jsonb,'a','“Kakak” merujuk saudara perempuan yang lebih tua; “saya” menunjukkan pemilikan atau hubungan dengan penutur.','“Kakak” means an older sister; “saya” links the relationship to the speaker.','approved','knowledge','ms','older-sister-term',pg_catalog.now()),
('quiz-ms-en-b053',1,'ms','en','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Pilih frasa yang betul untuk memesan satu gelas air dalam bahasa Melayu.','Choose the correct Malay phrase for ordering one glass of water.','[{"id":"a","learning_text":"segelas air","translation_text":"a glass of water"},{"id":"b","learning_text":"seekor air","translation_text":"an animal of water"},{"id":"c","learning_text":"sebatang air","translation_text":"a stick of water"},{"id":"d","learning_text":"sehelai air","translation_text":"a sheet of water"}]'::jsonb,'a','“Segelas” ialah penjodoh bilangan untuk kandungan sebanyak satu gelas.','“Segelas” is the classifier phrase for one glassful.','approved','knowledge','ms','food-order-classifier',pg_catalog.now()),
('quiz-ms-en-b054',1,'ms','en','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Ayat manakah menyatakan kegiatan yang diminati sebagai hobi?','Which sentence describes an activity someone enjoys as a hobby?','[{"id":"a","learning_text":"Hobi saya ialah berkebun.","translation_text":"My hobby is gardening."},{"id":"b","learning_text":"Saya berada di stesen.","translation_text":"I am at the station."},{"id":"c","learning_text":"Hari ini hari Isnin.","translation_text":"Today is Monday."},{"id":"d","learning_text":"Buku itu di atas meja.","translation_text":"The book is on the table."}]'::jsonb,'a','Frasa “Hobi saya ialah …” digunakan untuk memperkenalkan aktiviti kegemaran.','“Hobi saya ialah …” introduces a favourite activity.','approved','knowledge','ms','hobby-expression',pg_catalog.now()),
('quiz-ms-en-b055',1,'ms','en','ms-b-home-and-household','ms-topic-home-and-household','beginner','Di ruang manakah seseorang biasanya tidur pada waktu malam?','In which room does someone usually sleep at night?','[{"id":"a","learning_text":"Bilik tidur","translation_text":"Bedroom"},{"id":"b","learning_text":"Dapur","translation_text":"Kitchen"},{"id":"c","learning_text":"Ruang tamu","translation_text":"Living room"},{"id":"d","learning_text":"Bilik mandi","translation_text":"Bathroom"}]'::jsonb,'a','“Bilik tidur” ialah ruang yang digunakan untuk tidur.','“Bilik tidur” is the room used for sleeping.','approved','knowledge','ms','room-vocabulary',pg_catalog.now()),
('quiz-ms-en-b056',1,'ms','en','ms-b-places-and-directions','ms-places-and-directions','beginner','Jika kedai berada di sebelah kiri anda, frasa manakah menerangkan lokasinya?','If the shop is on your left, which phrase describes its location?','[{"id":"a","learning_text":"di sebelah kiri saya","translation_text":"on my left"},{"id":"b","learning_text":"ke sebelah kiri saya","translation_text":"towards my left"},{"id":"c","learning_text":"belok ke kiri","translation_text":"turn left"},{"id":"d","learning_text":"terus ke hadapan","translation_text":"go straight ahead"}]'::jsonb,'a','“Di sebelah kiri” menerangkan lokasi, bukan pergerakan.','“Di sebelah kiri” describes a location, not movement.','approved','knowledge','ms','direction-instruction',pg_catalog.now()),
('quiz-ms-en-b057',1,'ms','en','ms-b-shopping-and-prices','ms-shopping-and-prices','beginner','Apakah soalan yang sesuai untuk mengetahui harga sebuah beg?','Which question is suitable for asking the price of a bag?','[{"id":"a","learning_text":"Berapakah harga beg ini?","translation_text":"How much is this bag?"},{"id":"b","learning_text":"Di manakah beg ini?","translation_text":"Where is this bag?"},{"id":"c","learning_text":"Bilakah beg ini tiba?","translation_text":"When will this bag arrive?"},{"id":"d","learning_text":"Siapakah pemilik beg ini?","translation_text":"Who owns this bag?"}]'::jsonb,'a','“Berapakah harga …?” ialah bentuk soalan untuk bertanya harga.','“Berapakah harga …?” is a standard way to ask a price.','approved','knowledge','ms','asking-price',pg_catalog.now()),
('quiz-ms-en-b058',1,'ms','en','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang menyatakan tempat asal seseorang, bukan tempat tinggal sekarang.','Choose the sentence that states someone''s place of origin, not their current residence.','[{"id":"a","learning_text":"Saya berasal dari Perlis.","translation_text":"I come from Perlis."},{"id":"b","learning_text":"Saya tinggal di Perlis.","translation_text":"I live in Perlis."},{"id":"c","learning_text":"Saya pergi ke Perlis.","translation_text":"I am going to Perlis."},{"id":"d","learning_text":"Saya suka Perlis.","translation_text":"I like Perlis."}]'::jsonb,'a','“Berasal dari” menyatakan asal seseorang; “tinggal di” menyatakan tempat menetap.','“Berasal dari” states origin; “tinggal di” states residence.','approved','knowledge','ms','residence-statement',pg_catalog.now()),
('quiz-ms-en-b059',1,'ms','en','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Pilih kata kerja berawalan meN- yang betul daripada kata dasar “sapu”.','Choose the correctly formed meN- verb derived from “sapu”.','[{"id":"a","learning_text":"menyapu","translation_text":"to sweep"},{"id":"b","learning_text":"mensapu","translation_text":"nonstandard form: initial s retained"},{"id":"c","learning_text":"memsapu","translation_text":"nonstandard form: extra m added"},{"id":"d","learning_text":"mengsapu","translation_text":"nonstandard form: extra ng added"}]'::jsonb,'a','Huruf awal “s” dalam kata dasar gugur dan digantikan dengan bentuk “meny-”: menyapu.','The initial “s” is dropped and the prefix takes the form “meny-”: menyapu.','approved','knowledge','ms','meN-prefix-context',pg_catalog.now()),
('quiz-ms-en-b060',1,'ms','en','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah sesuai untuk sehelai kertas?','Which classifier is suitable for a sheet of paper?','[{"id":"a","learning_text":"sehelai kertas","translation_text":"a sheet of paper"},{"id":"b","learning_text":"seekor kertas","translation_text":"an animal of paper"},{"id":"c","learning_text":"sebatang kertas","translation_text":"a stick of paper"},{"id":"d","learning_text":"sebiji kertas","translation_text":"a piece/fruit of paper"}]'::jsonb,'a','“Helai” digunakan untuk benda nipis dan leper seperti kertas.','“Helai” is used for thin, flat items such as paper.','approved','knowledge','ms','classifier-for-flat-items',pg_catalog.now()),
('quiz-ms-en-b061',1,'ms','en','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah maksud kata ganda “kanak-kanak”?','What does the reduplicated word “kanak-kanak” mean?','[{"id":"a","learning_text":"kanak-kanak","translation_text":"children"},{"id":"b","learning_text":"orang dewasa","translation_text":"an adult"},{"id":"c","learning_text":"bilik darjah","translation_text":"a classroom"},{"id":"d","learning_text":"guru","translation_text":"a teacher"}]'::jsonb,'a','“Kanak-kanak” ialah bentuk kata ganda yang merujuk golongan anak atau budak.','“Kanak-kanak” is a reduplicated form referring to children.','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-en-b062',1,'ms','en','ms-i-aspek-perbuatan','ms-aspect','intermediate','Dalam ayat “Mereka sedang berbincang”, apakah fungsi perkataan “sedang”?','In “Mereka sedang berbincang”, what is the function of “sedang”?','[{"id":"a","learning_text":"Menunjukkan perbuatan sedang berlangsung","translation_text":"Shows an action in progress"},{"id":"b","learning_text":"Menunjukkan perbuatan yang belum bermula","translation_text":"Shows an action that has not begun"},{"id":"c","learning_text":"Menunjukkan tempat","translation_text":"Shows a location"},{"id":"d","learning_text":"Menunjukkan pemilikan","translation_text":"Shows possession"}]'::jsonb,'a','“Sedang” menandakan perbuatan yang berlaku pada waktu rujukan.','“Sedang” marks an action in progress at the reference time.','approved','knowledge','ms','ongoing-aspect',pg_catalog.now()),
('quiz-ms-en-b063',1,'ms','en','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang melengkapkan ayat: “Mereka bergerak ___ dewan utama.”','Choose the preposition that completes: “They move ___ the main hall.”','[{"id":"a","learning_text":"ke","translation_text":"to"},{"id":"b","learning_text":"di","translation_text":"at/in"},{"id":"c","learning_text":"daripada","translation_text":"from"},{"id":"d","learning_text":"dengan","translation_text":"with"}]'::jsonb,'a','“Ke” menunjukkan arah atau destinasi pergerakan.','“Ke” indicates the direction or destination of movement.','approved','knowledge','ms','destination-preposition',pg_catalog.now()),
('quiz-ms-en-b064',1,'ms','en','ms-i-kata-hubung','ms-conjunctions','intermediate','Pilih kata hubung yang sesuai: “___ hujan, perlawanan diteruskan.”','Choose the suitable conjunction: “___ it was raining, the match continued.”','[{"id":"a","learning_text":"Walaupun","translation_text":"Although"},{"id":"b","learning_text":"Kerana","translation_text":"Because"},{"id":"c","learning_text":"Supaya","translation_text":"So that"},{"id":"d","learning_text":"Sebelum","translation_text":"Before"}]'::jsonb,'a','“Walaupun” memperkenalkan keadaan yang berlawanan dengan hasil yang dinyatakan.','“Walaupun” introduces a concession that contrasts with the stated outcome.','approved','knowledge','ms','contrast-conjunction',pg_catalog.now()),
('quiz-ms-en-b065',1,'ms','en','ms-i-perbandingan','ms-comparison','intermediate','Pilih ayat perbandingan yang menggunakan “lebih … daripada” dengan betul.','Choose the comparative sentence that correctly uses “lebih … daripada”.','[{"id":"a","learning_text":"Bangunan A lebih tinggi daripada bangunan B.","translation_text":"Building A is taller than building B."},{"id":"b","learning_text":"Bangunan A paling tinggi daripada bangunan B.","translation_text":"Building A is tallest than building B."},{"id":"c","learning_text":"Bangunan A tinggi lebih bangunan B.","translation_text":"Building A tall more building B."},{"id":"d","learning_text":"Bangunan A lebih daripada tinggi bangunan B.","translation_text":"Building A more than tall building B."}]'::jsonb,'a','Struktur “lebih + kata adjektif + daripada” membentuk perbandingan.','The structure “lebih + adjective + daripada” forms a comparison.','approved','knowledge','ms','comparative-structure',pg_catalog.now()),
('quiz-ms-en-b066',1,'ms','en','ms-i-kata-penguat','ms-intensifiers','intermediate','Perkataan manakah menguatkan kata adjektif dalam frasa “___ menarik”?','Which word intensifies the adjective in the phrase “___ menarik”?','[{"id":"a","learning_text":"sangat","translation_text":"very"},{"id":"b","learning_text":"tetapi","translation_text":"but"},{"id":"c","learning_text":"kerana","translation_text":"because"},{"id":"d","learning_text":"apabila","translation_text":"when"}]'::jsonb,'a','“Sangat” ialah kata penguat yang hadir sebelum kata adjektif dalam frasa ini.','“Sangat” is an intensifier placed before the adjective in this phrase.','approved','knowledge','ms','intensifier-choice',pg_catalog.now()),
('quiz-ms-en-b067',1,'ms','en','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Pilih ayat majmuk yang menggabungkan dua kegiatan dengan kata hubung yang sesuai.','Choose the compound sentence that joins two activities with a suitable conjunction.','[{"id":"a","learning_text":"Aina membaca buku dan adiknya menulis nota.","translation_text":"Aina reads a book and her younger sibling writes notes."},{"id":"b","learning_text":"Aina membaca buku kerana adiknya.","translation_text":"Aina reads a book because her younger sibling."},{"id":"c","learning_text":"Aina membaca buku apabila meja.","translation_text":"Aina reads a book when the table."},{"id":"d","learning_text":"Aina membaca buku walaupun dan.","translation_text":"Aina reads a book although and."}]'::jsonb,'a','“Dan” menghubungkan dua klausa yang setara dalam ayat majmuk gabungan.','“Dan” joins two coordinate clauses in a compound sentence.','approved','knowledge','ms','compound-clause',pg_catalog.now()),
('quiz-ms-en-b068',1,'ms','en','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Pilih penanda yang sesuai untuk memperkenalkan kesan: “Jalan licin; ___, pemandu memperlahankan kenderaan.”','Choose the marker that introduces a result: “The road is slippery; ___, drivers slow down.”','[{"id":"a","learning_text":"oleh itu","translation_text":"therefore"},{"id":"b","learning_text":"walaupun","translation_text":"although"},{"id":"c","learning_text":"sebaliknya","translation_text":"instead"},{"id":"d","learning_text":"sementara","translation_text":"while"}]'::jsonb,'a','“Oleh itu” memperkenalkan kesan atau tindakan yang terhasil daripada sebab sebelumnya.','“Oleh itu” introduces a consequence or action resulting from the preceding cause.','approved','knowledge','ms','cause-effect-linker',pg_catalog.now()),
('quiz-ms-en-b069',1,'ms','en','ms-a-ragam-bahasa','ms-register','advanced','Anda menulis surat rasmi kepada pegawai yang tidak dikenali. Sapaan manakah paling sesuai?','You are writing a formal letter to an officer you do not know. Which salutation is most appropriate?','[{"id":"a","learning_text":"Tuan/Puan","translation_text":"Sir/Madam"},{"id":"b","learning_text":"Hai semua","translation_text":"Hi everyone"},{"id":"c","learning_text":"Oi kawan","translation_text":"Hey friend"},{"id":"d","learning_text":"Apa cerita?","translation_text":"What''s up?"}]'::jsonb,'a','“Tuan/Puan” ialah sapaan formal yang sesuai apabila nama penerima tidak diketahui.','“Tuan/Puan” is a suitable formal salutation when the recipient''s name is unknown.','approved','knowledge','ms','formal-register-choice',pg_catalog.now()),
('quiz-ms-en-b070',1,'ms','en','ms-a-ragam-bahasa','ms-register','advanced','Pilih ayat yang mengekalkan laras bahasa rasmi ketika membuat permohonan.','Choose the sentence that maintains a formal register when making a request.','[{"id":"a","learning_text":"Saya ingin memohon pertimbangan pihak tuan.","translation_text":"I would like to request your consideration."},{"id":"b","learning_text":"Aku nak benda itu sekarang.","translation_text":"I want that thing now."},{"id":"c","learning_text":"Kau kena bagi jawapan cepat.","translation_text":"You have to give an answer quickly."},{"id":"d","learning_text":"Bagi saya, boleh?","translation_text":"Give it to me, okay?"}]'::jsonb,'a','“Saya ingin memohon…” ialah bentuk permohonan yang sopan dan formal.','“Saya ingin memohon…” is a polite, formal request form.','approved','knowledge','ms','formal-application-request',pg_catalog.now()),
('quiz-ms-en-b071',1,'ms','en','ms-a-wacana-penanda','ms-discourse-markers','advanced','Pilih penanda wacana yang paling sesuai untuk memperkenalkan pengecualian terhadap hujah sebelumnya.','Choose the discourse marker that best introduces a qualification to the previous argument.','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"Nevertheless"},{"id":"b","learning_text":"Selain itu","translation_text":"Furthermore"},{"id":"c","learning_text":"Sebagai contoh","translation_text":"For example"},{"id":"d","learning_text":"Kesimpulannya","translation_text":"In conclusion"}]'::jsonb,'a','“Walau bagaimanapun” memperkenalkan maklumat yang berbeza atau mengehadkan kenyataan sebelumnya.','“Walau bagaimanapun” introduces contrasting information or qualifies a previous statement.','approved','knowledge','ms','discourse-connector-contrast',pg_catalog.now()),
('quiz-ms-en-b072',1,'ms','en','ms-a-wacana-penanda','ms-discourse-markers','advanced','Dalam esei, anda mahu memperkenalkan maklumat tambahan yang menyokong hujah. Penanda manakah paling sesuai?','In an essay, you want to introduce additional information supporting an argument. Which marker is most suitable?','[{"id":"a","learning_text":"Selain itu","translation_text":"Furthermore"},{"id":"b","learning_text":"Walau bagaimanapun","translation_text":"Nevertheless"},{"id":"c","learning_text":"Sebaliknya","translation_text":"On the contrary"},{"id":"d","learning_text":"Walaupun","translation_text":"Although"}]'::jsonb,'a','“Selain itu” menambah maklumat yang berkaitan dengan perkara sebelumnya.','“Selain itu” adds information related to the preceding point.','approved','knowledge','ms','additive-discourse-marker',pg_catalog.now()),
('quiz-ms-en-b073',1,'ms','en','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling kemas tanpa pengulangan penanda jamak yang tidak perlu.','Choose the clearest sentence without an unnecessary repetition of plural marking.','[{"id":"a","learning_text":"Para peserta menghadiri taklimat itu.","translation_text":"The participants attended the briefing."},{"id":"b","learning_text":"Para peserta semua menghadiri taklimat itu.","translation_text":"All the participants participants attended the briefing."},{"id":"c","learning_text":"Para-para peserta menghadiri taklimat itu.","translation_text":"The participants-participants attended the briefing."},{"id":"d","learning_text":"Peserta para semua menghadiri taklimat itu.","translation_text":"Participants the all attended the briefing."}]'::jsonb,'a','“Para” sudah menandakan kumpulan jamak, maka “semua” tidak diperlukan dalam binaan ini.','“Para” already marks a plural group, so “semua” is unnecessary in this construction.','approved','knowledge','ms','avoid-redundant-plural-marking',pg_catalog.now()),
('quiz-ms-en-b074',1,'ms','en','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang mempunyai rujukan kata ganti nama yang paling jelas.','Choose the sentence with the clearest pronoun reference.','[{"id":"a","learning_text":"Aina meminjam buku daripada Mira lalu memulangkannya kepada Mira pada petang itu.","translation_text":"Aina borrowed a book from Mira and returned it to Mira that afternoon."},{"id":"b","learning_text":"Aina meminjam buku daripada Mira lalu dia memulangkannya kepada dia.","translation_text":"Aina borrowed a book from Mira and she returned it to her."},{"id":"c","learning_text":"Selepas itu, perkara tersebut berlaku kepada mereka.","translation_text":"After that, the matter happened to them."},{"id":"d","learning_text":"Mira memberitahu Aina bahawa dia perlu membawanya.","translation_text":"Mira told Aina that she needed to bring it."}]'::jsonb,'a','Mengulangi nama penerima apabila perlu dapat mengelakkan rujukan kata ganti nama yang kabur.','Repeating the recipient''s name when necessary avoids ambiguous pronoun references.','approved','knowledge','ms','editing-pronoun-reference',pg_catalog.now()),
('quiz-ms-en-b075',1,'ms','en','ms-a-ayat-pasif','ms-passive-voice','advanced','Pilih ayat pasif yang mengekalkan maksud bahawa laporan itu disiapkan oleh Farah.','Choose the passive sentence that preserves the meaning that the report was completed by Farah.','[{"id":"a","learning_text":"Laporan itu disiapkan oleh Farah.","translation_text":"The report was completed by Farah."},{"id":"b","learning_text":"Farah disiapkan oleh laporan itu.","translation_text":"Farah was completed by the report."},{"id":"c","learning_text":"Laporan itu menyiapkan Farah.","translation_text":"The report completed Farah."},{"id":"d","learning_text":"Farah sedang laporan itu siap.","translation_text":"Farah is report complete."}]'::jsonb,'a','Dalam ayat pasif, perkara yang menerima perbuatan menjadi fokus dan pelaku boleh diperkenalkan dengan “oleh”.','In a passive sentence, the receiver of the action becomes the focus and the agent can be introduced with “oleh”.','approved','knowledge','ms','passive-voice-focus',pg_catalog.now()),
('quiz-ms-en-b076',1,'ms','en','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Dalam perenggan tentang para sukarelawan, kata ganti “mereka” paling tepat merujuk kepada siapa jika ayat sebelumnya menyebut kumpulan itu?','In a paragraph about volunteers, whom should “mereka” refer to when the previous sentence names that group?','[{"id":"a","learning_text":"Kumpulan sukarelawan yang disebut sebelumnya","translation_text":"The group of volunteers mentioned earlier"},{"id":"b","learning_text":"Pembaca yang tidak disebut","translation_text":"An unmentioned reader"},{"id":"c","learning_text":"Satu objek yang tidak bernyawa","translation_text":"An inanimate object"},{"id":"d","learning_text":"Penulis sahaja","translation_text":"The writer alone"}]'::jsonb,'a','Kata ganti nama perlu mempunyai rujukan yang jelas dalam wacana.','A pronoun needs a clear antecedent in the discourse.','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-en-b077',1,'ms','en','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Pilih penghubung yang paling sesuai untuk merujuk semula kepada idea utama yang telah dihuraikan.','Choose the connector that best refers back to the main idea already discussed.','[{"id":"a","learning_text":"Hal ini","translation_text":"This matter"},{"id":"b","learning_text":"Walaupun","translation_text":"Although"},{"id":"c","learning_text":"Sebelum","translation_text":"Before"},{"id":"d","learning_text":"Sekiranya","translation_text":"If"}]'::jsonb,'a','“Hal ini” boleh merujuk kepada idea atau keadaan yang telah dinyatakan sebelumnya.','“Hal ini” can refer back to an idea or situation stated earlier.','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-en-b078',1,'ms','en','ms-a-variasi-struktur','ms-sentence-variation','advanced','Dua ayat berturut-turut bermula dengan “Pihak sekolah”. Apakah suntingan terbaik untuk mempelbagaikan struktur tanpa mengubah maksud?','Two consecutive sentences begin with “Pihak sekolah”. What is the best edit to vary the structure without changing the meaning?','[{"id":"a","learning_text":"Gunakan “Di sekolah” sebagai frasa pendahuluan pada ayat kedua.","translation_text":"Use “Di sekolah” as an introductory phrase in the second sentence."},{"id":"b","learning_text":"Buang semua kata kerja daripada ayat kedua.","translation_text":"Remove all verbs from the second sentence."},{"id":"c","learning_text":"Tukar fakta dalam ayat pertama.","translation_text":"Change the facts in the first sentence."},{"id":"d","learning_text":"Ulang kedua-dua ayat dengan susunan yang sama.","translation_text":"Repeat both sentences with the same structure."}]'::jsonb,'a','Frasa pendahuluan boleh mempelbagaikan permulaan ayat sambil mengekalkan makna.','An introductory phrase can vary a sentence opening while preserving meaning.','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-en-b079',1,'ms','en','ms-a-variasi-struktur','ms-sentence-variation','advanced','Apakah tujuan menggabungkan ayat pendek dan ayat majmuk dalam penulisan?','What is the purpose of combining short and compound sentences in writing?','[{"id":"a","learning_text":"Mewujudkan aliran dan penekanan yang lebih berkesan","translation_text":"To create more effective flow and emphasis"},{"id":"b","learning_text":"Menghapuskan semua tanda baca","translation_text":"To remove all punctuation"},{"id":"c","learning_text":"Menjadikan setiap ayat sama panjang","translation_text":"To make every sentence the same length"},{"id":"d","learning_text":"Mengelakkan penyampaian idea","translation_text":"To avoid communicating ideas"}]'::jsonb,'a','Variasi panjang dan struktur ayat membantu mengawal aliran serta penekanan.','Variation in sentence length and structure helps control flow and emphasis.','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-en-b080',1,'ms','en','ms-a-parafrasa','ms-paraphrasing','advanced','Ayat asal: “Program itu meningkatkan penyertaan belia.” Parafrasa manakah mengekalkan maksud asal?','Original: “The programme increased youth participation.” Which paraphrase preserves the original meaning?','[{"id":"a","learning_text":"Program tersebut menambah penglibatan golongan muda.","translation_text":"The programme increased the involvement of young people."},{"id":"b","learning_text":"Program itu mengurangkan penyertaan belia.","translation_text":"The programme reduced youth participation."},{"id":"c","learning_text":"Belia membatalkan program tersebut.","translation_text":"Young people cancelled the programme."},{"id":"d","learning_text":"Program itu hanya untuk golongan dewasa.","translation_text":"The programme was only for adults."}]'::jsonb,'a','Parafrasa yang baik menukar bentuk ungkapan tanpa mengubah hubungan makna utama.','A good paraphrase changes wording without changing the main meaning.','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-en-b081',1,'ms','en','ms-a-parafrasa','ms-paraphrasing','advanced','Pilih parafrasa yang mengekalkan hubungan sebab dan hasil dalam ayat: “Hujan lebat menyebabkan acara ditangguhkan.”','Choose the paraphrase that preserves the cause-and-result relationship in: “Heavy rain caused the event to be postponed.”','[{"id":"a","learning_text":"Acara ditangguhkan akibat hujan yang lebat.","translation_text":"The event was postponed because of heavy rain."},{"id":"b","learning_text":"Acara diteruskan walaupun hujan lebat.","translation_text":"The event continued despite heavy rain."},{"id":"c","learning_text":"Hujan lebat berlaku selepas acara tamat.","translation_text":"Heavy rain occurred after the event ended."},{"id":"d","learning_text":"Acara menyebabkan hujan turun.","translation_text":"The event caused the rain."}]'::jsonb,'a','“Akibat” mengekalkan hubungan bahawa hujan lebat menjadi sebab penangguhan.','“Akibat” preserves the relationship in which heavy rain is the cause of the postponement.','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-en-b082',1,'ms','en','ms-a-bacaan-kritis','ms-critical-reading','advanced','Anda menemui dakwaan kesihatan tanpa nama penulis, tarikh atau rujukan. Apakah tindakan paling wajar?','You find a health claim with no author, date or references. What is the most appropriate action?','[{"id":"a","learning_text":"Semak dakwaan itu melalui sumber kesihatan yang berwibawa.","translation_text":"Check the claim against an authoritative health source."},{"id":"b","learning_text":"Kongsi segera kerana tajuknya menarik.","translation_text":"Share it immediately because the headline is interesting."},{"id":"c","learning_text":"Anggap dakwaan itu benar tanpa bukti.","translation_text":"Assume it is true without evidence."},{"id":"d","learning_text":"Gunakan bilangan tanda suka sebagai bukti ketepatan.","translation_text":"Use the number of likes as proof of accuracy."}]'::jsonb,'a','Dakwaan perlu disemak melalui sumber yang boleh dikenal pasti dan berwibawa.','Claims should be checked against identifiable, authoritative sources.','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-en-b083',1,'ms','en','ms-a-bacaan-kritis','ms-critical-reading','advanced','Apakah ciri yang paling membantu menilai kebolehpercayaan laporan penyelidikan?','Which feature is most useful when evaluating the reliability of a research report?','[{"id":"a","learning_text":"Kaedah, data dan sumber rujukan dinyatakan dengan jelas.","translation_text":"Methods, data and references are clearly stated."},{"id":"b","learning_text":"Reka bentuk kulit yang berwarna-warni.","translation_text":"A colourful cover design."},{"id":"c","learning_text":"Tajuk yang menggunakan huruf besar.","translation_text":"A title written in capital letters."},{"id":"d","learning_text":"Jumlah komen yang tinggi sahaja.","translation_text":"A high number of comments alone."}]'::jsonb,'a','Kaedah dan rujukan yang telus membolehkan pembaca menilai asas sesuatu dapatan.','Transparent methods and references let readers assess the basis of findings.','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-en-b084',1,'ms','en','ms-a-argument-structure','ms-topic-argument-structure','advanced','Dalam hujah, apakah fungsi bukti yang relevan selepas sesuatu dakwaan dikemukakan?','In an argument, what is the role of relevant evidence after a claim is presented?','[{"id":"a","learning_text":"Menyokong dakwaan dengan asas yang boleh dinilai.","translation_text":"To support the claim with an assessable basis."},{"id":"b","learning_text":"Menggantikan semua penjelasan tanpa hubungan.","translation_text":"To replace all related explanation."},{"id":"c","learning_text":"Mengalihkan perbincangan kepada topik lain.","translation_text":"To shift the discussion to another topic."},{"id":"d","learning_text":"Mengulangi dakwaan tanpa maklumat tambahan.","translation_text":"To repeat the claim without additional information."}]'::jsonb,'a','Bukti yang relevan memberikan asas untuk menilai sama ada dakwaan itu munasabah.','Relevant evidence provides a basis for assessing whether a claim is reasonable.','approved','knowledge','ms','argument-structure',pg_catalog.now()),
('quiz-ms-en-b085',1,'ms','en','ms-b-greetings','ms-greetings','beginner','Seseorang bertanya “Apa khabar?” Apakah jawapan ringkas yang sesuai?','Someone asks “Apa khabar?” What is a suitable short reply?','[{"id":"a","learning_text":"Khabar baik, terima kasih.","translation_text":"I''m fine, thank you."},{"id":"b","learning_text":"Nama saya Aina.","translation_text":"My name is Aina."},{"id":"c","learning_text":"Saya tinggal di Ipoh.","translation_text":"I live in Ipoh."},{"id":"d","learning_text":"Selamat tinggal.","translation_text":"Goodbye."}]'::jsonb,'a','“Khabar baik, terima kasih” ialah jawapan lazim untuk pertanyaan khabar.','“Khabar baik, terima kasih” is a common reply to a question about wellbeing.','approved','knowledge','ms','greeting-response-to-wellbeing',pg_catalog.now()),
('quiz-ms-en-b086',1,'ms','en','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang memperkenalkan nama seseorang dengan betul.','Choose the sentence that correctly introduces someone''s name.','[{"id":"a","learning_text":"Nama saya Aina.","translation_text":"My name is Aina."},{"id":"b","learning_text":"Saya nama Aina.","translation_text":"I name Aina."},{"id":"c","learning_text":"Nama kepada saya Aina.","translation_text":"Name to me Aina."},{"id":"d","learning_text":"Aina nama saya punya.","translation_text":"Aina name my own."}]'::jsonb,'a','“Nama saya …” ialah susunan biasa untuk memperkenalkan nama.','“Nama saya …” is the usual word order for introducing a name.','approved','knowledge','ms','name-introduction',pg_catalog.now()),
('quiz-ms-en-b087',1,'ms','en','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Dalam ayat “Aina membaca buku”, apakah susunan unsur ayat yang betul?','In “Aina membaca buku”, what is the correct sentence-element order?','[{"id":"a","learning_text":"Subjek – kata kerja – objek","translation_text":"Subject – verb – object"},{"id":"b","learning_text":"Objek – subjek – kata kerja","translation_text":"Object – subject – verb"},{"id":"c","learning_text":"Kata kerja – objek – subjek","translation_text":"Verb – object – subject"},{"id":"d","learning_text":"Subjek – objek – kata kerja","translation_text":"Subject – object – verb"}]'::jsonb,'a','Ayat penyata mudah lazimnya mengikut susunan subjek, predikat dan objek apabila objek hadir.','A simple statement commonly follows subject, predicate/verb and object order when an object is present.','approved','knowledge','ms','simple-word-order',pg_catalog.now()),
('quiz-ms-en-b088',1,'ms','en','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Anda tidak dapat membuka fail tugasan. Apakah ungkapan yang sesuai untuk meminta bantuan rakan?','You cannot open the assignment file. Which expression is suitable for asking a classmate for help?','[{"id":"a","learning_text":"Boleh kamu bantu saya sebentar?","translation_text":"Could you help me for a moment?"},{"id":"b","learning_text":"Kamu mesti buat kerja saya.","translation_text":"You must do my work."},{"id":"c","learning_text":"Jangan bercakap dengan saya.","translation_text":"Do not speak to me."},{"id":"d","learning_text":"Saya tidak peduli tentang fail.","translation_text":"I do not care about the file."}]'::jsonb,'a','“Boleh … bantu saya?” ialah permintaan bantuan yang sopan.','“Boleh … bantu saya?” is a polite request for help.','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-en-b089',1,'ms','en','ms-b-community-places','ms-topic-community-places','beginner','Jika seseorang memerlukan rawatan untuk demam, tempat manakah paling sesuai dikunjungi?','If someone needs treatment for a fever, which place is most suitable to visit?','[{"id":"a","learning_text":"Klinik","translation_text":"Clinic"},{"id":"b","learning_text":"Perpustakaan","translation_text":"Library"},{"id":"c","learning_text":"Pejabat pos","translation_text":"Post office"},{"id":"d","learning_text":"Pasar raya","translation_text":"Supermarket"}]'::jsonb,'a','Klinik menyediakan perkhidmatan pemeriksaan dan rawatan kesihatan asas.','A clinic provides basic health examinations and treatment.','approved','knowledge','ms','community-service-place',pg_catalog.now()),
('quiz-ms-en-b090',1,'ms','en','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih penanda urutan yang sesuai untuk melengkapkan ayat: “Saya bersarapan. ___, saya pergi ke sekolah.”','Choose the sequence marker: “I have breakfast. ___, I go to school.”','[{"id":"a","learning_text":"Kemudian","translation_text":"Then"},{"id":"b","learning_text":"Walaupun","translation_text":"Although"},{"id":"c","learning_text":"Kerana","translation_text":"Because"},{"id":"d","learning_text":"Tetapi","translation_text":"But"}]'::jsonb,'a','“Kemudian” menunjukkan kegiatan yang berlaku selepas kegiatan sebelumnya.','“Kemudian” indicates an activity that happens after the previous one.','approved','knowledge','ms','daily-sequence-marker',pg_catalog.now()),
('quiz-ms-en-b091',1,'ms','en','ms-b-family-and-people','ms-family-and-people','beginner','Pilih frasa pemilikan yang betul untuk menyatakan “their younger sibling”.','Choose the correct Malay possessive phrase for “their younger sibling”.','[{"id":"a","learning_text":"adik mereka","translation_text":"their younger sibling"},{"id":"b","learning_text":"mereka adik","translation_text":"they younger sibling"},{"id":"c","learning_text":"adik kepada mereka punya","translation_text":"younger sibling to their own"},{"id":"d","learning_text":"mereka punya kepada adik","translation_text":"they own to younger sibling"}]'::jsonb,'a','Kata ganti nama pemilik hadir selepas kata nama dalam frasa seperti “adik mereka”.','The possessive pronoun follows the noun in a phrase such as “adik mereka”.','approved','knowledge','ms','possessive-pronoun-order',pg_catalog.now()),
('quiz-ms-en-b092',1,'ms','en','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Apakah kata adjektif yang sesuai untuk menerangkan rasa limau yang masam?','Which adjective describes the sour taste of lime?','[{"id":"a","learning_text":"masam","translation_text":"sour"},{"id":"b","learning_text":"manis","translation_text":"sweet"},{"id":"c","learning_text":"pedas","translation_text":"spicy"},{"id":"d","learning_text":"tawar","translation_text":"bland"}]'::jsonb,'a','“Masam” menerangkan rasa seperti limau atau cuka.','“Masam” describes a sour taste such as lime or vinegar.','approved','knowledge','ms','taste-adjective',pg_catalog.now()),
('quiz-ms-en-b093',1,'ms','en','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Pilih ayat yang menyatakan minat terhadap aktiviti pada masa lapang.','Choose the sentence that expresses an interest in a free-time activity.','[{"id":"a","learning_text":"Saya gemar berkebun pada hujung minggu.","translation_text":"I enjoy gardening at weekends."},{"id":"b","learning_text":"Saya berada di klinik semalam.","translation_text":"I was at the clinic yesterday."},{"id":"c","learning_text":"Cuaca hari ini mendung.","translation_text":"The weather is cloudy today."},{"id":"d","learning_text":"Buku itu milik guru.","translation_text":"The book belongs to the teacher."}]'::jsonb,'a','“Saya gemar …” digunakan untuk menyatakan minat atau kesukaan.','“Saya gemar …” expresses an interest or preference.','approved','knowledge','ms','hobby-preference-expression',pg_catalog.now()),
('quiz-ms-en-b094',1,'ms','en','ms-b-home-and-household','ms-topic-home-and-household','beginner','Pilih parafrasa yang mengekalkan maksud ayat “Ada sebuah meja di ruang tamu”.','What does “Ada sebuah meja di ruang tamu” mean?','[{"id":"a","learning_text":"Terdapat sebuah meja di ruang tamu.","translation_text":"There is a table in the living room."},{"id":"b","learning_text":"Meja itu berada di luar rumah.","translation_text":"The table is outside the house."},{"id":"c","learning_text":"Seseorang sedang mengalihkan meja itu.","translation_text":"Someone is moving the table."},{"id":"d","learning_text":"Ruang tamu itu ialah sebuah meja.","translation_text":"The living room is a table."}]'::jsonb,'a','Ayat ini menyatakan kewujudan sebuah meja di ruang tamu.','The sentence states that a table exists in the living room.','approved','knowledge','ms','existence-with-ada',pg_catalog.now()),
('quiz-ms-en-b095',1,'ms','en','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Apakah bentuk kata kerja berawalan meN- yang betul daripada kata dasar “pukul”?','What is the correct meN- verb derived from “pukul”?','[{"id":"a","learning_text":"memukul","translation_text":"to hit"},{"id":"b","learning_text":"menpukul","translation_text":"incorrect: n prefix"},{"id":"c","learning_text":"mengpukul","translation_text":"incorrect: ng prefix"},{"id":"d","learning_text":"mempukul","translation_text":"incorrect: doubled p"}]'::jsonb,'a','Huruf “p” pada awal kata dasar gugur apabila menerima awalan meN- lalu terbentuk “memukul”.','The initial “p” is dropped with the meN- prefix, producing “memukul”.','approved','knowledge','ms','meN-prefix-p-to-m',pg_catalog.now()),
('quiz-ms-en-b096',1,'ms','en','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah sesuai untuk sebatang pensel?','Which classifier is suitable for one pencil?','[{"id":"a","learning_text":"batang","translation_text":"long-object classifier"},{"id":"b","learning_text":"helai","translation_text":"flat-object classifier"},{"id":"c","learning_text":"ekor","translation_text":"animal classifier"},{"id":"d","learning_text":"biji","translation_text":"small-object/general classifier"}]'::jsonb,'a','“Batang” digunakan untuk benda panjang dan berbentuk silinder seperti pensel.','“Batang” is used for long, cylindrical objects such as pencils.','approved','knowledge','ms','classifier-for-long-items',pg_catalog.now()),
('quiz-ms-en-b097',1,'ms','en','ms-i-kata-ganda','ms-reduplication','intermediate','Dalam konteks “Buku-buku itu disusun di rak”, apakah fungsi kata ganda “buku-buku”?','In “Buku-buku itu disusun di rak”, what is the function of “buku-buku”?','[{"id":"a","learning_text":"Menunjukkan lebih daripada sebuah buku","translation_text":"Indicates more than one book"},{"id":"b","learning_text":"Menunjukkan satu buku sahaja","translation_text":"Indicates only one book"},{"id":"c","learning_text":"Menunjukkan pemilik buku","translation_text":"Indicates the owner of a book"},{"id":"d","learning_text":"Menunjukkan tempat buku","translation_text":"Indicates the location of a book"}]'::jsonb,'a','Penggandaan kata nama boleh menandakan bilangan jamak mengikut konteks.','Noun reduplication can indicate plurality depending on context.','approved','knowledge','ms','reduplication-plurality',pg_catalog.now()),
('quiz-ms-en-b098',1,'ms','en','ms-i-aspek-perbuatan','ms-aspect','intermediate','Dalam ayat “Mereka sudah menyiapkan laporan”, apakah maksud “sudah”?','In “Mereka sudah menyiapkan laporan”, what does “sudah” indicate?','[{"id":"a","learning_text":"Perbuatan telah selesai","translation_text":"The action has been completed"},{"id":"b","learning_text":"Perbuatan sedang berlangsung","translation_text":"The action is in progress"},{"id":"c","learning_text":"Perbuatan akan bermula","translation_text":"The action will begin"},{"id":"d","learning_text":"Tempat laporan disimpan","translation_text":"Where the report is stored"}]'::jsonb,'a','“Sudah” menandakan perbuatan telah berlaku atau selesai.','“Sudah” indicates that an action has occurred or been completed.','approved','knowledge','ms','completed-aspect-marker',pg_catalog.now()),
('quiz-ms-en-b099',1,'ms','en','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang betul: “Murid-murid belajar ___ perpustakaan.”','Choose the correct preposition: “The pupils study ___ the library.”','[{"id":"a","learning_text":"di","translation_text":"in/at"},{"id":"b","learning_text":"ke","translation_text":"to"},{"id":"c","learning_text":"daripada","translation_text":"from"},{"id":"d","learning_text":"kepada","translation_text":"to (recipient)"}]'::jsonb,'a','“Di” menandakan lokasi sesuatu kegiatan berlaku.','“Di” marks the location where an activity takes place.','approved','knowledge','ms','location-preposition',pg_catalog.now()),
('quiz-ms-en-b100',1,'ms','en','ms-i-kata-hubung','ms-conjunctions','intermediate','Pilih kata hubung yang menyatakan sebab: “Dia tidak hadir ___ demam.”','Choose the conjunction that expresses a reason: “He did not attend ___ a fever.”','[{"id":"a","learning_text":"kerana","translation_text":"because"},{"id":"b","learning_text":"walaupun","translation_text":"although"},{"id":"c","learning_text":"supaya","translation_text":"so that"},{"id":"d","learning_text":"semasa","translation_text":"while"}]'::jsonb,'a','“Kerana” memperkenalkan sebab bagi sesuatu keadaan atau tindakan.','“Kerana” introduces the reason for a condition or action.','approved','knowledge','ms','cause-conjunction',pg_catalog.now()),
('quiz-ms-en-b101',1,'ms','en','ms-i-perbandingan','ms-comparison','intermediate','Pilih ayat yang menggunakan kata penguat darjah tertinggi dengan betul.','Choose the sentence that correctly uses a superlative expression.','[{"id":"a","learning_text":"Gunung itu paling tinggi di kawasan ini.","translation_text":"That mountain is the highest in this area."},{"id":"b","learning_text":"Gunung itu lebih tinggi di kawasan ini.","translation_text":"That mountain is higher in this area."},{"id":"c","learning_text":"Gunung itu tinggi daripada paling.","translation_text":"That mountain high than most."},{"id":"d","learning_text":"Gunung itu paling daripada tinggi.","translation_text":"That mountain most than high."}]'::jsonb,'a','“Paling” digunakan untuk menyatakan darjah tertinggi dalam kumpulan perbandingan.','“Paling” expresses the highest degree within a comparison group.','approved','knowledge','ms','superlative-structure',pg_catalog.now()),
('quiz-ms-en-b102',1,'ms','en','ms-i-kata-penguat','ms-intensifiers','intermediate','Dalam frasa “agak sukar”, apakah maksud kata penguat “agak”?','In the phrase “agak sukar”, what does “agak” mean?','[{"id":"a","learning_text":"Pada tahap sederhana","translation_text":"To a moderate degree"},{"id":"b","learning_text":"Pada tahap yang amat tinggi","translation_text":"To an extremely high degree"},{"id":"c","learning_text":"Langsung tidak","translation_text":"Not at all"},{"id":"d","learning_text":"Pada tahap paling tinggi","translation_text":"To the highest degree"}]'::jsonb,'a','“Agak” menunjukkan darjah sederhana, bukan tahap yang paling tinggi.','“Agak” indicates a moderate degree, not the highest intensity.','approved','knowledge','ms','moderate-intensifier',pg_catalog.now()),
('quiz-ms-en-b103',1,'ms','en','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Pilih kata hubung yang sesuai untuk menggabungkan dua klausa yang berlawanan: “Dia letih, ___ dia meneruskan kerja.”','Choose the conjunction joining two contrasting clauses: “He was tired, ___ he continued working.”','[{"id":"a","learning_text":"tetapi","translation_text":"but"},{"id":"b","learning_text":"kerana","translation_text":"because"},{"id":"c","learning_text":"supaya","translation_text":"so that"},{"id":"d","learning_text":"sebelum","translation_text":"before"}]'::jsonb,'a','“Tetapi” menghubungkan klausa yang menunjukkan pertentangan.','“Tetapi” joins clauses that express a contrast.','approved','knowledge','ms','contrastive-compound-clause',pg_catalog.now()),
('quiz-ms-en-b104',1,'ms','en','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Pilih penanda yang sesuai untuk memperkenalkan kesan selepas sebab dinyatakan: “Bekalan elektrik terputus; ___, kelas dalam talian ditangguhkan.”','Choose the marker introducing the result: “The power supply failed; ___, the online class was postponed.”','[{"id":"a","learning_text":"oleh itu","translation_text":"therefore"},{"id":"b","learning_text":"walaupun","translation_text":"although"},{"id":"c","learning_text":"sebaliknya","translation_text":"instead"},{"id":"d","learning_text":"misalnya","translation_text":"for example"}]'::jsonb,'a','“Oleh itu” menghubungkan sebab yang dinyatakan dengan kesannya.','“Oleh itu” links the stated cause to its result.','approved','knowledge','ms','effect-linker',pg_catalog.now()),
('quiz-ms-en-b105',1,'ms','en','ms-a-ragam-bahasa','ms-register','advanced','Pilih pembuka surat rasmi yang paling sesuai sebelum menyatakan tujuan surat.','Choose the most suitable formal-letter opening before stating the purpose of the letter.','[{"id":"a","learning_text":"Dengan hormatnya,","translation_text":"Respectfully,"},{"id":"b","learning_text":"Hai, apa khabar?","translation_text":"Hi, how are you?"},{"id":"c","learning_text":"Oi, dengar sini.","translation_text":"Hey, listen here."},{"id":"d","learning_text":"Aku nak beritahu.","translation_text":"I want to tell you."}]'::jsonb,'a','“Dengan hormatnya” ialah ungkapan pembuka yang sesuai dalam surat rasmi.','“Dengan hormatnya” is a suitable opening expression in a formal letter.','approved','knowledge','ms','formal-letter-opening',pg_catalog.now()),
('quiz-ms-en-b106',1,'ms','en','ms-a-wacana-penanda','ms-discourse-markers','advanced','Anda mahu merumuskan keseluruhan perbincangan. Penanda wacana manakah paling sesuai?','You want to summarise the entire discussion. Which discourse marker is most suitable?','[{"id":"a","learning_text":"Kesimpulannya","translation_text":"In conclusion"},{"id":"b","learning_text":"Selain itu","translation_text":"Furthermore"},{"id":"c","learning_text":"Walaupun","translation_text":"Although"},{"id":"d","learning_text":"Sebaliknya","translation_text":"On the contrary"}]'::jsonb,'a','“Kesimpulannya” menandakan rumusan atau penutup hujah.','“Kesimpulannya” signals a summary or conclusion.','approved','knowledge','ms','concluding-discourse-marker',pg_catalog.now()),
('quiz-ms-en-b107',1,'ms','en','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling ringkas dan gramatis tanpa frasa berlebihan.','Choose the most concise and grammatical sentence without unnecessary wording.','[{"id":"a","learning_text":"Mereka membincangkan cadangan itu.","translation_text":"They discussed the proposal."},{"id":"b","learning_text":"Mereka saling berbincang bersama-sama tentang cadangan itu.","translation_text":"They mutually discussed together about the proposal."},{"id":"c","learning_text":"Mereka membincangkan tentang mengenai cadangan itu.","translation_text":"They discussed about regarding the proposal."},{"id":"d","learning_text":"Mereka adalah membincangkan cadangan itu.","translation_text":"They are discussing the proposal (ungrammatical in this context)."}]'::jsonb,'a','Pilih kata kerja yang tepat dan elakkan pengulangan makna seperti “berbincang bersama-sama”.','Choose a precise verb and avoid redundant wording such as “berbincang bersama-sama”.','approved','knowledge','ms','editing-conciseness',pg_catalog.now()),
('quiz-ms-en-b108',1,'ms','en','ms-a-ayat-pasif','ms-passive-voice','advanced','Dalam ayat pasif “Keputusan itu diumumkan oleh pengerusi”, apakah fungsi frasa “oleh pengerusi”?','In the passive sentence “Keputusan itu diumumkan oleh pengerusi”, what is the function of “oleh pengerusi”?','[{"id":"a","learning_text":"Menamakan pelaku perbuatan","translation_text":"Names the agent performing the action"},{"id":"b","learning_text":"Menamakan tempat kejadian","translation_text":"Names the location"},{"id":"c","learning_text":"Menunjukkan masa lampau","translation_text":"Shows past time"},{"id":"d","learning_text":"Menafikan keputusan","translation_text":"Negates the decision"}]'::jsonb,'a','Frasa “oleh pengerusi” memperkenalkan pelaku dalam ayat pasif.','“Oleh pengerusi” introduces the agent in a passive sentence.','approved','knowledge','ms','passive-agent-phrase',pg_catalog.now()),
('quiz-ms-en-b109',1,'ms','en','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Apabila dua organisasi disebut dalam perenggan, apakah cara terbaik mengelakkan kekeliruan tentang pihak yang bertindak?','When two organisations are mentioned in a paragraph, what is the best way to avoid confusion about which one acted?','[{"id":"a","learning_text":"Ulang nama organisasi yang dimaksudkan apabila rujukan boleh menjadi kabur.","translation_text":"Repeat the intended organisation''s name when the reference could be unclear."},{"id":"b","learning_text":"Gunakan “mereka” untuk kedua-dua organisasi tanpa konteks.","translation_text":"Use “they” for both organisations without context."},{"id":"c","learning_text":"Gugurkan semua subjek daripada ayat.","translation_text":"Remove all subjects from the sentences."},{"id":"d","learning_text":"Tukar nama organisasi secara rawak.","translation_text":"Change the organisations'' names randomly."}]'::jsonb,'a','Pengulangan kata nama yang terkawal boleh memperjelas rujukan dalam wacana.','Careful noun repetition can clarify references in discourse.','approved','knowledge','ms','cohesive-repetition-reference',pg_catalog.now()),
('quiz-ms-en-b110',1,'ms','en','ms-a-variasi-struktur','ms-sentence-variation','advanced','Ayat kedua terlalu kerap bermula dengan subjek yang sama. Pilih suntingan yang mempelbagaikan struktur tanpa mengubah fakta.','The second sentence repeatedly begins with the same subject. Choose an edit that varies the structure without changing the facts.','[{"id":"a","learning_text":"Pada minggu berikutnya, program itu diteruskan di daerah lain.","translation_text":"In the following week, the programme continued in another district."},{"id":"b","learning_text":"Program itu fakta lain dan minggu.","translation_text":"The programme that fact other and week."},{"id":"c","learning_text":"Buang maklumat tempat daripada kedua-dua ayat.","translation_text":"Remove the location information from both sentences."},{"id":"d","learning_text":"Ulang ayat pertama tanpa perubahan.","translation_text":"Repeat the first sentence unchanged."}]'::jsonb,'a','Frasa keterangan di hadapan ayat boleh mempelbagaikan struktur sambil mengekalkan fakta.','An introductory adverbial phrase can vary sentence structure while preserving the facts.','approved','knowledge','ms','fronted-phrase-variation',pg_catalog.now()),
('quiz-ms-en-b111',1,'ms','en','ms-a-parafrasa','ms-paraphrasing','advanced','Ayat asal: “Pihak sekolah meluluskan permohonan itu.” Parafrasa manakah mengekalkan maksud yang sama?','Original: “The school approved the application.” Which paraphrase preserves the same meaning?','[{"id":"a","learning_text":"Permohonan itu diluluskan oleh pihak sekolah.","translation_text":"The application was approved by the school."},{"id":"b","learning_text":"Permohonan itu ditolak oleh pihak sekolah.","translation_text":"The application was rejected by the school."},{"id":"c","learning_text":"Pihak sekolah menarik balik permohonan itu.","translation_text":"The school withdrew the application."},{"id":"d","learning_text":"Permohonan itu meluluskan pihak sekolah.","translation_text":"The application approved the school."}]'::jsonb,'a','Pertukaran ayat aktif kepada ayat pasif boleh mengekalkan makna jika peranan pelaku dan penerima tindakan kekal tepat.','Changing an active sentence to passive can preserve meaning when the agent and receiver roles remain accurate.','approved','knowledge','ms','active-passive-paraphrase',pg_catalog.now()),
('quiz-ms-en-b112',1,'ms','en','ms-a-bacaan-kritis','ms-critical-reading','advanced','Dua laman memberikan angka yang berbeza tentang perkara yang sama. Apakah langkah paling wajar sebelum membuat kesimpulan?','Two websites give different figures about the same issue. What is the most appropriate step before drawing a conclusion?','[{"id":"a","learning_text":"Bandingkan tarikh, kaedah dan sumber asal bagi kedua-dua angka.","translation_text":"Compare the dates, methods and original sources behind both figures."},{"id":"b","learning_text":"Pilih angka yang paling besar.","translation_text":"Choose the larger figure."},{"id":"c","learning_text":"Pilih laman yang reka bentuknya paling menarik.","translation_text":"Choose the website with the most attractive design."},{"id":"d","learning_text":"Abaikan semua sumber tanpa menyemaknya.","translation_text":"Ignore all sources without checking them."}]'::jsonb,'a','Perbezaan data perlu dinilai melalui konteks, kaedah dan sumber asal.','Differences in data should be assessed through context, methods and original sources.','approved','knowledge','ms','cross-source-verification',pg_catalog.now()),
('quiz-ms-en-b113',1,'ms','en','ms-a-argument-structure','ms-topic-argument-structure','advanced','Dakwaan menyatakan bahawa kemudahan membaca meningkatkan minat murid. Bukti manakah paling relevan?','The claim is that reading facilities increase pupils'' interest. Which evidence is most relevant?','[{"id":"a","learning_text":"Data tinjauan minat membaca sebelum dan selepas kemudahan disediakan.","translation_text":"Survey data on reading interest before and after the facilities were provided."},{"id":"b","learning_text":"Bilangan kenderaan di tempat letak kereta.","translation_text":"The number of vehicles in the car park."},{"id":"c","learning_text":"Warna dinding bangunan sekolah.","translation_text":"The colour of the school building walls."},{"id":"d","learning_text":"Senarai nama guru yang bertugas.","translation_text":"A list of teachers on duty."}]'::jsonb,'a','Bukti yang relevan mengukur perkara yang berkait secara langsung dengan dakwaan.','Relevant evidence measures something directly connected to the claim.','approved','knowledge','ms','evidence-relevance',pg_catalog.now()),
('quiz-ms-en-b114',1,'ms','en','ms-a-counterargument-and-rebuttal','ms-topic-counterargument-and-rebuttal','advanced','Apakah cara yang paling berkesan untuk menjawab hujah balas secara adil?','What is the fairest and most effective way to respond to a counterargument?','[{"id":"a","learning_text":"Akui bahagian yang munasabah, kemudian jawab dengan alasan dan bukti.","translation_text":"Acknowledge the reasonable point, then respond with reasons and evidence."},{"id":"b","learning_text":"Ubah maksud hujah pihak lain.","translation_text":"Misrepresent the other side''s argument."},{"id":"c","learning_text":"Serang peribadi orang yang mengemukakan hujah.","translation_text":"Attack the person who made the argument."},{"id":"d","learning_text":"Abaikan hujah balas tanpa penjelasan.","translation_text":"Ignore the counterargument without explanation."}]'::jsonb,'a','Jawapan yang adil menangani isi hujah, bukan menyerang individu.','A fair rebuttal addresses the argument rather than attacking the individual.','approved','knowledge','ms','acknowledge-counterargument',pg_catalog.now()),
('quiz-ms-en-b115',1,'ms','en','ms-a-source-credibility','ms-topic-source-credibility','advanced','Untuk mengetahui tarikh sebenar sesuatu pengumuman kerajaan, sumber manakah patut diperiksa dahulu?','To confirm the actual date of a government announcement, which source should be checked first?','[{"id":"a","learning_text":"Pengumuman asal pada portal rasmi agensi berkenaan.","translation_text":"The original announcement on the relevant agency''s official portal."},{"id":"b","learning_text":"Tangkap layar tanpa pautan yang dikongsi dalam sembang.","translation_text":"An unlinked screenshot shared in a chat."},{"id":"c","learning_text":"Komen pengguna yang tidak menyertakan bukti.","translation_text":"A user''s comment without evidence."},{"id":"d","learning_text":"Tajuk ringkas daripada akaun yang tidak diketahui.","translation_text":"A short headline from an unknown account."}]'::jsonb,'a','Sumber primer rasmi lebih sesuai untuk mengesahkan kandungan dan tarikh pengumuman asal.','An official primary source is better for verifying the original announcement and its date.','approved','knowledge','ms','primary-source-identification',pg_catalog.now()),
('quiz-ms-en-b116',1,'ms','en','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Anda menerangkan langkah kedua selepas langkah pertama. Penanda wacana manakah paling sesuai?','You are describing the second step after the first. Which discourse marker is most suitable?','[{"id":"a","learning_text":"Seterusnya","translation_text":"Next"},{"id":"b","learning_text":"Walau bagaimanapun","translation_text":"Nevertheless"},{"id":"c","learning_text":"Kesimpulannya","translation_text":"In conclusion"},{"id":"d","learning_text":"Sebaliknya","translation_text":"On the contrary"}]'::jsonb,'a','“Seterusnya” menandakan langkah atau perkara yang menyusul.','“Seterusnya” marks the next step or point.','approved','knowledge','ms','sequence-cohesion-marker',pg_catalog.now()),
('quiz-ms-en-b117',1,'ms','en','ms-a-variasi-struktur','ms-sentence-variation','advanced','Dua ayat menerangkan sebab dan hasil. Pilih gabungan yang paling lancar tanpa mengubah hubungan makna.','Two sentences describe a cause and result. Choose the smoothest combination without changing their relationship.','[{"id":"a","learning_text":"Oleh sebab hujan lebat, acara itu ditangguhkan.","translation_text":"Because of heavy rain, the event was postponed."},{"id":"b","learning_text":"Hujan lebat acara dan ditangguhkan sebab.","translation_text":"Heavy rain event and postponed because."},{"id":"c","learning_text":"Acara itu hujan lebat oleh sebab ditangguhkan.","translation_text":"The event heavy rain because postponed."},{"id":"d","learning_text":"Ditangguhkan acara itu sebab hujan lebat dan.","translation_text":"Postponed the event because heavy rain and."}]'::jsonb,'a','Klausa sebab boleh diletakkan di hadapan untuk menghasilkan aliran ayat yang jelas.','A causal clause can be placed first to create a clear sentence flow.','approved','knowledge','ms','clause-combination-for-flow',pg_catalog.now()),
('quiz-ms-en-b118',1,'ms','en','ms-a-parafrasa','ms-paraphrasing','advanced','Pilih parafrasa yang mengekalkan maksud “Pihak itu memberikan bantuan kepada mangsa”.','Choose the paraphrase that preserves the meaning of “The party provided assistance to the victims”.','[{"id":"a","learning_text":"Pihak itu membantu mangsa.","translation_text":"The party helped the victims."},{"id":"b","learning_text":"Pihak itu menghalang mangsa.","translation_text":"The party obstructed the victims."},{"id":"c","learning_text":"Mangsa memberikan bantuan kepada pihak itu.","translation_text":"The victims helped the party."},{"id":"d","learning_text":"Pihak itu meminta mangsa membayar bantuan.","translation_text":"The party asked the victims to pay for the assistance."}]'::jsonb,'a','“Memberikan bantuan” boleh diparafrasa sebagai “membantu” tanpa mengubah maksud utama.','“Memberikan bantuan” can be paraphrased as “membantu” without changing the main meaning.','approved','knowledge','ms','lexical-paraphrase',pg_catalog.now()),
('quiz-ms-en-b119',1,'ms','en','ms-a-bacaan-kritis','ms-critical-reading','advanced','Pernyataan manakah merupakan pendapat, bukannya fakta yang boleh disahkan secara langsung?','Which statement is an opinion rather than a directly verifiable fact?','[{"id":"a","learning_text":"Perpustakaan itu ialah tempat paling menarik di bandar ini.","translation_text":"That library is the most interesting place in this town."},{"id":"b","learning_text":"Perpustakaan itu dibuka pada pukul lapan pagi.","translation_text":"The library opens at eight in the morning."},{"id":"c","learning_text":"Bangunan itu mempunyai tiga tingkat.","translation_text":"The building has three floors."},{"id":"d","learning_text":"Buku tersebut diterbitkan pada tahun 2022.","translation_text":"The book was published in 2022."}]'::jsonb,'a','Penilaian seperti “paling menarik” bergantung pada pandangan, manakala tiga pernyataan lain boleh disemak melalui rekod atau pemerhatian.','An evaluation such as “most interesting” depends on opinion, while the other statements can be checked through records or observation.','approved','knowledge','ms','fact-opinion-distinction',pg_catalog.now()),
('quiz-ms-en-b120',1,'ms','en','ms-a-argument-structure','ms-topic-argument-structure','advanced','Susunan manakah membentuk hujah yang jelas dan boleh dinilai?','Which sequence forms a clear and assessable argument?','[{"id":"a","learning_text":"Dakwaan, alasan dan bukti yang relevan.","translation_text":"Claim, reason and relevant evidence."},{"id":"b","learning_text":"Kesimpulan, serangan peribadi dan andaian.","translation_text":"Conclusion, personal attack and assumption."},{"id":"c","learning_text":"Contoh rawak, dakwaan baharu dan tajuk.","translation_text":"Random example, new claim and headline."},{"id":"d","learning_text":"Pendapat tanpa alasan atau sokongan.","translation_text":"Opinion without reasons or support."}]'::jsonb,'a','Hujah yang jelas menghubungkan dakwaan dengan alasan serta bukti yang menyokongnya.','A clear argument connects a claim with reasons and supporting evidence.','approved','knowledge','ms','claim-reason-evidence',pg_catalog.now()),
('quiz-ms-zh-b001',1,'ms','zh','ms-b-greetings','ms-greetings','beginner','Anda tiba di kelas pada pukul 8.00 pagi. Apakah sapaan yang paling sesuai?','你早上八点到教室，哪一种问候最合适？','[{"id":"a","learning_text":"Selamat pagi","translation_text":"早上好"},{"id":"b","learning_text":"Selamat malam","translation_text":"晚安"},{"id":"c","learning_text":"Selamat tinggal","translation_text":"再见"},{"id":"d","learning_text":"Sama-sama","translation_text":"不客气"}]'::jsonb,'a','“Selamat pagi” digunakan pada waktu pagi.','“Selamat pagi”用于早上。','approved','knowledge','ms','greetings-in-context',pg_catalog.now()),
('quiz-ms-zh-b002',1,'ms','zh','ms-b-greetings','ms-greetings','beginner','Seseorang mengucapkan “Terima kasih” selepas anda membantunya. Apakah jawapan yang sesuai?','你帮助别人后，对方说“Terima kasih”，你应如何回应？','[{"id":"a","learning_text":"Sama-sama","translation_text":"不客气"},{"id":"b","learning_text":"Apa khabar?","translation_text":"你好吗？"},{"id":"c","learning_text":"Selamat pagi","translation_text":"早上好"},{"id":"d","learning_text":"Maafkan saya","translation_text":"请原谅我"}]'::jsonb,'a','“Sama-sama” ialah balasan lazim untuk ucapan terima kasih.','“Sama-sama”是回应感谢的常见说法。','approved','knowledge','ms','polite-responses',pg_catalog.now()),
('quiz-ms-zh-b003',1,'ms','zh','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang menyatakan tempat tinggal seseorang sekarang.','选择说明某人目前居住地点的句子。','[{"id":"a","learning_text":"Saya tinggal di Ipoh.","translation_text":"我住在怡保。"},{"id":"b","learning_text":"Saya berasal dari Ipoh.","translation_text":"我来自怡保。"},{"id":"c","learning_text":"Saya pergi ke Ipoh.","translation_text":"我要去怡保。"},{"id":"d","learning_text":"Saya suka Ipoh.","translation_text":"我喜欢怡保。"}]'::jsonb,'a','“Saya tinggal di …” menyatakan tempat seseorang menetap sekarang.','“Saya tinggal di …”表示某人目前居住的地方。','approved','knowledge','ms','introducing-personal-details',pg_catalog.now()),
('quiz-ms-zh-b004',1,'ms','zh','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Dalam ayat “Murid itu membaca buku”, frasa manakah menjadi subjek?','在“Murid itu membaca buku”中，哪一个短语是主语？','[{"id":"a","learning_text":"Murid itu","translation_text":"那名学生"},{"id":"b","learning_text":"membaca","translation_text":"阅读"},{"id":"c","learning_text":"buku","translation_text":"书"},{"id":"d","learning_text":"membaca buku","translation_text":"读书"}]'::jsonb,'a','“Murid itu” ialah perkara yang diperkatakan, maka frasa itu subjek.','“Murid itu”是句子谈论的对象，因此是主语。','approved','knowledge','ms','subject-predicate-structure',pg_catalog.now()),
('quiz-ms-zh-b006',1,'ms','zh','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Pilih kata kerja berawalan meN- yang terbentuk dengan betul daripada kata dasar “tulis”.','选择由词根“tulis”正确构成的meN-动词。','[{"id":"a","learning_text":"menulis","translation_text":"书写"},{"id":"b","learning_text":"metulis","translation_text":"非标准形式"},{"id":"c","learning_text":"memtulis","translation_text":"前缀形式错误"},{"id":"d","learning_text":"mengtulis","translation_text":"辅音变化错误"}]'::jsonb,'a','Bentuk standard ialah “menulis”.','标准形式是“menulis”。','approved','knowledge','ms','meN-prefix-forms',pg_catalog.now()),
('quiz-ms-zh-b007',1,'ms','zh','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Pilih penjodoh bilangan yang sesuai: “seekor ___”.','选择合适的量词短语：“seekor ___”。','[{"id":"a","learning_text":"kucing","translation_text":"猫"},{"id":"b","learning_text":"pensel","translation_text":"铅笔"},{"id":"c","learning_text":"buku","translation_text":"书"},{"id":"d","learning_text":"meja","translation_text":"桌子"}]'::jsonb,'a','“Ekor” digunakan sebagai penjodoh bilangan bagi haiwan seperti kucing.','“Ekor”用于动物，例如猫。','approved','knowledge','ms','classifiers-for-animals',pg_catalog.now()),
('quiz-ms-zh-b008',1,'ms','zh','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah fungsi kata ganda “buku-buku” dalam ayat biasa?','重叠形式“buku-buku”通常表示什么？','[{"id":"a","learning_text":"Lebih daripada sebuah buku","translation_text":"不止一本书"},{"id":"b","learning_text":"Sebuah buku yang kecil","translation_text":"一本小书"},{"id":"c","learning_text":"Buku yang baharu","translation_text":"一本新书"},{"id":"d","learning_text":"Buku kepunyaan guru","translation_text":"老师的书"}]'::jsonb,'a','Penggandaan penuh “buku-buku” lazimnya menandakan bilangan jamak.','完全重叠“buku-buku”通常表示复数。','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-zh-b009',1,'ms','zh','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Lengkapkan ayat dengan bentuk kata kerja yang tepat: “Kakak ___ surat itu.” (tulis)','用正确的动词形式完成句子：“Kakak ___ surat itu.”（写）','[{"id":"a","learning_text":"menulis","translation_text":"写"},{"id":"b","learning_text":"menuliskan","translation_text":"把它写下来"},{"id":"c","learning_text":"ditulis","translation_text":"被写"},{"id":"d","learning_text":"tertulis","translation_text":"无意中写下"}]'::jsonb,'a','Dalam ayat aktif ini, “menulis” ialah kata kerja yang sesuai.','在这个主动句中，“menulis”是合适的动词。','approved','knowledge','ms','meN-prefix-context',pg_catalog.now()),
('quiz-ms-zh-b010',1,'ms','zh','ms-a-ragam-bahasa','ms-register','advanced','Anda menulis e-mel rasmi kepada pihak pentadbiran. Pilih pembuka permintaan yang paling sesuai.','你要给行政部门写正式电邮，选择最合适的请求开头。','[{"id":"a","learning_text":"Saya ingin memohon maklumat lanjut berkenaan perkara tersebut.","translation_text":"我谨此申请有关该事项的进一步资料。"},{"id":"b","learning_text":"Oi, bagi tahu saya pasal benda itu.","translation_text":"喂，告诉我那件事。"},{"id":"c","learning_text":"Kau kena jawab sekarang.","translation_text":"你现在必须回答。"},{"id":"d","learning_text":"Aku nak tahu benda tu.","translation_text":"我想知道那件事。"}]'::jsonb,'a','Ungkapan “Saya ingin memohon…” mengekalkan nada formal dan sopan.','“Saya ingin memohon…”保持正式且礼貌的语气。','approved','knowledge','ms','formal-register-choice',pg_catalog.now()),
('quiz-ms-zh-b011',1,'ms','zh','ms-a-wacana-penanda','ms-discourse-markers','advanced','Pilih penanda wacana yang paling tepat untuk menunjukkan pertentangan: “Cadangan itu menjimatkan kos. ___, pelaksanaannya memerlukan masa.”','选择最适合表示转折的衔接词：“该建议能节省成本。___，其实施需要时间。”','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"然而"},{"id":"b","learning_text":"Selain itu","translation_text":"此外"},{"id":"c","learning_text":"Seterusnya","translation_text":"接下来"},{"id":"d","learning_text":"Sebagai contoh","translation_text":"例如"}]'::jsonb,'a','“Walau bagaimanapun” memperkenalkan maklumat yang berbeza atau bertentangan.','“Walau bagaimanapun”用于引出不同或相反的信息。','approved','knowledge','ms','discourse-connector-contrast',pg_catalog.now()),
('quiz-ms-zh-b012',1,'ms','zh','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling jelas dan gramatis untuk laporan rasmi.','选择最清晰、最符合语法的正式报告句子。','[{"id":"a","learning_text":"Pihak sekolah akan mengadakan mesyuarat pada hari Isnin.","translation_text":"校方将在星期一举行会议。"},{"id":"b","learning_text":"Sekolah pihak Isnin mesyuarat akan mengadakan.","translation_text":"学校方面星期一会议将举行。"},{"id":"c","learning_text":"Mesyuarat akan pihak sekolah hari Isnin mengadakan.","translation_text":"会议将校方星期一举行。"},{"id":"d","learning_text":"Pada Isnin mesyuarat sekolah pihak mengadakan akan.","translation_text":"在星期一会议学校方面举行将。"}]'::jsonb,'a','Ayat pertama mempunyai susunan subjek, predikat dan keterangan yang jelas.','第一句的主语、谓语和时间状语结构清晰。','approved','knowledge','ms','editing-agreement-and-clarity',pg_catalog.now()),
('quiz-ms-zh-b005',1,'ms','zh','ms-a-source-credibility','ms-topic-source-credibility','advanced','Apakah tindakan paling wajar apabila dua sumber memberikan angka yang berbeza tentang perkara yang sama?','当两个来源对同一事项给出不同数据时，最恰当的做法是什么？','[{"id":"a","learning_text":"Semak kaedah, tarikh dan sumber data asal.","translation_text":"核对方法、日期和原始数据来源。"},{"id":"b","learning_text":"Pilih angka yang paling besar.","translation_text":"选择最大的数字。"},{"id":"c","learning_text":"Abaikan kedua-dua sumber.","translation_text":"忽略两个来源。"},{"id":"d","learning_text":"Gabungkan angka tanpa menyemak.","translation_text":"不经核实就合并数据。"}]'::jsonb,'a','Angka perlu dibandingkan berdasarkan kaedah dan sumber asal yang boleh disemak.','应根据可核实的方法和原始来源比较数据。','approved','knowledge','ms','verify-claim-with-source',pg_catalog.now()),
('quiz-ms-zh-b013',1,'ms','zh','ms-b-greetings','ms-greetings','beginner','Pilih balasan sopan yang sesuai untuk “Terima kasih”.','选择对“Terima kasih”（谢谢）的恰当礼貌回应。','[{"id":"a","learning_text":"Sama-sama","translation_text":"不客气"},{"id":"b","learning_text":"Maafkan saya","translation_text":"对不起"},{"id":"c","learning_text":"Selamat tinggal","translation_text":"再见"},{"id":"d","learning_text":"Apa khabar?","translation_text":"你好吗？"}]'::jsonb,'a','“Sama-sama” ialah balasan lazim untuk ucapan terima kasih.','“Sama-sama”是回应感谢的常见表达。','approved','knowledge','ms','greeting-choice',pg_catalog.now()),
('quiz-ms-zh-b014',1,'ms','zh','ms-b-personal-information','ms-personal-information','beginner','Ayat manakah yang betul untuk menyatakan tempat tinggal anda?','哪一句正确表达你的居住地？','[{"id":"a","learning_text":"Saya tinggal di Ipoh.","translation_text":"我住在怡保。"},{"id":"b","learning_text":"Saya berasal pada Ipoh.","translation_text":"我来自在怡保。"},{"id":"c","learning_text":"Nama saya di Ipoh.","translation_text":"我的名字在怡保。"},{"id":"d","learning_text":"Saya umur Ipoh.","translation_text":"我年龄怡保。"}]'::jsonb,'a','“Saya tinggal di…” digunakan untuk menyatakan tempat tinggal.','“我住在……”用于说明居住地点。','approved','knowledge','ms','residence-statement',pg_catalog.now()),
('quiz-ms-zh-b015',1,'ms','zh','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Pilih ayat yang mempunyai susunan subjek–kata kerja–objek yang jelas.','选择主语—动词—宾语顺序清晰的句子。','[{"id":"a","learning_text":"Aina membaca buku.","translation_text":"Aina读书。"},{"id":"b","learning_text":"Membaca Aina buku.","translation_text":"读Aina书。"},{"id":"c","learning_text":"Buku membaca Aina.","translation_text":"书读Aina。"},{"id":"d","learning_text":"Aina buku membaca.","translation_text":"Aina书读。"}]'::jsonb,'a','Subjek “Aina” hadir sebelum kata kerja “membaca” dan objek “buku”.','主语“Aina”位于动词“membaca”和宾语“buku”之前。','approved','knowledge','ms','simple-word-order',pg_catalog.now()),
('quiz-ms-zh-b016',1,'ms','zh','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Ungkapan manakah yang sopan untuk meminta bantuan?','哪一种表达礼貌地请求帮助？','[{"id":"a","learning_text":"Boleh saya minta bantuan?","translation_text":"我可以请求帮助吗？"},{"id":"b","learning_text":"Kamu mesti buat sekarang.","translation_text":"你必须现在做。"},{"id":"c","learning_text":"Pergi dari sini.","translation_text":"离开这里。"},{"id":"d","learning_text":"Saya tidak peduli.","translation_text":"我不在乎。"}]'::jsonb,'a','“Boleh saya…” melembutkan permintaan dan menjadikannya lebih sopan.','“Boleh saya……”能使请求语气更委婉、礼貌。','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-zh-b017',1,'ms','zh','ms-b-community-places','ms-topic-community-places','beginner','Di manakah anda biasanya meminjam buku?','你通常在哪里借书？','[{"id":"a","learning_text":"Perpustakaan","translation_text":"图书馆"},{"id":"b","learning_text":"Balai bomba","translation_text":"消防局"},{"id":"c","learning_text":"Klinik","translation_text":"诊所"},{"id":"d","learning_text":"Pasar","translation_text":"市场"}]'::jsonb,'a','Perpustakaan ialah tempat orang meminjam buku.','图书馆是人们借阅书籍的地方。','approved','knowledge','ms','community-place-vocabulary',pg_catalog.now()),
('quiz-ms-zh-b018',1,'ms','zh','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih kata kerja yang melengkapkan: “Saya ___ sebelum pergi ke sekolah.”','选择能完成句子的动词：“Saya ___ sebelum pergi ke sekolah.”','[{"id":"a","learning_text":"bersarapan","translation_text":"吃早餐"},{"id":"b","learning_text":"semalam","translation_text":"昨天"},{"id":"c","learning_text":"cantik","translation_text":"漂亮"},{"id":"d","learning_text":"kerana","translation_text":"因为"}]'::jsonb,'a','“Bersarapan” bermaksud makan sarapan sebelum ke sekolah.','“Bersarapan”意为吃早餐，是上学前的一项活动。','approved','knowledge','ms','daily-activity-verb',pg_catalog.now()),
('quiz-ms-zh-b019',1,'ms','zh','ms-b-family-and-people','ms-family-and-people','beginner','Apakah maksud “abang” dalam hubungan kekeluargaan?','“abang”在家庭关系中通常是什么意思？','[{"id":"a","learning_text":"Saudara lelaki yang lebih tua","translation_text":"哥哥／年长的兄弟"},{"id":"b","learning_text":"Saudara perempuan yang lebih muda","translation_text":"妹妹／年幼的姐妹"},{"id":"c","learning_text":"Nenek","translation_text":"祖母"},{"id":"d","learning_text":"Bapa saudara","translation_text":"叔叔"}]'::jsonb,'a','“Abang” merujuk kepada saudara lelaki yang lebih tua.','“Abang”指年长的兄弟。','approved','knowledge','ms','family-relationship',pg_catalog.now()),
('quiz-ms-zh-b020',1,'ms','zh','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Frasa manakah yang betul untuk bermaksud “segelas air”?','哪一个短语正确表示“一杯水”？','[{"id":"a","learning_text":"Segelas air","translation_text":"一杯水"},{"id":"b","learning_text":"Seekor air","translation_text":"一只水"},{"id":"c","learning_text":"Sebatang air","translation_text":"一根水"},{"id":"d","learning_text":"Sebiji air","translation_text":"一粒水"}]'::jsonb,'a','“Segelas” ialah penjodoh bilangan untuk air dalam gelas.','“Segelas”是表示一杯液体的量词表达。','approved','knowledge','ms','food-order-classifier',pg_catalog.now()),
('quiz-ms-zh-b021',1,'ms','zh','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Ayat manakah yang menyatakan bermain badminton sebagai hobi?','哪一句表达把打羽毛球作为爱好？','[{"id":"a","learning_text":"Hobi saya bermain badminton.","translation_text":"我的爱好是打羽毛球。"},{"id":"b","learning_text":"Saya badminton sangat.","translation_text":"我羽毛球非常。"},{"id":"c","learning_text":"Badminton saya kerana.","translation_text":"羽毛球我因为。"},{"id":"d","learning_text":"Hobi bermain saya badminton.","translation_text":"爱好打我的羽毛球。"}]'::jsonb,'a','“Hobi saya…” digunakan untuk memperkenalkan aktiviti kegemaran.','“Hobi saya……”用于介绍个人爱好。','approved','knowledge','ms','hobby-expression',pg_catalog.now()),
('quiz-ms-zh-b022',1,'ms','zh','ms-b-home-and-household','ms-topic-home-and-household','beginner','Ruang manakah yang biasanya digunakan untuk memasak?','通常在哪个房间做饭？','[{"id":"a","learning_text":"Dapur","translation_text":"厨房"},{"id":"b","learning_text":"Bilik tidur","translation_text":"卧室"},{"id":"c","learning_text":"Bilik mandi","translation_text":"浴室"},{"id":"d","learning_text":"Ruang tamu","translation_text":"客厅"}]'::jsonb,'a','“Dapur” ialah ruang untuk menyediakan dan memasak makanan.','“Dapur”是准备和烹饪食物的厨房。','approved','knowledge','ms','room-vocabulary',pg_catalog.now()),
('quiz-ms-zh-b023',1,'ms','zh','ms-b-places-and-directions','ms-places-and-directions','beginner','Apakah arahan “belok kiri”?','“belok kiri”指示对方怎么走？','[{"id":"a","learning_text":"Belok ke kiri","translation_text":"向左转"},{"id":"b","learning_text":"Belok ke kanan","translation_text":"向右转"},{"id":"c","learning_text":"Jalan terus","translation_text":"直走"},{"id":"d","learning_text":"Berhenti di sini","translation_text":"在这里停下"}]'::jsonb,'a','“Kiri” bermaksud sebelah kiri; “belok kiri” ialah arahan membelok ke kiri.','“Kiri”表示左边，因此“belok kiri”意为向左转。','approved','knowledge','ms','direction-instruction',pg_catalog.now()),
('quiz-ms-zh-b024',1,'ms','zh','ms-b-shopping-and-prices','ms-shopping-and-prices','beginner','Soalan manakah yang bertanya tentang harga sesuatu barang?','哪一句是在询问商品价格？','[{"id":"a","learning_text":"Berapakah harga barang ini?","translation_text":"这件商品多少钱？"},{"id":"b","learning_text":"Di manakah barang ini?","translation_text":"这件商品在哪里？"},{"id":"c","learning_text":"Siapakah membeli barang ini?","translation_text":"谁买了这件商品？"},{"id":"d","learning_text":"Bilakah barang ini tiba?","translation_text":"这件商品什么时候到？"}]'::jsonb,'a','“Berapakah harga…” ialah cara biasa untuk bertanya tentang harga.','“Berapakah harga……”是询问价格的常用句式。','approved','knowledge','ms','asking-price',pg_catalog.now()),
('quiz-ms-zh-b025',1,'ms','zh','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Perkataan manakah yang menggunakan awalan meN- dengan betul bagi kata dasar “baca”?','哪个词正确使用 meN- 前缀构成“baca”的动词？','[{"id":"a","learning_text":"membaca","translation_text":"阅读"},{"id":"b","learning_text":"membacaan","translation_text":"阅读（名词）"},{"id":"c","learning_text":"dibaca","translation_text":"被阅读"},{"id":"d","learning_text":"bacaan","translation_text":"读物"}]'::jsonb,'a','Kata dasar “baca” berubah menjadi “membaca” apabila menerima awalan meN-.','词根“baca”加上 meN- 前缀后构成“membaca”。','approved','knowledge','ms','men-prefix-verb',pg_catalog.now()),
('quiz-ms-zh-b026',1,'ms','zh','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah yang sesuai untuk tiga ekor kucing?','表示三只猫时，哪个量词合适？','[{"id":"a","learning_text":"Tiga ekor kucing","translation_text":"三只猫"},{"id":"b","learning_text":"Tiga batang kucing","translation_text":"三根猫"},{"id":"c","learning_text":"Tiga helai kucing","translation_text":"三张猫"},{"id":"d","learning_text":"Tiga biji kucing","translation_text":"三粒猫"}]'::jsonb,'a','Gunakan “ekor” untuk haiwan.','动物通常使用量词“ekor”。','approved','knowledge','ms','animal-classifier',pg_catalog.now()),
('quiz-ms-zh-b027',1,'ms','zh','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah yang dirujuk oleh perkataan “kanak-kanak”?','“kanak-kanak”指什么？','[{"id":"a","learning_text":"Kanak-kanak","translation_text":"儿童"},{"id":"b","learning_text":"Orang dewasa","translation_text":"成年人"},{"id":"c","learning_text":"Bilik darjah","translation_text":"教室"},{"id":"d","learning_text":"Rumah keluarga","translation_text":"家庭住宅"}]'::jsonb,'a','“Kanak-kanak” ialah kata ganda yang merujuk kepada golongan kanak-kanak.','“Kanak-kanak”是表示儿童的重叠词。','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-zh-b028',1,'ms','zh','ms-i-aspek-perbuatan','ms-aspect','intermediate','Perkataan manakah yang menunjukkan perbuatan sedang berlaku?','哪个词表示动作正在进行？','[{"id":"a","learning_text":"sedang","translation_text":"正在"},{"id":"b","learning_text":"telah","translation_text":"已经"},{"id":"c","learning_text":"akan","translation_text":"将会"},{"id":"d","learning_text":"pernah","translation_text":"曾经"}]'::jsonb,'a','“Sedang” menandakan perbuatan yang sedang berlangsung.','“Sedang”表示动作正在进行。','approved','knowledge','ms','ongoing-aspect',pg_catalog.now()),
('quiz-ms-zh-b029',1,'ms','zh','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang betul: “Buku itu ___ atas meja.”','选择正确的介词：“Buku itu ___ atas meja.”','[{"id":"a","learning_text":"di","translation_text":"在"},{"id":"b","learning_text":"ke","translation_text":"去"},{"id":"c","learning_text":"daripada","translation_text":"来自"},{"id":"d","learning_text":"kepada","translation_text":"给（接受者）"}]'::jsonb,'a','“Di” menandakan tempat; “di atas meja” bermaksud berada di atas meja.','“Di”表示地点；“di atas meja”意为在桌子上。','approved','knowledge','ms','location-preposition',pg_catalog.now()),
('quiz-ms-zh-b030',1,'ms','zh','ms-i-kata-hubung','ms-conjunctions','intermediate','Kata hubung manakah paling sesuai: “___ hujan, mereka meneruskan perjalanan.”','哪个连词最适合填入：“___ hujan, mereka meneruskan perjalanan.”','[{"id":"a","learning_text":"Walaupun","translation_text":"虽然"},{"id":"b","learning_text":"Kerana","translation_text":"因为"},{"id":"c","learning_text":"Supaya","translation_text":"为了"},{"id":"d","learning_text":"Sebelum","translation_text":"之前"}]'::jsonb,'a','“Walaupun” memperkenalkan maksud pertentangan atau konsesi.','“Walaupun”用于引出让步或转折关系。','approved','knowledge','ms','contrast-conjunction',pg_catalog.now()),
('quiz-ms-zh-b031',1,'ms','zh','ms-i-perbandingan','ms-comparison','intermediate','Pilih bentuk perbandingan yang betul: “Menara A lebih tinggi ___ Menara B.”','选择正确的比较结构：“Menara A lebih tinggi ___ Menara B.”','[{"id":"a","learning_text":"daripada","translation_text":"比"},{"id":"b","learning_text":"kepada","translation_text":"给"},{"id":"c","learning_text":"dengan","translation_text":"和"},{"id":"d","learning_text":"untuk","translation_text":"为了"}]'::jsonb,'a','Gunakan “lebih … daripada” untuk membandingkan dua perkara.','使用“lebih……daripada”比较两个事物。','approved','knowledge','ms','comparative-structure',pg_catalog.now()),
('quiz-ms-zh-b032',1,'ms','zh','ms-i-kata-penguat','ms-intensifiers','intermediate','Perkataan manakah menguatkan kata adjektif dalam “Cuaca hari ini ___ panas”?','哪个词能加强句子“Cuaca hari ini ___ panas”中的形容词语气？','[{"id":"a","learning_text":"sangat","translation_text":"非常"},{"id":"b","learning_text":"tetapi","translation_text":"但是"},{"id":"c","learning_text":"kerana","translation_text":"因为"},{"id":"d","learning_text":"sejak","translation_text":"自从"}]'::jsonb,'a','“Sangat” menguatkan kata adjektif “panas”.','“Sangat”加强形容词“panas”的程度。','approved','knowledge','ms','intensifier-choice',pg_catalog.now()),
('quiz-ms-zh-b033',1,'ms','zh','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Kata hubung manakah yang betul untuk menggabungkan idea “Saya belajar” dan “adik bermain”?','哪个连词能正确连接“我学习”和“弟弟玩耍”这两个意思？','[{"id":"a","learning_text":"manakala","translation_text":"而／与此同时"},{"id":"b","learning_text":"kerana","translation_text":"因为"},{"id":"c","learning_text":"supaya","translation_text":"为了"},{"id":"d","learning_text":"sehingga","translation_text":"直到"}]'::jsonb,'a','“Manakala” boleh menghubungkan dua klausa yang berbeza atau selari.','“Manakala”可连接两个对照或并列的分句。','approved','knowledge','ms','compound-clause',pg_catalog.now()),
('quiz-ms-zh-b034',1,'ms','zh','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Penanda manakah yang jelas memperkenalkan kesan?','哪个连接词明确引出结果？','[{"id":"a","learning_text":"Oleh itu","translation_text":"因此"},{"id":"b","learning_text":"Walaupun","translation_text":"虽然"},{"id":"c","learning_text":"Sebaliknya","translation_text":"相反地"},{"id":"d","learning_text":"Namun","translation_text":"然而"}]'::jsonb,'a','“Oleh itu” memperkenalkan akibat atau hasil.','“Oleh itu”用于引出后果或结果。','approved','knowledge','ms','cause-effect-linker',pg_catalog.now()),
('quiz-ms-zh-b035',1,'ms','zh','ms-i-conditionals','ms-topic-conditionals','intermediate','Perkataan manakah yang memperkenalkan syarat?','哪个词用于引出条件？','[{"id":"a","learning_text":"sekiranya","translation_text":"如果／倘若"},{"id":"b","learning_text":"walaupun","translation_text":"虽然"},{"id":"c","learning_text":"sementara","translation_text":"当……时"},{"id":"d","learning_text":"malah","translation_text":"而且"}]'::jsonb,'a','“Sekiranya” digunakan untuk memperkenalkan keadaan bersyarat.','“Sekiranya”用于引出条件情境。','approved','knowledge','ms','conditional-clause',pg_catalog.now()),
('quiz-ms-zh-b036',1,'ms','zh','ms-i-relative-clauses','ms-topic-relative-clauses','intermediate','Perkataan manakah menghubungkan kata nama dengan klausa yang menerangkannya?','哪个词把名词与描述它的从句连接起来？','[{"id":"a","learning_text":"yang","translation_text":"……的／关系从句标记"},{"id":"b","learning_text":"dan","translation_text":"和"},{"id":"c","learning_text":"atau","translation_text":"或者"},{"id":"d","learning_text":"tetapi","translation_text":"但是"}]'::jsonb,'a','“Yang” memperkenalkan klausa relatif yang menerangkan kata nama.','“Yang”引导描述名词的关系从句。','approved','knowledge','ms','relative-clause-marker',pg_catalog.now()),
('quiz-ms-zh-b037',1,'ms','zh','ms-a-ragam-bahasa','ms-register','advanced','Pembuka kata manakah paling sesuai untuk surat rasmi kepada organisasi?','给机构写正式信函时，哪种称呼最合适？','[{"id":"a","learning_text":"Tuan/Puan,","translation_text":"尊敬的先生／女士："},{"id":"b","learning_text":"Hai semua!","translation_text":"大家好！"},{"id":"c","learning_text":"Oi,","translation_text":"喂！"},{"id":"d","learning_text":"Apa cerita?","translation_text":"最近怎样？"}]'::jsonb,'a','“Tuan/Puan” ialah panggilan hormat yang lazim dalam surat rasmi.','“Tuan/Puan”是正式信函中常见的尊称。','approved','knowledge','ms','formal-register',pg_catalog.now()),
('quiz-ms-zh-b038',1,'ms','zh','ms-a-wacana-penanda','ms-discourse-markers','advanced','Penanda wacana manakah paling sesuai untuk menunjukkan pertentangan dengan isi sebelumnya?','哪个篇章连接词最适合表示与前文观点相反？','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"然而／尽管如此"},{"id":"b","learning_text":"Selain itu","translation_text":"此外"},{"id":"c","learning_text":"Seterusnya","translation_text":"接下来"},{"id":"d","learning_text":"Kesimpulannya","translation_text":"总而言之"}]'::jsonb,'a','“Walau bagaimanapun” menandakan pertentangan atau pengecualian terhadap isi sebelumnya.','“Walau bagaimanapun”表示转折或补充限制。','approved','knowledge','ms','discourse-contrast',pg_catalog.now()),
('quiz-ms-zh-b039',1,'ms','zh','ms-a-penyuntingan','ms-editing','advanced','Pindaan manakah menghapuskan pengulangan yang tidak perlu tanpa mengubah maksud?','哪项修改在保留原意的同时消除了不必要的重复？','[{"id":"a","learning_text":"Para peserta diminta hadir pada pukul lapan.","translation_text":"请参与者于八点出席。"},{"id":"b","learning_text":"Semua para peserta diminta hadir pada pukul lapan.","translation_text":"所有参与者们请于八点出席。"},{"id":"c","learning_text":"Para semua peserta diminta hadir pada pukul lapan.","translation_text":"全部所有参与者请于八点出席。"},{"id":"d","learning_text":"Peserta-peserta semua para diminta hadir.","translation_text":"参与者们全部所有请出席。"}]'::jsonb,'a','“Para peserta” sudah menunjukkan kumpulan yang ramai; penambahan “semua” tidak diperlukan.','“Para peserta”已经表示复数群体，再加“semua”会造成重复。','approved','knowledge','ms','editing-clarity',pg_catalog.now()),
('quiz-ms-zh-b040',1,'ms','zh','ms-a-ayat-pasif','ms-passive-voice','advanced','Pilih bentuk pasif yang betul bagi ayat “Siti membaca buku itu.”','选择句子“Siti membaca buku itu.”的正确被动形式。','[{"id":"a","learning_text":"Buku itu dibaca oleh Siti.","translation_text":"这本书由Siti阅读。"},{"id":"b","learning_text":"Buku itu membaca Siti.","translation_text":"这本书阅读Siti。"},{"id":"c","learning_text":"Siti dibaca oleh buku itu.","translation_text":"Siti被这本书阅读。"},{"id":"d","learning_text":"Dibaca buku itu Siti oleh.","translation_text":"阅读这本书Siti由。"}]'::jsonb,'a','Objek menjadi fokus ayat dan menerima bentuk pasif berawalan di- iaitu “dibaca”.','宾语成为句子焦点，并使用带有 di- 前缀的被动形式“dibaca”。','approved','knowledge','ms','passive-voice-focus',pg_catalog.now()),
('quiz-ms-zh-b041',1,'ms','zh','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Pilihan manakah paling baik untuk mengelakkan pengulangan kata nama yang sama dalam ayat berturutan?','哪种选择最能避免在相邻句子中重复同一个名词？','[{"id":"a","learning_text":"Gunakan kata ganti nama yang rujukannya jelas.","translation_text":"使用指代明确的代词。"},{"id":"b","learning_text":"Ulang kata nama yang sama dalam setiap ayat.","translation_text":"每句都重复同一个名词。"},{"id":"c","learning_text":"Gugurkan semua subjek tanpa sebab.","translation_text":"无故省略所有主语。"},{"id":"d","learning_text":"Tukar topik pada setiap ayat.","translation_text":"每句都更换主题。"}]'::jsonb,'a','Rujukan kata ganti nama yang jelas menghubungkan ayat tanpa mengelirukan pembaca.','明确的代词指代能连接句子，同时避免读者混淆。','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-zh-b042',1,'ms','zh','ms-a-hujah-berasas','ms-reasoned-argument','advanced','Unsur manakah yang memberikan sokongan kepada sesuatu hujah?','哪项内容能为论点提供支持？','[{"id":"a","learning_text":"Bukti yang relevan","translation_text":"相关证据"},{"id":"b","learning_text":"Pendapat tanpa alasan","translation_text":"没有理由的意见"},{"id":"c","learning_text":"Pengulangan dakwaan","translation_text":"重复论断"},{"id":"d","learning_text":"Serangan terhadap penulis","translation_text":"攻击作者"}]'::jsonb,'a','Bukti yang relevan menyokong dakwaan dan mengukuhkan hujah.','相关证据能支持论点，使论证更有说服力。','approved','knowledge','ms','argument-evidence',pg_catalog.now()),
('quiz-ms-zh-b043',1,'ms','zh','ms-a-variasi-struktur','ms-sentence-variation','advanced','Ayat manakah menggunakan frasa tempat di hadapan untuk mempelbagaikan struktur secara semula jadi?','哪一句自然地把地点短语放在句首，以变化句子结构？','[{"id":"a","learning_text":"Di tepi sungai itu, beberapa keluarga berkelah.","translation_text":"在那条河边，几户家庭正在野餐。"},{"id":"b","learning_text":"Beberapa keluarga di tepi sungai itu berkelah keluarga.","translation_text":"几户家庭在河边野餐家庭。"},{"id":"c","learning_text":"Berkelah beberapa keluarga sungai itu di tepi.","translation_text":"野餐几户家庭河边在。"},{"id":"d","learning_text":"Sungai itu beberapa keluarga di tepi berkelah.","translation_text":"那条河几户家庭边上野餐。"}]'::jsonb,'a','Frasa tempat di hadapan menetapkan latar sebelum klausa utama.','前置地点短语先交代场景，再引出主句。','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-zh-b044',1,'ms','zh','ms-a-parafrasa','ms-paraphrasing','advanced','Parafrasa manakah mengekalkan maksud “Penggunaan air perlu dikurangkan”?','哪项改写保留了“Penggunaan air perlu dikurangkan”（用水量需要减少）的意思？','[{"id":"a","learning_text":"Kita perlu menggunakan air dengan lebih sedikit.","translation_text":"我们需要减少用水。"},{"id":"b","learning_text":"Kita mesti menggunakan air sebanyak mungkin.","translation_text":"我们必须尽可能多用水。"},{"id":"c","learning_text":"Air tidak boleh digunakan langsung.","translation_text":"完全不能用水。"},{"id":"d","learning_text":"Penggunaan air akan meningkat.","translation_text":"用水量将会增加。"}]'::jsonb,'a','Parafrasa yang baik mengubah susunan atau pilihan kata tetapi mengekalkan maksud asal.','恰当的改写会改变措辞，但保留原意。','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-zh-b045',1,'ms','zh','ms-a-bacaan-kritis','ms-critical-reading','advanced','Butiran manakah paling berguna untuk menilai kredibiliti laporan dalam talian?','评估网络报道可信度时，哪项信息最有用？','[{"id":"a","learning_text":"Nama penulis, tarikh dan sumber bukti","translation_text":"作者姓名、日期和证据来源"},{"id":"b","learning_text":"Warna laman web sahaja","translation_text":"仅看网站颜色"},{"id":"c","learning_text":"Jumlah emoji dalam tajuk","translation_text":"标题中的表情符号数量"},{"id":"d","learning_text":"Panjang tajuk semata-mata","translation_text":"仅看标题长度"}]'::jsonb,'a','Nama penulis, tarikh penerbitan dan bukti yang boleh disemak membantu menilai kebolehpercayaan.','作者、发布日期和可追溯证据有助于判断可靠性。','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-zh-b046',1,'ms','zh','ms-a-argument-structure','ms-topic-argument-structure','advanced','Apakah susunan paling logik bagi hujah ringkas yang berasaskan bukti?','简短的证据型论证最合理的顺序是什么？','[{"id":"a","learning_text":"Dakwaan, bukti, huraian","translation_text":"论点、证据、解释"},{"id":"b","learning_text":"Bukti, kesimpulan, tajuk","translation_text":"证据、结论、标题"},{"id":"c","learning_text":"Huraian, tajuk, dakwaan","translation_text":"解释、标题、论点"},{"id":"d","learning_text":"Kesimpulan, dakwaan, bukti tanpa kaitan","translation_text":"结论、无关论点、证据"}]'::jsonb,'a','Hujah yang jelas menyatakan dakwaan, menyokongnya dengan bukti dan menghuraikan kaitannya.','清晰的论证先提出论点，再提供证据并解释两者的联系。','approved','knowledge','ms','argument-structure',pg_catalog.now()),
('quiz-ms-zh-b047',1,'ms','zh','ms-a-counterargument-and-rebuttal','ms-topic-counterargument-and-rebuttal','advanced','Apakah yang perlu dilakukan oleh sanggahan selepas hujah balas dikemukakan?','提出反方论点后，反驳应当做什么？','[{"id":"a","learning_text":"Menjawab hujah balas dengan alasan atau bukti yang relevan","translation_text":"用相关理由或证据回应反方论点"},{"id":"b","learning_text":"Mengabaikan semua pandangan lain","translation_text":"忽略所有其他观点"},{"id":"c","learning_text":"Mengulangi dakwaan tanpa penjelasan","translation_text":"不作解释地重复论点"},{"id":"d","learning_text":"Menyerang peribadi pihak lawan","translation_text":"人身攻击对方"}]'::jsonb,'a','Sanggahan menjawab hujah pihak lain dengan alasan atau bukti yang berkaitan.','反驳应使用相关理由或证据回应对方观点。','approved','knowledge','ms','counterargument-response',pg_catalog.now()),
('quiz-ms-zh-b048',1,'ms','zh','ms-a-source-credibility','ms-topic-source-credibility','advanced','Sumber manakah biasanya paling kukuh untuk menyemak dasar kerajaan semasa?','查询现行政府政策时，哪种来源通常最可靠？','[{"id":"a","learning_text":"Laman rasmi agensi kerajaan yang berkaitan","translation_text":"相关政府机构的官方网站"},{"id":"b","learning_text":"Komen tanpa nama di media sosial","translation_text":"社交媒体上的匿名评论"},{"id":"c","learning_text":"Mesej berantai yang tiada pautan","translation_text":"没有链接的转发消息"},{"id":"d","learning_text":"Iklan produk yang tidak berkaitan","translation_text":"无关产品广告"}]'::jsonb,'a','Laman rasmi agensi berkaitan biasanya menjadi rujukan utama bagi dasar agensi itu.','相关政府机构的官方网站通常是查询其政策的一手资料。','approved','knowledge','ms','source-credibility',pg_catalog.now()),
('quiz-ms-zh-b049',1,'ms','zh','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Anda tidak memahami arahan tugasan. Apakah cara yang paling sopan untuk meminta penjelasan?','您不明白作业说明。哪种方式最礼貌地请求解释？','[{"id":"a","learning_text":"Boleh cikgu terangkan sekali lagi?","translation_text":"老师，可以再解释一次吗？"},{"id":"b","learning_text":"Cikgu, terangkan sekarang!","translation_text":"老师，现在解释！"},{"id":"c","learning_text":"Saya tidak mahu mendengar arahan.","translation_text":"我不想听说明。"},{"id":"d","learning_text":"Awak mesti ulang semuanya.","translation_text":"你必须把所有内容重复一遍。"}]'::jsonb,'a','Ungkapan “Boleh …?” membentuk permintaan yang lebih sopan.','“Boleh …?”可以构成较礼貌的请求。','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-zh-b050',1,'ms','zh','ms-b-community-places','ms-topic-community-places','beginner','Di manakah seseorang biasanya meminjam buku untuk dibaca di luar premis?','人们通常在哪里借书带回去阅读？','[{"id":"a","learning_text":"Perpustakaan","translation_text":"图书馆"},{"id":"b","learning_text":"Klinik","translation_text":"诊所"},{"id":"c","learning_text":"Balai polis","translation_text":"警察局"},{"id":"d","learning_text":"Stesen minyak","translation_text":"加油站"}]'::jsonb,'a','Perpustakaan menyediakan perkhidmatan pinjaman bahan bacaan.','图书馆提供书籍借阅服务。','approved','knowledge','ms','community-place-vocabulary',pg_catalog.now()),
('quiz-ms-zh-b051',1,'ms','zh','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih kata kerja yang melengkapkan ayat: “Selepas pulang, saya ___ dan berehat.”','选择适合填入句子的动词：“回家后，我___然后休息。”','[{"id":"a","learning_text":"mandi","translation_text":"洗澡"},{"id":"b","learning_text":"semalam","translation_text":"昨晚"},{"id":"c","learning_text":"kerana","translation_text":"因为"},{"id":"d","learning_text":"tinggi","translation_text":"高"}]'::jsonb,'a','“Mandi” ialah kata kerja yang sesuai untuk kegiatan harian.','“Mandi”是适合描述日常活动的动词。','approved','knowledge','ms','daily-activity-verb',pg_catalog.now()),
('quiz-ms-zh-b052',1,'ms','zh','ms-b-family-and-people','ms-family-and-people','beginner','Apakah maksud frasa “kakak saya”?','短语“kakak saya”是什么意思？','[{"id":"a","learning_text":"kakak saya","translation_text":"我的姐姐"},{"id":"b","learning_text":"adik lelaki saya","translation_text":"我的弟弟"},{"id":"c","learning_text":"nenek saya","translation_text":"我的祖母"},{"id":"d","learning_text":"bapa saudara saya","translation_text":"我的叔叔／舅舅"}]'::jsonb,'a','“Kakak” merujuk saudara perempuan yang lebih tua; “saya” menunjukkan pemilikan atau hubungan dengan penutur.','“Kakak”指年长的姐妹，“saya”说明她与说话者的关系。','approved','knowledge','ms','older-sister-term',pg_catalog.now()),
('quiz-ms-zh-b053',1,'ms','zh','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Pilih frasa yang betul untuk memesan satu gelas air dalam bahasa Melayu.','选择正确的马来语短语，表示一杯水。','[{"id":"a","learning_text":"segelas air","translation_text":"一杯水"},{"id":"b","learning_text":"seekor air","translation_text":"一只水"},{"id":"c","learning_text":"sebatang air","translation_text":"一根水"},{"id":"d","learning_text":"sehelai air","translation_text":"一张水"}]'::jsonb,'a','“Segelas” ialah penjodoh bilangan untuk kandungan sebanyak satu gelas.','“Segelas”是表示一杯容量的量词短语。','approved','knowledge','ms','food-order-classifier',pg_catalog.now()),
('quiz-ms-zh-b054',1,'ms','zh','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Ayat manakah menyatakan kegiatan yang diminati sebagai hobi?','哪一句表示某人喜欢作为爱好的活动？','[{"id":"a","learning_text":"Hobi saya ialah berkebun.","translation_text":"我的爱好是园艺。"},{"id":"b","learning_text":"Saya berada di stesen.","translation_text":"我在车站。"},{"id":"c","learning_text":"Hari ini hari Isnin.","translation_text":"今天是星期一。"},{"id":"d","learning_text":"Buku itu di atas meja.","translation_text":"书在桌子上。"}]'::jsonb,'a','Frasa “Hobi saya ialah …” digunakan untuk memperkenalkan aktiviti kegemaran.','“Hobi saya ialah …”用于介绍喜爱的活动。','approved','knowledge','ms','hobby-expression',pg_catalog.now()),
('quiz-ms-zh-b055',1,'ms','zh','ms-b-home-and-household','ms-topic-home-and-household','beginner','Di ruang manakah seseorang biasanya tidur pada waktu malam?','人们通常晚上在哪个房间睡觉？','[{"id":"a","learning_text":"Bilik tidur","translation_text":"卧室"},{"id":"b","learning_text":"Dapur","translation_text":"厨房"},{"id":"c","learning_text":"Ruang tamu","translation_text":"客厅"},{"id":"d","learning_text":"Bilik mandi","translation_text":"浴室"}]'::jsonb,'a','“Bilik tidur” ialah ruang yang digunakan untuk tidur.','“Bilik tidur”是用于睡觉的房间。','approved','knowledge','ms','room-vocabulary',pg_catalog.now()),
('quiz-ms-zh-b056',1,'ms','zh','ms-b-places-and-directions','ms-places-and-directions','beginner','Jika kedai berada di sebelah kiri anda, frasa manakah menerangkan lokasinya?','如果商店在你的左边，哪个短语描述它的位置？','[{"id":"a","learning_text":"di sebelah kiri saya","translation_text":"在我的左边"},{"id":"b","learning_text":"ke sebelah kiri saya","translation_text":"朝我的左边"},{"id":"c","learning_text":"belok ke kiri","translation_text":"向左转"},{"id":"d","learning_text":"terus ke hadapan","translation_text":"直走"}]'::jsonb,'a','“Di sebelah kiri” menerangkan lokasi, bukan pergerakan.','“Di sebelah kiri”描述位置，而不是移动方向。','approved','knowledge','ms','direction-instruction',pg_catalog.now()),
('quiz-ms-zh-b057',1,'ms','zh','ms-b-shopping-and-prices','ms-shopping-and-prices','beginner','Apakah soalan yang sesuai untuk mengetahui harga sebuah beg?','询问一个包的价格，哪种问法合适？','[{"id":"a","learning_text":"Berapakah harga beg ini?","translation_text":"这个包多少钱？"},{"id":"b","learning_text":"Di manakah beg ini?","translation_text":"这个包在哪里？"},{"id":"c","learning_text":"Bilakah beg ini tiba?","translation_text":"这个包什么时候到？"},{"id":"d","learning_text":"Siapakah pemilik beg ini?","translation_text":"这个包是谁的？"}]'::jsonb,'a','“Berapakah harga …?” ialah bentuk soalan untuk bertanya harga.','“Berapakah harga …?”是询问价格的常见句式。','approved','knowledge','ms','asking-price',pg_catalog.now()),
('quiz-ms-zh-b058',1,'ms','zh','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang menyatakan tempat asal seseorang, bukan tempat tinggal sekarang.','选择说明某人来自哪里，而不是目前住在哪里的句子。','[{"id":"a","learning_text":"Saya berasal dari Perlis.","translation_text":"我来自玻璃市。"},{"id":"b","learning_text":"Saya tinggal di Perlis.","translation_text":"我住在玻璃市。"},{"id":"c","learning_text":"Saya pergi ke Perlis.","translation_text":"我要去玻璃市。"},{"id":"d","learning_text":"Saya suka Perlis.","translation_text":"我喜欢玻璃市。"}]'::jsonb,'a','“Berasal dari” menyatakan asal seseorang; “tinggal di” menyatakan tempat menetap.','“Berasal dari”表示来自哪里；“tinggal di”表示居住地点。','approved','knowledge','ms','residence-statement',pg_catalog.now()),
('quiz-ms-zh-b059',1,'ms','zh','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Pilih kata kerja berawalan meN- yang betul daripada kata dasar “sapu”.','选择由词根“sapu”正确构成的 meN- 前缀动词。','[{"id":"a","learning_text":"menyapu","translation_text":"扫地"},{"id":"b","learning_text":"mensapu","translation_text":"错误形式：保留词根开头的 s"},{"id":"c","learning_text":"memsapu","translation_text":"错误形式：多加 m"},{"id":"d","learning_text":"mengsapu","translation_text":"错误形式：多加 ng"}]'::jsonb,'a','Huruf awal “s” dalam kata dasar gugur dan digantikan dengan bentuk “meny-”: menyapu.','词根开头的“s”脱落，并采用“meny-”形式：menyapu。','approved','knowledge','ms','meN-prefix-context',pg_catalog.now()),
('quiz-ms-zh-b060',1,'ms','zh','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah sesuai untuk sehelai kertas?','哪一个量词适合一张纸？','[{"id":"a","learning_text":"sehelai kertas","translation_text":"一张纸"},{"id":"b","learning_text":"seekor kertas","translation_text":"一只纸"},{"id":"c","learning_text":"sebatang kertas","translation_text":"一根纸"},{"id":"d","learning_text":"sebiji kertas","translation_text":"一颗纸"}]'::jsonb,'a','“Helai” digunakan untuk benda nipis dan leper seperti kertas.','“Helai”用于纸张等薄而扁平的物品。','approved','knowledge','ms','classifier-for-flat-items',pg_catalog.now()),
('quiz-ms-zh-b061',1,'ms','zh','ms-i-kata-ganda','ms-reduplication','intermediate','Apakah maksud kata ganda “kanak-kanak”?','重叠词“kanak-kanak”是什么意思？','[{"id":"a","learning_text":"kanak-kanak","translation_text":"儿童"},{"id":"b","learning_text":"orang dewasa","translation_text":"成年人"},{"id":"c","learning_text":"bilik darjah","translation_text":"教室"},{"id":"d","learning_text":"guru","translation_text":"教师"}]'::jsonb,'a','“Kanak-kanak” ialah bentuk kata ganda yang merujuk golongan anak atau budak.','“Kanak-kanak”是重叠形式，指儿童。','approved','knowledge','ms','reduplication-meaning',pg_catalog.now()),
('quiz-ms-zh-b062',1,'ms','zh','ms-i-aspek-perbuatan','ms-aspect','intermediate','Dalam ayat “Mereka sedang berbincang”, apakah fungsi perkataan “sedang”?','在“Mereka sedang berbincang”中，“sedang”有什么作用？','[{"id":"a","learning_text":"Menunjukkan perbuatan sedang berlangsung","translation_text":"表示动作正在进行"},{"id":"b","learning_text":"Menunjukkan perbuatan yang belum bermula","translation_text":"表示动作尚未开始"},{"id":"c","learning_text":"Menunjukkan tempat","translation_text":"表示地点"},{"id":"d","learning_text":"Menunjukkan pemilikan","translation_text":"表示所属关系"}]'::jsonb,'a','“Sedang” menandakan perbuatan yang berlaku pada waktu rujukan.','“Sedang”表示动作在所指时间正在进行。','approved','knowledge','ms','ongoing-aspect',pg_catalog.now()),
('quiz-ms-zh-b063',1,'ms','zh','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang melengkapkan ayat: “Mereka bergerak ___ dewan utama.”','选择合适的介词完成句子：“他们前往主礼堂。”','[{"id":"a","learning_text":"ke","translation_text":"到／向"},{"id":"b","learning_text":"di","translation_text":"在"},{"id":"c","learning_text":"daripada","translation_text":"从"},{"id":"d","learning_text":"dengan","translation_text":"和"}]'::jsonb,'a','“Ke” menunjukkan arah atau destinasi pergerakan.','“Ke”表示移动的方向或目的地。','approved','knowledge','ms','destination-preposition',pg_catalog.now()),
('quiz-ms-zh-b064',1,'ms','zh','ms-i-kata-hubung','ms-conjunctions','intermediate','Pilih kata hubung yang sesuai: “___ hujan, perlawanan diteruskan.”','选择合适的连词：“___下雨，比赛仍继续进行。”','[{"id":"a","learning_text":"Walaupun","translation_text":"虽然"},{"id":"b","learning_text":"Kerana","translation_text":"因为"},{"id":"c","learning_text":"Supaya","translation_text":"为了"},{"id":"d","learning_text":"Sebelum","translation_text":"之前"}]'::jsonb,'a','“Walaupun” memperkenalkan keadaan yang berlawanan dengan hasil yang dinyatakan.','“Walaupun”引出与后续结果形成让步关系的情况。','approved','knowledge','ms','contrast-conjunction',pg_catalog.now()),
('quiz-ms-zh-b065',1,'ms','zh','ms-i-perbandingan','ms-comparison','intermediate','Pilih ayat perbandingan yang menggunakan “lebih … daripada” dengan betul.','选择正确使用“lebih … daripada”结构的比较句。','[{"id":"a","learning_text":"Bangunan A lebih tinggi daripada bangunan B.","translation_text":"A楼比B楼高。"},{"id":"b","learning_text":"Bangunan A paling tinggi daripada bangunan B.","translation_text":"A楼是比B楼最高。"},{"id":"c","learning_text":"Bangunan A tinggi lebih bangunan B.","translation_text":"A楼高更多B楼。"},{"id":"d","learning_text":"Bangunan A lebih daripada tinggi bangunan B.","translation_text":"A楼更比高B楼。"}]'::jsonb,'a','Struktur “lebih + kata adjektif + daripada” membentuk perbandingan.','“lebih + 形容词 + daripada”用于构成比较句。','approved','knowledge','ms','comparative-structure',pg_catalog.now()),
('quiz-ms-zh-b066',1,'ms','zh','ms-i-kata-penguat','ms-intensifiers','intermediate','Perkataan manakah menguatkan kata adjektif dalam frasa “___ menarik”?','哪个词可以加强短语“___ menarik”（有趣）的程度？','[{"id":"a","learning_text":"sangat","translation_text":"非常"},{"id":"b","learning_text":"tetapi","translation_text":"但是"},{"id":"c","learning_text":"kerana","translation_text":"因为"},{"id":"d","learning_text":"apabila","translation_text":"当……时"}]'::jsonb,'a','“Sangat” ialah kata penguat yang hadir sebelum kata adjektif dalam frasa ini.','在这个短语中，“sangat”是置于形容词前的程度副词。','approved','knowledge','ms','intensifier-choice',pg_catalog.now()),
('quiz-ms-zh-b067',1,'ms','zh','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Pilih ayat majmuk yang menggabungkan dua kegiatan dengan kata hubung yang sesuai.','选择使用合适连词连接两项活动的复合句。','[{"id":"a","learning_text":"Aina membaca buku dan adiknya menulis nota.","translation_text":"Aina读书，她的弟弟／妹妹做笔记。"},{"id":"b","learning_text":"Aina membaca buku kerana adiknya.","translation_text":"Aina读书，因为她的弟弟／妹妹。"},{"id":"c","learning_text":"Aina membaca buku apabila meja.","translation_text":"Aina读书，当桌子。"},{"id":"d","learning_text":"Aina membaca buku walaupun dan.","translation_text":"Aina读书，虽然和。"}]'::jsonb,'a','“Dan” menghubungkan dua klausa yang setara dalam ayat majmuk gabungan.','“Dan”在并列复合句中连接两个地位相同的分句。','approved','knowledge','ms','compound-clause',pg_catalog.now()),
('quiz-ms-zh-b068',1,'ms','zh','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Pilih penanda yang sesuai untuk memperkenalkan kesan: “Jalan licin; ___, pemandu memperlahankan kenderaan.”','选择表示结果的连接词：“道路湿滑；___，司机减慢车速。”','[{"id":"a","learning_text":"oleh itu","translation_text":"因此"},{"id":"b","learning_text":"walaupun","translation_text":"虽然"},{"id":"c","learning_text":"sebaliknya","translation_text":"相反"},{"id":"d","learning_text":"sementara","translation_text":"与此同时"}]'::jsonb,'a','“Oleh itu” memperkenalkan kesan atau tindakan yang terhasil daripada sebab sebelumnya.','“Oleh itu”引出前述原因所产生的结果或行动。','approved','knowledge','ms','cause-effect-linker',pg_catalog.now()),
('quiz-ms-zh-b069',1,'ms','zh','ms-a-ragam-bahasa','ms-register','advanced','Anda menulis surat rasmi kepada pegawai yang tidak dikenali. Sapaan manakah paling sesuai?','你要给一位不认识的官员写正式信件。哪种称呼最合适？','[{"id":"a","learning_text":"Tuan/Puan","translation_text":"先生／女士"},{"id":"b","learning_text":"Hai semua","translation_text":"大家好"},{"id":"c","learning_text":"Oi kawan","translation_text":"喂，朋友"},{"id":"d","learning_text":"Apa cerita?","translation_text":"最近怎样？"}]'::jsonb,'a','“Tuan/Puan” ialah sapaan formal yang sesuai apabila nama penerima tidak diketahui.','当不知道收件人姓名时，“Tuan/Puan”是合适的正式称呼。','approved','knowledge','ms','formal-register-choice',pg_catalog.now()),
('quiz-ms-zh-b070',1,'ms','zh','ms-a-ragam-bahasa','ms-register','advanced','Pilih ayat yang mengekalkan laras bahasa rasmi ketika membuat permohonan.','选择在提出申请时保持正式语体的句子。','[{"id":"a","learning_text":"Saya ingin memohon pertimbangan pihak tuan.","translation_text":"本人谨此请求贵方予以考虑。"},{"id":"b","learning_text":"Aku nak benda itu sekarang.","translation_text":"我现在就要那个东西。"},{"id":"c","learning_text":"Kau kena bagi jawapan cepat.","translation_text":"你必须快点给答复。"},{"id":"d","learning_text":"Bagi saya, boleh?","translation_text":"给我，可以吗？"}]'::jsonb,'a','“Saya ingin memohon…” ialah bentuk permohonan yang sopan dan formal.','“Saya ingin memohon…”是礼貌且正式的申请表达。','approved','knowledge','ms','formal-application-request',pg_catalog.now()),
('quiz-ms-zh-b071',1,'ms','zh','ms-a-wacana-penanda','ms-discourse-markers','advanced','Pilih penanda wacana yang paling sesuai untuk memperkenalkan pengecualian terhadap hujah sebelumnya.','选择最适合引出对前述论点作出限定的篇章连接语。','[{"id":"a","learning_text":"Walau bagaimanapun","translation_text":"然而／尽管如此"},{"id":"b","learning_text":"Selain itu","translation_text":"此外"},{"id":"c","learning_text":"Sebagai contoh","translation_text":"例如"},{"id":"d","learning_text":"Kesimpulannya","translation_text":"总而言之"}]'::jsonb,'a','“Walau bagaimanapun” memperkenalkan maklumat yang berbeza atau mengehadkan kenyataan sebelumnya.','“Walau bagaimanapun”引出不同信息，或对前述陈述作出限定。','approved','knowledge','ms','discourse-connector-contrast',pg_catalog.now()),
('quiz-ms-zh-b072',1,'ms','zh','ms-a-wacana-penanda','ms-discourse-markers','advanced','Dalam esei, anda mahu memperkenalkan maklumat tambahan yang menyokong hujah. Penanda manakah paling sesuai?','在文章中，你想补充支持论点的信息。哪个连接语最合适？','[{"id":"a","learning_text":"Selain itu","translation_text":"此外"},{"id":"b","learning_text":"Walau bagaimanapun","translation_text":"然而"},{"id":"c","learning_text":"Sebaliknya","translation_text":"相反"},{"id":"d","learning_text":"Walaupun","translation_text":"虽然"}]'::jsonb,'a','“Selain itu” menambah maklumat yang berkaitan dengan perkara sebelumnya.','“Selain itu”用于补充与前文相关的信息。','approved','knowledge','ms','additive-discourse-marker',pg_catalog.now()),
('quiz-ms-zh-b073',1,'ms','zh','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling kemas tanpa pengulangan penanda jamak yang tidak perlu.','选择最简洁的句子，避免不必要地重复复数标记。','[{"id":"a","learning_text":"Para peserta menghadiri taklimat itu.","translation_text":"参与者出席了简报会。"},{"id":"b","learning_text":"Para peserta semua menghadiri taklimat itu.","translation_text":"所有参与者们都出席了简报会。"},{"id":"c","learning_text":"Para-para peserta menghadiri taklimat itu.","translation_text":"参与者们们出席了简报会。"},{"id":"d","learning_text":"Peserta para semua menghadiri taklimat itu.","translation_text":"参与者所有都出席了简报会。"}]'::jsonb,'a','“Para” sudah menandakan kumpulan jamak, maka “semua” tidak diperlukan dalam binaan ini.','“Para”已经表示复数群体，因此这个结构中不需要再加“semua”。','approved','knowledge','ms','avoid-redundant-plural-marking',pg_catalog.now()),
('quiz-ms-zh-b074',1,'ms','zh','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang mempunyai rujukan kata ganti nama yang paling jelas.','选择代词指代最清楚的句子。','[{"id":"a","learning_text":"Aina meminjam buku daripada Mira lalu memulangkannya kepada Mira pada petang itu.","translation_text":"Aina向Mira借了书，并在当天傍晚把书还给Mira。"},{"id":"b","learning_text":"Aina meminjam buku daripada Mira lalu dia memulangkannya kepada dia.","translation_text":"Aina向Mira借了书，然后她把书还给她。"},{"id":"c","learning_text":"Selepas itu, perkara tersebut berlaku kepada mereka.","translation_text":"之后，那件事发生在他们身上。"},{"id":"d","learning_text":"Mira memberitahu Aina bahawa dia perlu membawanya.","translation_text":"Mira告诉Aina她需要把它带来。"}]'::jsonb,'a','Mengulangi nama penerima apabila perlu dapat mengelakkan rujukan kata ganti nama yang kabur.','必要时重复收件人的姓名，可以避免代词指代不清。','approved','knowledge','ms','editing-pronoun-reference',pg_catalog.now()),
('quiz-ms-zh-b075',1,'ms','zh','ms-a-ayat-pasif','ms-passive-voice','advanced','Pilih ayat pasif yang mengekalkan maksud bahawa laporan itu disiapkan oleh Farah.','选择保留“报告由Farah完成”这一意思的被动句。','[{"id":"a","learning_text":"Laporan itu disiapkan oleh Farah.","translation_text":"报告由Farah完成。"},{"id":"b","learning_text":"Farah disiapkan oleh laporan itu.","translation_text":"Farah由报告完成。"},{"id":"c","learning_text":"Laporan itu menyiapkan Farah.","translation_text":"报告完成了Farah。"},{"id":"d","learning_text":"Farah sedang laporan itu siap.","translation_text":"Farah正在报告完成。"}]'::jsonb,'a','Dalam ayat pasif, perkara yang menerima perbuatan menjadi fokus dan pelaku boleh diperkenalkan dengan “oleh”.','被动句以动作承受者为重点，并可用“oleh”引出动作执行者。','approved','knowledge','ms','passive-voice-focus',pg_catalog.now()),
('quiz-ms-zh-b076',1,'ms','zh','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Dalam perenggan tentang para sukarelawan, kata ganti “mereka” paling tepat merujuk kepada siapa jika ayat sebelumnya menyebut kumpulan itu?','在一段关于志愿者的文字中，如果前一句提到该群体，“mereka”最恰当地指谁？','[{"id":"a","learning_text":"Kumpulan sukarelawan yang disebut sebelumnya","translation_text":"前文提到的志愿者群体"},{"id":"b","learning_text":"Pembaca yang tidak disebut","translation_text":"没有提到的读者"},{"id":"c","learning_text":"Satu objek yang tidak bernyawa","translation_text":"一个无生命物体"},{"id":"d","learning_text":"Penulis sahaja","translation_text":"只有作者本人"}]'::jsonb,'a','Kata ganti nama perlu mempunyai rujukan yang jelas dalam wacana.','代词在篇章中必须有明确的先行指代对象。','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-zh-b077',1,'ms','zh','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Pilih penghubung yang paling sesuai untuk merujuk semula kepada idea utama yang telah dihuraikan.','选择最适合回指前面已阐述的主要观点的连接表达。','[{"id":"a","learning_text":"Hal ini","translation_text":"这一点／这件事"},{"id":"b","learning_text":"Walaupun","translation_text":"虽然"},{"id":"c","learning_text":"Sebelum","translation_text":"之前"},{"id":"d","learning_text":"Sekiranya","translation_text":"如果"}]'::jsonb,'a','“Hal ini” boleh merujuk kepada idea atau keadaan yang telah dinyatakan sebelumnya.','“Hal ini”可以回指前文已经提到的观点或情况。','approved','knowledge','ms','cohesive-reference',pg_catalog.now()),
('quiz-ms-zh-b078',1,'ms','zh','ms-a-variasi-struktur','ms-sentence-variation','advanced','Dua ayat berturut-turut bermula dengan “Pihak sekolah”. Apakah suntingan terbaik untuk mempelbagaikan struktur tanpa mengubah maksud?','连续两个句子都以“Pihak sekolah”开头。哪种修改可以在不改变意思的情况下丰富句式？','[{"id":"a","learning_text":"Gunakan “Di sekolah” sebagai frasa pendahuluan pada ayat kedua.","translation_text":"在第二句使用“Di sekolah”作为前置短语。"},{"id":"b","learning_text":"Buang semua kata kerja daripada ayat kedua.","translation_text":"从第二句删除所有动词。"},{"id":"c","learning_text":"Tukar fakta dalam ayat pertama.","translation_text":"更改第一句的事实。"},{"id":"d","learning_text":"Ulang kedua-dua ayat dengan susunan yang sama.","translation_text":"以相同结构重复两个句子。"}]'::jsonb,'a','Frasa pendahuluan boleh mempelbagaikan permulaan ayat sambil mengekalkan makna.','前置短语可以丰富句子开头，同时保留原意。','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-zh-b079',1,'ms','zh','ms-a-variasi-struktur','ms-sentence-variation','advanced','Apakah tujuan menggabungkan ayat pendek dan ayat majmuk dalam penulisan?','写作中结合短句和复合句有什么目的？','[{"id":"a","learning_text":"Mewujudkan aliran dan penekanan yang lebih berkesan","translation_text":"让行文更流畅并形成更有效的强调"},{"id":"b","learning_text":"Menghapuskan semua tanda baca","translation_text":"删除所有标点符号"},{"id":"c","learning_text":"Menjadikan setiap ayat sama panjang","translation_text":"让每个句子长度相同"},{"id":"d","learning_text":"Mengelakkan penyampaian idea","translation_text":"避免表达观点"}]'::jsonb,'a','Variasi panjang dan struktur ayat membantu mengawal aliran serta penekanan.','句子长度和结构的变化有助于控制行文节奏和重点。','approved','knowledge','ms','sentence-variation',pg_catalog.now()),
('quiz-ms-zh-b080',1,'ms','zh','ms-a-parafrasa','ms-paraphrasing','advanced','Ayat asal: “Program itu meningkatkan penyertaan belia.” Parafrasa manakah mengekalkan maksud asal?','原句：“该计划提高了青年参与度。”哪种改写保留了原意？','[{"id":"a","learning_text":"Program tersebut menambah penglibatan golongan muda.","translation_text":"该计划增加了年轻人的参与。"},{"id":"b","learning_text":"Program itu mengurangkan penyertaan belia.","translation_text":"该计划减少了青年参与。"},{"id":"c","learning_text":"Belia membatalkan program tersebut.","translation_text":"年轻人取消了该计划。"},{"id":"d","learning_text":"Program itu hanya untuk golongan dewasa.","translation_text":"该计划只面向成年人。"}]'::jsonb,'a','Parafrasa yang baik menukar bentuk ungkapan tanpa mengubah hubungan makna utama.','好的改写会改变表达方式，但不改变主要含义。','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-zh-b081',1,'ms','zh','ms-a-parafrasa','ms-paraphrasing','advanced','Pilih parafrasa yang mengekalkan hubungan sebab dan hasil dalam ayat: “Hujan lebat menyebabkan acara ditangguhkan.”','选择保留“暴雨导致活动延期”这一因果关系的改写。','[{"id":"a","learning_text":"Acara ditangguhkan akibat hujan yang lebat.","translation_text":"活动因大雨而延期。"},{"id":"b","learning_text":"Acara diteruskan walaupun hujan lebat.","translation_text":"尽管下大雨，活动仍继续。"},{"id":"c","learning_text":"Hujan lebat berlaku selepas acara tamat.","translation_text":"活动结束后才下大雨。"},{"id":"d","learning_text":"Acara menyebabkan hujan turun.","translation_text":"活动导致下雨。"}]'::jsonb,'a','“Akibat” mengekalkan hubungan bahawa hujan lebat menjadi sebab penangguhan.','“Akibat”保留了大雨是延期原因这一关系。','approved','knowledge','ms','paraphrase-preserve-meaning',pg_catalog.now()),
('quiz-ms-zh-b082',1,'ms','zh','ms-a-bacaan-kritis','ms-critical-reading','advanced','Anda menemui dakwaan kesihatan tanpa nama penulis, tarikh atau rujukan. Apakah tindakan paling wajar?','你看到一则没有作者、日期或参考资料的健康说法。最恰当的做法是什么？','[{"id":"a","learning_text":"Semak dakwaan itu melalui sumber kesihatan yang berwibawa.","translation_text":"通过权威健康来源核实该说法。"},{"id":"b","learning_text":"Kongsi segera kerana tajuknya menarik.","translation_text":"因为标题有趣就立即分享。"},{"id":"c","learning_text":"Anggap dakwaan itu benar tanpa bukti.","translation_text":"没有证据也认为它是真的。"},{"id":"d","learning_text":"Gunakan bilangan tanda suka sebagai bukti ketepatan.","translation_text":"把点赞数量当作准确性的证明。"}]'::jsonb,'a','Dakwaan perlu disemak melalui sumber yang boleh dikenal pasti dan berwibawa.','应通过可识别且权威的来源核实相关说法。','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-zh-b083',1,'ms','zh','ms-a-bacaan-kritis','ms-critical-reading','advanced','Apakah ciri yang paling membantu menilai kebolehpercayaan laporan penyelidikan?','评估研究报告的可信度时，哪项特征最有帮助？','[{"id":"a","learning_text":"Kaedah, data dan sumber rujukan dinyatakan dengan jelas.","translation_text":"清楚说明研究方法、数据和参考来源。"},{"id":"b","learning_text":"Reka bentuk kulit yang berwarna-warni.","translation_text":"色彩鲜艳的封面设计。"},{"id":"c","learning_text":"Tajuk yang menggunakan huruf besar.","translation_text":"全部使用大写字母的标题。"},{"id":"d","learning_text":"Jumlah komen yang tinggi sahaja.","translation_text":"仅有大量评论。"}]'::jsonb,'a','Kaedah dan rujukan yang telus membolehkan pembaca menilai asas sesuatu dapatan.','透明的方法和参考资料能让读者评估研究结论的依据。','approved','knowledge','ms','source-evaluation',pg_catalog.now()),
('quiz-ms-zh-b084',1,'ms','zh','ms-a-argument-structure','ms-topic-argument-structure','advanced','Dalam hujah, apakah fungsi bukti yang relevan selepas sesuatu dakwaan dikemukakan?','在论证中提出主张后，相关证据有什么作用？','[{"id":"a","learning_text":"Menyokong dakwaan dengan asas yang boleh dinilai.","translation_text":"以可评估的依据支持主张。"},{"id":"b","learning_text":"Menggantikan semua penjelasan tanpa hubungan.","translation_text":"取代所有相关解释。"},{"id":"c","learning_text":"Mengalihkan perbincangan kepada topik lain.","translation_text":"把讨论转移到其他主题。"},{"id":"d","learning_text":"Mengulangi dakwaan tanpa maklumat tambahan.","translation_text":"不提供新信息地重复主张。"}]'::jsonb,'a','Bukti yang relevan memberikan asas untuk menilai sama ada dakwaan itu munasabah.','相关证据为评估主张是否合理提供依据。','approved','knowledge','ms','argument-structure',pg_catalog.now()),
('quiz-ms-zh-b085',1,'ms','zh','ms-b-greetings','ms-greetings','beginner','Seseorang bertanya “Apa khabar?” Apakah jawapan ringkas yang sesuai?','有人问“Apa khabar?”，哪种简短回答合适？','[{"id":"a","learning_text":"Khabar baik, terima kasih.","translation_text":"我很好，谢谢。"},{"id":"b","learning_text":"Nama saya Aina.","translation_text":"我叫Aina。"},{"id":"c","learning_text":"Saya tinggal di Ipoh.","translation_text":"我住在怡保。"},{"id":"d","learning_text":"Selamat tinggal.","translation_text":"再见。"}]'::jsonb,'a','“Khabar baik, terima kasih” ialah jawapan lazim untuk pertanyaan khabar.','“Khabar baik, terima kasih”是回应近况询问的常见说法。','approved','knowledge','ms','greeting-response-to-wellbeing',pg_catalog.now()),
('quiz-ms-zh-b086',1,'ms','zh','ms-b-personal-information','ms-personal-information','beginner','Pilih ayat yang memperkenalkan nama seseorang dengan betul.','选择正确介绍某人姓名的句子。','[{"id":"a","learning_text":"Nama saya Aina.","translation_text":"我叫Aina。"},{"id":"b","learning_text":"Saya nama Aina.","translation_text":"我名字Aina。"},{"id":"c","learning_text":"Nama kepada saya Aina.","translation_text":"我的名字给Aina。"},{"id":"d","learning_text":"Aina nama saya punya.","translation_text":"Aina我的名字拥有。"}]'::jsonb,'a','“Nama saya …” ialah susunan biasa untuk memperkenalkan nama.','“Nama saya …”是介绍姓名的常见语序。','approved','knowledge','ms','name-introduction',pg_catalog.now()),
('quiz-ms-zh-b087',1,'ms','zh','ms-b-basic-sentence-order','ms-basic-sentence-order','beginner','Dalam ayat “Aina membaca buku”, apakah susunan unsur ayat yang betul?','在“Aina membaca buku”中，正确的句子成分顺序是什么？','[{"id":"a","learning_text":"Subjek – kata kerja – objek","translation_text":"主语－动词－宾语"},{"id":"b","learning_text":"Objek – subjek – kata kerja","translation_text":"宾语－主语－动词"},{"id":"c","learning_text":"Kata kerja – objek – subjek","translation_text":"动词－宾语－主语"},{"id":"d","learning_text":"Subjek – objek – kata kerja","translation_text":"主语－宾语－动词"}]'::jsonb,'a','Ayat penyata mudah lazimnya mengikut susunan subjek, predikat dan objek apabila objek hadir.','简单陈述句在有宾语时通常采用主语、谓语／动词、宾语的顺序。','approved','knowledge','ms','simple-word-order',pg_catalog.now()),
('quiz-ms-zh-b088',1,'ms','zh','ms-b-asking-for-help','ms-topic-asking-for-help','beginner','Anda tidak dapat membuka fail tugasan. Apakah ungkapan yang sesuai untuk meminta bantuan rakan?','你无法打开作业文件。哪种表达适合向同学求助？','[{"id":"a","learning_text":"Boleh kamu bantu saya sebentar?","translation_text":"你可以帮我一下吗？"},{"id":"b","learning_text":"Kamu mesti buat kerja saya.","translation_text":"你必须替我做作业。"},{"id":"c","learning_text":"Jangan bercakap dengan saya.","translation_text":"不要跟我说话。"},{"id":"d","learning_text":"Saya tidak peduli tentang fail.","translation_text":"我不在乎这个文件。"}]'::jsonb,'a','“Boleh … bantu saya?” ialah permintaan bantuan yang sopan.','“Boleh … bantu saya?”是礼貌的求助表达。','approved','knowledge','ms','polite-help-request',pg_catalog.now()),
('quiz-ms-zh-b089',1,'ms','zh','ms-b-community-places','ms-topic-community-places','beginner','Jika seseorang memerlukan rawatan untuk demam, tempat manakah paling sesuai dikunjungi?','如果有人发烧需要治疗，最适合去哪里？','[{"id":"a","learning_text":"Klinik","translation_text":"诊所"},{"id":"b","learning_text":"Perpustakaan","translation_text":"图书馆"},{"id":"c","learning_text":"Pejabat pos","translation_text":"邮局"},{"id":"d","learning_text":"Pasar raya","translation_text":"超市"}]'::jsonb,'a','Klinik menyediakan perkhidmatan pemeriksaan dan rawatan kesihatan asas.','诊所提供基本的健康检查和治疗服务。','approved','knowledge','ms','community-service-place',pg_catalog.now()),
('quiz-ms-zh-b090',1,'ms','zh','ms-b-daily-activities','ms-topic-daily-activities','beginner','Pilih penanda urutan yang sesuai untuk melengkapkan ayat: “Saya bersarapan. ___, saya pergi ke sekolah.”','选择合适的顺序词：“我吃早餐。___，我去学校。”','[{"id":"a","learning_text":"Kemudian","translation_text":"然后"},{"id":"b","learning_text":"Walaupun","translation_text":"虽然"},{"id":"c","learning_text":"Kerana","translation_text":"因为"},{"id":"d","learning_text":"Tetapi","translation_text":"但是"}]'::jsonb,'a','“Kemudian” menunjukkan kegiatan yang berlaku selepas kegiatan sebelumnya.','“Kemudian”表示在前一项活动之后发生的活动。','approved','knowledge','ms','daily-sequence-marker',pg_catalog.now()),
('quiz-ms-zh-b091',1,'ms','zh','ms-b-family-and-people','ms-family-and-people','beginner','Pilih frasa pemilikan yang betul untuk menyatakan “their younger sibling”.','选择正确的马来语所属短语，表示“他们的弟弟／妹妹”。','[{"id":"a","learning_text":"adik mereka","translation_text":"他们的弟弟／妹妹"},{"id":"b","learning_text":"mereka adik","translation_text":"他们弟弟／妹妹"},{"id":"c","learning_text":"adik kepada mereka punya","translation_text":"弟弟／妹妹给他们拥有"},{"id":"d","learning_text":"mereka punya kepada adik","translation_text":"他们拥有给弟弟／妹妹"}]'::jsonb,'a','Kata ganti nama pemilik hadir selepas kata nama dalam frasa seperti “adik mereka”.','在“adik mereka”这样的短语中，所属代词放在名词之后。','approved','knowledge','ms','possessive-pronoun-order',pg_catalog.now()),
('quiz-ms-zh-b092',1,'ms','zh','ms-b-food-and-drink','ms-topic-food-and-drink','beginner','Apakah kata adjektif yang sesuai untuk menerangkan rasa limau yang masam?','哪个形容词适合描述酸橙的酸味？','[{"id":"a","learning_text":"masam","translation_text":"酸"},{"id":"b","learning_text":"manis","translation_text":"甜"},{"id":"c","learning_text":"pedas","translation_text":"辣"},{"id":"d","learning_text":"tawar","translation_text":"淡"}]'::jsonb,'a','“Masam” menerangkan rasa seperti limau atau cuka.','“Masam”描述酸橙或醋一类的酸味。','approved','knowledge','ms','taste-adjective',pg_catalog.now()),
('quiz-ms-zh-b093',1,'ms','zh','ms-b-hobbies-and-free-time','ms-topic-hobbies-and-free-time','beginner','Pilih ayat yang menyatakan minat terhadap aktiviti pada masa lapang.','选择表达对休闲活动感兴趣的句子。','[{"id":"a","learning_text":"Saya gemar berkebun pada hujung minggu.","translation_text":"我喜欢在周末园艺。"},{"id":"b","learning_text":"Saya berada di klinik semalam.","translation_text":"我昨天在诊所。"},{"id":"c","learning_text":"Cuaca hari ini mendung.","translation_text":"今天天气多云。"},{"id":"d","learning_text":"Buku itu milik guru.","translation_text":"那本书属于老师。"}]'::jsonb,'a','“Saya gemar …” digunakan untuk menyatakan minat atau kesukaan.','“Saya gemar …”用于表达兴趣或喜好。','approved','knowledge','ms','hobby-preference-expression',pg_catalog.now()),
('quiz-ms-zh-b094',1,'ms','zh','ms-b-home-and-household','ms-topic-home-and-household','beginner','Pilih parafrasa yang mengekalkan maksud ayat “Ada sebuah meja di ruang tamu”.','“Ada sebuah meja di ruang tamu”是什么意思？','[{"id":"a","learning_text":"Terdapat sebuah meja di ruang tamu.","translation_text":"客厅里有一张桌子。"},{"id":"b","learning_text":"Meja itu berada di luar rumah.","translation_text":"桌子在屋外。"},{"id":"c","learning_text":"Seseorang sedang mengalihkan meja itu.","translation_text":"有人正在搬桌子。"},{"id":"d","learning_text":"Ruang tamu itu ialah sebuah meja.","translation_text":"客厅是一张桌子。"}]'::jsonb,'a','Ayat ini menyatakan kewujudan sebuah meja di ruang tamu.','“Ada”表示某物在某处存在。','approved','knowledge','ms','existence-with-ada',pg_catalog.now()),
('quiz-ms-zh-b095',1,'ms','zh','ms-i-imbuhan-meN','ms-affixes-meN','intermediate','Apakah bentuk kata kerja berawalan meN- yang betul daripada kata dasar “pukul”?','由词根“pukul”构成的正确 meN- 前缀动词是什么？','[{"id":"a","learning_text":"memukul","translation_text":"打／敲"},{"id":"b","learning_text":"menpukul","translation_text":"错误：使用 n 前缀"},{"id":"c","learning_text":"mengpukul","translation_text":"错误：使用 ng 前缀"},{"id":"d","learning_text":"mempukul","translation_text":"错误：重复 p"}]'::jsonb,'a','Huruf “p” pada awal kata dasar gugur apabila menerima awalan meN- lalu terbentuk “memukul”.','词根开头的“p”在加 meN- 前缀时脱落，形成“memukul”。','approved','knowledge','ms','meN-prefix-p-to-m',pg_catalog.now()),
('quiz-ms-zh-b096',1,'ms','zh','ms-i-penjodoh-bilangan','ms-classifiers','intermediate','Penjodoh bilangan manakah sesuai untuk sebatang pensel?','哪一个量词适合一支铅笔？','[{"id":"a","learning_text":"batang","translation_text":"根／支"},{"id":"b","learning_text":"helai","translation_text":"张／片"},{"id":"c","learning_text":"ekor","translation_text":"只"},{"id":"d","learning_text":"biji","translation_text":"颗／个"}]'::jsonb,'a','“Batang” digunakan untuk benda panjang dan berbentuk silinder seperti pensel.','“Batang”用于铅笔等细长、近似圆柱形的物品。','approved','knowledge','ms','classifier-for-long-items',pg_catalog.now()),
('quiz-ms-zh-b097',1,'ms','zh','ms-i-kata-ganda','ms-reduplication','intermediate','Dalam konteks “Buku-buku itu disusun di rak”, apakah fungsi kata ganda “buku-buku”?','在“Buku-buku itu disusun di rak”中，“buku-buku”有什么作用？','[{"id":"a","learning_text":"Menunjukkan lebih daripada sebuah buku","translation_text":"表示不止一本书"},{"id":"b","learning_text":"Menunjukkan satu buku sahaja","translation_text":"只表示一本书"},{"id":"c","learning_text":"Menunjukkan pemilik buku","translation_text":"表示书的所有者"},{"id":"d","learning_text":"Menunjukkan tempat buku","translation_text":"表示书的位置"}]'::jsonb,'a','Penggandaan kata nama boleh menandakan bilangan jamak mengikut konteks.','名词重叠可根据语境表示复数。','approved','knowledge','ms','reduplication-plurality',pg_catalog.now()),
('quiz-ms-zh-b098',1,'ms','zh','ms-i-aspek-perbuatan','ms-aspect','intermediate','Dalam ayat “Mereka sudah menyiapkan laporan”, apakah maksud “sudah”?','在“Mereka sudah menyiapkan laporan”中，“sudah”表示什么？','[{"id":"a","learning_text":"Perbuatan telah selesai","translation_text":"动作已经完成"},{"id":"b","learning_text":"Perbuatan sedang berlangsung","translation_text":"动作正在进行"},{"id":"c","learning_text":"Perbuatan akan bermula","translation_text":"动作将要开始"},{"id":"d","learning_text":"Tempat laporan disimpan","translation_text":"报告存放的地点"}]'::jsonb,'a','“Sudah” menandakan perbuatan telah berlaku atau selesai.','“Sudah”表示动作已经发生或完成。','approved','knowledge','ms','completed-aspect-marker',pg_catalog.now()),
('quiz-ms-zh-b099',1,'ms','zh','ms-i-kata-sendi','ms-prepositions','intermediate','Pilih kata sendi yang betul: “Murid-murid belajar ___ perpustakaan.”','选择正确的介词：“学生在图书馆学习。”','[{"id":"a","learning_text":"di","translation_text":"在"},{"id":"b","learning_text":"ke","translation_text":"到"},{"id":"c","learning_text":"daripada","translation_text":"从"},{"id":"d","learning_text":"kepada","translation_text":"给"}]'::jsonb,'a','“Di” menandakan lokasi sesuatu kegiatan berlaku.','“Di”表示活动发生的地点。','approved','knowledge','ms','location-preposition',pg_catalog.now()),
('quiz-ms-zh-b100',1,'ms','zh','ms-i-kata-hubung','ms-conjunctions','intermediate','Pilih kata hubung yang menyatakan sebab: “Dia tidak hadir ___ demam.”','选择表示原因的连词：“他没有出席，___发烧。”','[{"id":"a","learning_text":"kerana","translation_text":"因为"},{"id":"b","learning_text":"walaupun","translation_text":"虽然"},{"id":"c","learning_text":"supaya","translation_text":"为了"},{"id":"d","learning_text":"semasa","translation_text":"当……时"}]'::jsonb,'a','“Kerana” memperkenalkan sebab bagi sesuatu keadaan atau tindakan.','“Kerana”引出某种情况或行动的原因。','approved','knowledge','ms','cause-conjunction',pg_catalog.now()),
('quiz-ms-zh-b101',1,'ms','zh','ms-i-perbandingan','ms-comparison','intermediate','Pilih ayat yang menggunakan kata penguat darjah tertinggi dengan betul.','选择正确使用最高级表达的句子。','[{"id":"a","learning_text":"Gunung itu paling tinggi di kawasan ini.","translation_text":"那座山是这个地区最高的。"},{"id":"b","learning_text":"Gunung itu lebih tinggi di kawasan ini.","translation_text":"那座山在这个地区更高。"},{"id":"c","learning_text":"Gunung itu tinggi daripada paling.","translation_text":"那座山高于最。"},{"id":"d","learning_text":"Gunung itu paling daripada tinggi.","translation_text":"那座山最比高。"}]'::jsonb,'a','“Paling” digunakan untuk menyatakan darjah tertinggi dalam kumpulan perbandingan.','“Paling”用于表示比较范围内的最高程度。','approved','knowledge','ms','superlative-structure',pg_catalog.now()),
('quiz-ms-zh-b102',1,'ms','zh','ms-i-kata-penguat','ms-intensifiers','intermediate','Dalam frasa “agak sukar”, apakah maksud kata penguat “agak”?','在短语“agak sukar”中，程度词“agak”是什么意思？','[{"id":"a","learning_text":"Pada tahap sederhana","translation_text":"达到中等程度"},{"id":"b","learning_text":"Pada tahap yang amat tinggi","translation_text":"达到极高程度"},{"id":"c","learning_text":"Langsung tidak","translation_text":"完全不"},{"id":"d","learning_text":"Pada tahap paling tinggi","translation_text":"达到最高程度"}]'::jsonb,'a','“Agak” menunjukkan darjah sederhana, bukan tahap yang paling tinggi.','“Agak”表示中等程度，而不是最高强度。','approved','knowledge','ms','moderate-intensifier',pg_catalog.now()),
('quiz-ms-zh-b103',1,'ms','zh','ms-i-ayat-majmuk','ms-compound-sentences','intermediate','Pilih kata hubung yang sesuai untuk menggabungkan dua klausa yang berlawanan: “Dia letih, ___ dia meneruskan kerja.”','选择连接两个相反分句的连词：“他很累，___仍继续工作。”','[{"id":"a","learning_text":"tetapi","translation_text":"但是"},{"id":"b","learning_text":"kerana","translation_text":"因为"},{"id":"c","learning_text":"supaya","translation_text":"为了"},{"id":"d","learning_text":"sebelum","translation_text":"之前"}]'::jsonb,'a','“Tetapi” menghubungkan klausa yang menunjukkan pertentangan.','“Tetapi”连接表达转折关系的分句。','approved','knowledge','ms','contrastive-compound-clause',pg_catalog.now()),
('quiz-ms-zh-b104',1,'ms','zh','ms-i-cause-and-effect','ms-topic-cause-and-effect','intermediate','Pilih penanda yang sesuai untuk memperkenalkan kesan selepas sebab dinyatakan: “Bekalan elektrik terputus; ___, kelas dalam talian ditangguhkan.”','选择在说明原因后引出结果的连接词：“电力中断；___，线上课程延期。”','[{"id":"a","learning_text":"oleh itu","translation_text":"因此"},{"id":"b","learning_text":"walaupun","translation_text":"虽然"},{"id":"c","learning_text":"sebaliknya","translation_text":"相反"},{"id":"d","learning_text":"misalnya","translation_text":"例如"}]'::jsonb,'a','“Oleh itu” menghubungkan sebab yang dinyatakan dengan kesannya.','“Oleh itu”把前述原因与其结果连接起来。','approved','knowledge','ms','effect-linker',pg_catalog.now()),
('quiz-ms-zh-b105',1,'ms','zh','ms-a-ragam-bahasa','ms-register','advanced','Pilih pembuka surat rasmi yang paling sesuai sebelum menyatakan tujuan surat.','选择在说明信件目的前最合适的正式信件开头。','[{"id":"a","learning_text":"Dengan hormatnya,","translation_text":"谨启／谨此"},{"id":"b","learning_text":"Hai, apa khabar?","translation_text":"嗨，你好吗？"},{"id":"c","learning_text":"Oi, dengar sini.","translation_text":"喂，听着。"},{"id":"d","learning_text":"Aku nak beritahu.","translation_text":"我想告诉你。"}]'::jsonb,'a','“Dengan hormatnya” ialah ungkapan pembuka yang sesuai dalam surat rasmi.','“Dengan hormatnya”适合用作正式信件的开头表达。','approved','knowledge','ms','formal-letter-opening',pg_catalog.now()),
('quiz-ms-zh-b106',1,'ms','zh','ms-a-wacana-penanda','ms-discourse-markers','advanced','Anda mahu merumuskan keseluruhan perbincangan. Penanda wacana manakah paling sesuai?','你想总结整个讨论。哪个篇章连接语最合适？','[{"id":"a","learning_text":"Kesimpulannya","translation_text":"总而言之"},{"id":"b","learning_text":"Selain itu","translation_text":"此外"},{"id":"c","learning_text":"Walaupun","translation_text":"虽然"},{"id":"d","learning_text":"Sebaliknya","translation_text":"相反"}]'::jsonb,'a','“Kesimpulannya” menandakan rumusan atau penutup hujah.','“Kesimpulannya”表示总结或论述结尾。','approved','knowledge','ms','concluding-discourse-marker',pg_catalog.now()),
('quiz-ms-zh-b107',1,'ms','zh','ms-a-penyuntingan','ms-editing','advanced','Pilih ayat yang paling ringkas dan gramatis tanpa frasa berlebihan.','选择最简洁、语法正确且没有多余短语的句子。','[{"id":"a","learning_text":"Mereka membincangkan cadangan itu.","translation_text":"他们讨论了这项建议。"},{"id":"b","learning_text":"Mereka saling berbincang bersama-sama tentang cadangan itu.","translation_text":"他们彼此一起讨论关于这项建议。"},{"id":"c","learning_text":"Mereka membincangkan tentang mengenai cadangan itu.","translation_text":"他们讨论关于有关这项建议。"},{"id":"d","learning_text":"Mereka adalah membincangkan cadangan itu.","translation_text":"他们是讨论这项建议。"}]'::jsonb,'a','Pilih kata kerja yang tepat dan elakkan pengulangan makna seperti “berbincang bersama-sama”.','选择准确的动词，并避免“berbincang bersama-sama”等语义重复的表达。','approved','knowledge','ms','editing-conciseness',pg_catalog.now()),
('quiz-ms-zh-b108',1,'ms','zh','ms-a-ayat-pasif','ms-passive-voice','advanced','Dalam ayat pasif “Keputusan itu diumumkan oleh pengerusi”, apakah fungsi frasa “oleh pengerusi”?','在被动句“Keputusan itu diumumkan oleh pengerusi”中，“oleh pengerusi”有什么作用？','[{"id":"a","learning_text":"Menamakan pelaku perbuatan","translation_text":"指出动作执行者"},{"id":"b","learning_text":"Menamakan tempat kejadian","translation_text":"指出事件地点"},{"id":"c","learning_text":"Menunjukkan masa lampau","translation_text":"表示过去时间"},{"id":"d","learning_text":"Menafikan keputusan","translation_text":"否定决定"}]'::jsonb,'a','Frasa “oleh pengerusi” memperkenalkan pelaku dalam ayat pasif.','“Oleh pengerusi”在被动句中引出动作执行者。','approved','knowledge','ms','passive-agent-phrase',pg_catalog.now()),
('quiz-ms-zh-b109',1,'ms','zh','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Apabila dua organisasi disebut dalam perenggan, apakah cara terbaik mengelakkan kekeliruan tentang pihak yang bertindak?','一段文字中提到两个组织时，怎样最能避免混淆行动主体？','[{"id":"a","learning_text":"Ulang nama organisasi yang dimaksudkan apabila rujukan boleh menjadi kabur.","translation_text":"当指代可能不清楚时，重复写出所指组织的名称。"},{"id":"b","learning_text":"Gunakan “mereka” untuk kedua-dua organisasi tanpa konteks.","translation_text":"不顾语境，对两个组织都使用“他们”。"},{"id":"c","learning_text":"Gugurkan semua subjek daripada ayat.","translation_text":"从句子中删除所有主语。"},{"id":"d","learning_text":"Tukar nama organisasi secara rawak.","translation_text":"随意更改组织名称。"}]'::jsonb,'a','Pengulangan kata nama yang terkawal boleh memperjelas rujukan dalam wacana.','适当地重复名词可以使篇章中的指代更加清楚。','approved','knowledge','ms','cohesive-repetition-reference',pg_catalog.now()),
('quiz-ms-zh-b110',1,'ms','zh','ms-a-variasi-struktur','ms-sentence-variation','advanced','Ayat kedua terlalu kerap bermula dengan subjek yang sama. Pilih suntingan yang mempelbagaikan struktur tanpa mengubah fakta.','第二句反复以相同主语开头。选择一种不改变事实但能丰富句式的修改。','[{"id":"a","learning_text":"Pada minggu berikutnya, program itu diteruskan di daerah lain.","translation_text":"接下来的一周，该计划在另一个县继续开展。"},{"id":"b","learning_text":"Program itu fakta lain dan minggu.","translation_text":"该计划那个事实其他和星期。"},{"id":"c","learning_text":"Buang maklumat tempat daripada kedua-dua ayat.","translation_text":"从两个句子中删除地点信息。"},{"id":"d","learning_text":"Ulang ayat pertama tanpa perubahan.","translation_text":"原样重复第一句。"}]'::jsonb,'a','Frasa keterangan di hadapan ayat boleh mempelbagaikan struktur sambil mengekalkan fakta.','句首的状语短语可以丰富句式，同时保留事实。','approved','knowledge','ms','fronted-phrase-variation',pg_catalog.now()),
('quiz-ms-zh-b111',1,'ms','zh','ms-a-parafrasa','ms-paraphrasing','advanced','Ayat asal: “Pihak sekolah meluluskan permohonan itu.” Parafrasa manakah mengekalkan maksud yang sama?','原句：“校方批准了该申请。”哪种改写保留相同意思？','[{"id":"a","learning_text":"Permohonan itu diluluskan oleh pihak sekolah.","translation_text":"该申请由校方批准。"},{"id":"b","learning_text":"Permohonan itu ditolak oleh pihak sekolah.","translation_text":"该申请被校方拒绝。"},{"id":"c","learning_text":"Pihak sekolah menarik balik permohonan itu.","translation_text":"校方撤回了申请。"},{"id":"d","learning_text":"Permohonan itu meluluskan pihak sekolah.","translation_text":"申请批准了校方。"}]'::jsonb,'a','Pertukaran ayat aktif kepada ayat pasif boleh mengekalkan makna jika peranan pelaku dan penerima tindakan kekal tepat.','只要动作执行者和承受者的关系保持准确，主动句改为被动句仍可保留原意。','approved','knowledge','ms','active-passive-paraphrase',pg_catalog.now()),
('quiz-ms-zh-b112',1,'ms','zh','ms-a-bacaan-kritis','ms-critical-reading','advanced','Dua laman memberikan angka yang berbeza tentang perkara yang sama. Apakah langkah paling wajar sebelum membuat kesimpulan?','两个网站对同一事项给出了不同数据。在得出结论前，最恰当的做法是什么？','[{"id":"a","learning_text":"Bandingkan tarikh, kaedah dan sumber asal bagi kedua-dua angka.","translation_text":"比较两组数据的日期、方法和原始来源。"},{"id":"b","learning_text":"Pilih angka yang paling besar.","translation_text":"选择较大的数字。"},{"id":"c","learning_text":"Pilih laman yang reka bentuknya paling menarik.","translation_text":"选择设计最吸引人的网站。"},{"id":"d","learning_text":"Abaikan semua sumber tanpa menyemaknya.","translation_text":"不核实就忽略所有来源。"}]'::jsonb,'a','Perbezaan data perlu dinilai melalui konteks, kaedah dan sumber asal.','应结合背景、方法和原始来源评估数据差异。','approved','knowledge','ms','cross-source-verification',pg_catalog.now()),
('quiz-ms-zh-b113',1,'ms','zh','ms-a-argument-structure','ms-topic-argument-structure','advanced','Dakwaan menyatakan bahawa kemudahan membaca meningkatkan minat murid. Bukti manakah paling relevan?','论点认为阅读设施能提高学生的阅读兴趣。哪项证据最相关？','[{"id":"a","learning_text":"Data tinjauan minat membaca sebelum dan selepas kemudahan disediakan.","translation_text":"提供设施前后学生阅读兴趣的调查数据。"},{"id":"b","learning_text":"Bilangan kenderaan di tempat letak kereta.","translation_text":"停车场的车辆数量。"},{"id":"c","learning_text":"Warna dinding bangunan sekolah.","translation_text":"学校建筑墙壁的颜色。"},{"id":"d","learning_text":"Senarai nama guru yang bertugas.","translation_text":"值班教师名单。"}]'::jsonb,'a','Bukti yang relevan mengukur perkara yang berkait secara langsung dengan dakwaan.','相关证据应直接衡量与论点有关的事项。','approved','knowledge','ms','evidence-relevance',pg_catalog.now()),
('quiz-ms-zh-b114',1,'ms','zh','ms-a-counterargument-and-rebuttal','ms-topic-counterargument-and-rebuttal','advanced','Apakah cara yang paling berkesan untuk menjawab hujah balas secara adil?','以公平有效的方式回应反方论点，应该怎么做？','[{"id":"a","learning_text":"Akui bahagian yang munasabah, kemudian jawab dengan alasan dan bukti.","translation_text":"承认其中合理的部分，再用理由和证据回应。"},{"id":"b","learning_text":"Ubah maksud hujah pihak lain.","translation_text":"歪曲对方论点的意思。"},{"id":"c","learning_text":"Serang peribadi orang yang mengemukakan hujah.","translation_text":"攻击提出论点的人。"},{"id":"d","learning_text":"Abaikan hujah balas tanpa penjelasan.","translation_text":"不作解释就忽略反方论点。"}]'::jsonb,'a','Jawapan yang adil menangani isi hujah, bukan menyerang individu.','公平的反驳应针对论点内容，而不是攻击个人。','approved','knowledge','ms','acknowledge-counterargument',pg_catalog.now()),
('quiz-ms-zh-b115',1,'ms','zh','ms-a-source-credibility','ms-topic-source-credibility','advanced','Untuk mengetahui tarikh sebenar sesuatu pengumuman kerajaan, sumber manakah patut diperiksa dahulu?','要确认政府公告的实际日期，应该优先查看哪种来源？','[{"id":"a","learning_text":"Pengumuman asal pada portal rasmi agensi berkenaan.","translation_text":"相关机构官方网站上的原始公告。"},{"id":"b","learning_text":"Tangkap layar tanpa pautan yang dikongsi dalam sembang.","translation_text":"聊天中分享的无链接截图。"},{"id":"c","learning_text":"Komen pengguna yang tidak menyertakan bukti.","translation_text":"没有证据的用户评论。"},{"id":"d","learning_text":"Tajuk ringkas daripada akaun yang tidak diketahui.","translation_text":"来自未知账号的简短标题。"}]'::jsonb,'a','Sumber primer rasmi lebih sesuai untuk mengesahkan kandungan dan tarikh pengumuman asal.','官方一手来源更适合核实原始公告的内容和日期。','approved','knowledge','ms','primary-source-identification',pg_catalog.now()),
('quiz-ms-zh-b116',1,'ms','zh','ms-a-kohesi-wacana','ms-discourse-cohesion','advanced','Anda menerangkan langkah kedua selepas langkah pertama. Penanda wacana manakah paling sesuai?','你要在第一步之后说明第二步。哪个篇章连接语最合适？','[{"id":"a","learning_text":"Seterusnya","translation_text":"接下来"},{"id":"b","learning_text":"Walau bagaimanapun","translation_text":"然而"},{"id":"c","learning_text":"Kesimpulannya","translation_text":"总而言之"},{"id":"d","learning_text":"Sebaliknya","translation_text":"相反"}]'::jsonb,'a','“Seterusnya” menandakan langkah atau perkara yang menyusul.','“Seterusnya”表示接下来的步骤或事项。','approved','knowledge','ms','sequence-cohesion-marker',pg_catalog.now()),
('quiz-ms-zh-b117',1,'ms','zh','ms-a-variasi-struktur','ms-sentence-variation','advanced','Dua ayat menerangkan sebab dan hasil. Pilih gabungan yang paling lancar tanpa mengubah hubungan makna.','两个句子说明原因和结果。选择最流畅且不改变逻辑关系的合并方式。','[{"id":"a","learning_text":"Oleh sebab hujan lebat, acara itu ditangguhkan.","translation_text":"由于下大雨，活动延期了。"},{"id":"b","learning_text":"Hujan lebat acara dan ditangguhkan sebab.","translation_text":"大雨活动和延期因为。"},{"id":"c","learning_text":"Acara itu hujan lebat oleh sebab ditangguhkan.","translation_text":"活动大雨因为延期。"},{"id":"d","learning_text":"Ditangguhkan acara itu sebab hujan lebat dan.","translation_text":"延期活动因为大雨和。"}]'::jsonb,'a','Klausa sebab boleh diletakkan di hadapan untuk menghasilkan aliran ayat yang jelas.','原因分句可以置于句首，使句子衔接更清楚。','approved','knowledge','ms','clause-combination-for-flow',pg_catalog.now()),
('quiz-ms-zh-b118',1,'ms','zh','ms-a-parafrasa','ms-paraphrasing','advanced','Pilih parafrasa yang mengekalkan maksud “Pihak itu memberikan bantuan kepada mangsa”.','选择保留“该方为受害者提供援助”意思的改写。','[{"id":"a","learning_text":"Pihak itu membantu mangsa.","translation_text":"该方帮助了受害者。"},{"id":"b","learning_text":"Pihak itu menghalang mangsa.","translation_text":"该方阻碍了受害者。"},{"id":"c","learning_text":"Mangsa memberikan bantuan kepada pihak itu.","translation_text":"受害者帮助了该方。"},{"id":"d","learning_text":"Pihak itu meminta mangsa membayar bantuan.","translation_text":"该方要求受害者为援助付费。"}]'::jsonb,'a','“Memberikan bantuan” boleh diparafrasa sebagai “membantu” tanpa mengubah maksud utama.','“Memberikan bantuan”可以改写为“membantu”，而不改变主要意思。','approved','knowledge','ms','lexical-paraphrase',pg_catalog.now()),
('quiz-ms-zh-b119',1,'ms','zh','ms-a-bacaan-kritis','ms-critical-reading','advanced','Pernyataan manakah merupakan pendapat, bukannya fakta yang boleh disahkan secara langsung?','哪项陈述属于观点，而不是可以直接核实的事实？','[{"id":"a","learning_text":"Perpustakaan itu ialah tempat paling menarik di bandar ini.","translation_text":"那座图书馆是这座城市最有趣的地方。"},{"id":"b","learning_text":"Perpustakaan itu dibuka pada pukul lapan pagi.","translation_text":"图书馆早上八点开放。"},{"id":"c","learning_text":"Bangunan itu mempunyai tiga tingkat.","translation_text":"那栋建筑有三层。"},{"id":"d","learning_text":"Buku tersebut diterbitkan pada tahun 2022.","translation_text":"那本书于2022年出版。"}]'::jsonb,'a','Penilaian seperti “paling menarik” bergantung pada pandangan, manakala tiga pernyataan lain boleh disemak melalui rekod atau pemerhatian.','“最有趣”这类评价取决于个人观点，而其他陈述可以通过记录或观察核实。','approved','knowledge','ms','fact-opinion-distinction',pg_catalog.now()),
('quiz-ms-zh-b120',1,'ms','zh','ms-a-argument-structure','ms-topic-argument-structure','advanced','Susunan manakah membentuk hujah yang jelas dan boleh dinilai?','哪种顺序能构成清晰且可评估的论证？','[{"id":"a","learning_text":"Dakwaan, alasan dan bukti yang relevan.","translation_text":"主张、理由和相关证据。"},{"id":"b","learning_text":"Kesimpulan, serangan peribadi dan andaian.","translation_text":"结论、人身攻击和假设。"},{"id":"c","learning_text":"Contoh rawak, dakwaan baharu dan tajuk.","translation_text":"随机例子、新主张和标题。"},{"id":"d","learning_text":"Pendapat tanpa alasan atau sokongan.","translation_text":"没有理由或支持的观点。"}]'::jsonb,'a','Hujah yang jelas menghubungkan dakwaan dengan alasan serta bukti yang menyokongnya.','清晰的论证会将主张与理由及支持证据联系起来。','approved','knowledge','ms','claim-reason-evidence',pg_catalog.now())
on conflict(question_id,revision) do nothing;
do $assert_malay_quiz_release$
declare v_count integer; v_en integer; v_zh integer; v_bad integer;
begin
 select count(*) into v_count from private.quiz_question_bank where question_id like 'quiz-ms-%' and status='approved';
 select count(*) into v_en from private.quiz_question_bank where question_id like 'quiz-ms-en-%' and status='approved';
 select count(*) into v_zh from private.quiz_question_bank where question_id like 'quiz-ms-zh-%' and status='approved';
 select count(*) into v_bad from private.quiz_question_bank where question_id like 'quiz-ms-%' and (approved_at is null or learning_language_code<>'ms' or answer_language_code<>'ms' or question_type<>'knowledge');
 if v_count<>240 or v_en<>120 or v_zh<>120 or v_bad<>0 then raise exception 'Malay Quiz staging release expected 240 approved records (120 per support language); got total %, en %, zh %, invalid %',v_count,v_en,v_zh,v_bad; end if;
end;
$assert_malay_quiz_release$;
commit;
